//! Semantic allocation metadata and type-isolation compatibility hooks.
//!
//! The paper design extends allocation with compiler-visible object semantics.
//! This module provides the stable in-repository API for that path. The current
//! implementation records coverage and policy decisions, then routes through
//! the existing allocator fast path. Unmodified `GlobalAlloc` callers are
//! counted as fallback allocations unless an explicit scoped-metadata or
//! evaluation-only layout auto-metadata mode is active, so the coverage
//! denominator remains honest by default. Release builds that call semantic
//! allocation APIs must enable the `type_isolation` feature; raw-only release
//! builds leave semantic lifecycle synchronization out of their hot path.

use alloc::boxed::Box as AllocBox;
use alloc::ffi::CString as AllocCString;
use alloc::string::String as AllocString;
use alloc::vec::IntoIter as AllocVecIntoIter;
use alloc::vec::Vec as AllocVec;
use core::alloc::{Allocator, Layout};
use core::mem::size_of;
use core::ptr::NonNull;
use core::sync::atomic::{AtomicBool, AtomicU16, AtomicU64, AtomicUsize, Ordering};

#[cfg(test)]
extern crate std;

use crate::cache::RustAllocator;
#[cfg(not(feature = "fixed_heap"))]
use crate::pal::sys_alloc as system_alloc;
use spin::{Mutex, RwLock};

/// No semantic information was available for this allocation site.
pub const UNKNOWN_SEMANTIC_ID: u64 = 0;
/// Empty side-table records deliberately carry no valid allocation layout.
///
/// Record liveness is determined by the pointer/key/active sentinel before a
/// layout is reconstructed. Keeping the unused layout fields zero makes the
/// static tables demand-zero data instead of a large initialized TLS/image
/// payload for applications that do not enable semantic policies.
const EMPTY_LAYOUT_ALIGN: usize = 0;
const FNV1A_OFFSET: u64 = 0xcbf2_9ce4_8422_2325;
const FNV1A_PRIME: u64 = 0x0000_0100_0000_01b3;
const TYPE_CACHE_SLOTS: usize = 64;
const TYPE_CACHE_PROBE_LIMIT: usize = 4;
/// Direct exact-entry tier for hot compiler-scoped objects below 24 bytes.
///
/// These objects often alternate between only a handful of identities and
/// layouts. Keeping one out-of-line pointer per key avoids both intrusive-list
/// bookkeeping and the richer metadata-segregated bucket machinery.
const SMALL_EXACT_TYPE_CACHE_SLOTS: usize = 8;
/// Maximum linked objects inspected for one exact identity/layout slot.
///
/// Bursty containers can release hundreds of nodes of one exact layout at
/// once. Let that hot identity use a larger share of the existing per-thread
/// budget instead of forcing every object through the synchronized global L2.
/// The aggregate entry and byte caps below preserve the original 4,096-entry
/// registry bound and the 512 KiB total retained-memory bound.
#[cfg(not(feature = "fixed_heap"))]
const MAX_TYPE_CACHE_DEPTH: usize = 1024;
#[cfg(feature = "fixed_heap")]
const MAX_TYPE_CACHE_DEPTH: usize = 64;
/// Per-bucket metadata-segregated cache depth.
///
/// Two inline entries already cover the common alternating pair. Four cold
/// entries per bucket retain bounded reuse without reserving eight full
/// full metadata records in every thread; excess frees safely bypass
/// the cache and return to the ordinary allocator.
#[cfg(not(feature = "fixed_heap"))]
const SEGREGATED_TYPE_CACHE_DEPTH: usize = 4;
/// Fixed-heap targets have no hosted spill mapping and keep the prior cache
/// geometry; this RSS optimization is for hosted per-thread TLS.
#[cfg(feature = "fixed_heap")]
const SEGREGATED_TYPE_CACHE_DEPTH: usize = 8;
const SEGREGATED_TYPE_CACHE_PROBE_LIMIT: usize = 4;
const SEGREGATED_TYPE_CACHE_DOMAIN_ORDINARY: u8 = 0;
const SEGREGATED_TYPE_CACHE_DOMAIN_HUGEPAGE: u8 = 1;
/// Intrusive plain-cache nodes store only the next pointer in freed payload.
/// Exact layout authorization lives in the owning `TypeCacheSlot`, so a
/// word-sized object can use the fast exact-type tier without an out-of-line
/// metadata record.
const TYPE_CACHE_NODE_WORDS: usize = 1;
const DELAYED_FREE_SLOTS: usize = 32;
/// Process-visible ownership records for objects retained in per-thread quarantine rings.
///
/// The retained objects themselves remain thread-local.  This small sharded
/// pointer set exists only to prevent a foreign thread from treating an object
/// still owned by another thread's quarantine as freshly deallocated storage.
const GLOBAL_DELAYED_FREE_OWNERSHIP_SHARD_COUNT: usize = 8;
const GLOBAL_DELAYED_FREE_OWNERSHIP_SHARD_SLOTS: usize = 32;
const GLOBAL_DELAYED_FREE_OWNERSHIP_SHARD_MASK: usize =
    GLOBAL_DELAYED_FREE_OWNERSHIP_SHARD_COUNT - 1;
/// Process-visible ownership records for objects retained in semantic type caches.
///
/// Cache payloads remain thread-local, but ownership must be process-visible so
/// a duplicate free on another thread cannot publish the same address into a
/// second TLS cache. The registry is bounded and allocation-free. A full probe
/// window lets an already-owned delayed-free handoff fall back through its
/// durable source owner; an ordinary semantic deallocation fails closed before
/// release. Both paths prevent untracked ownership.
const GLOBAL_TYPE_CACHE_OWNERSHIP_SHARD_COUNT: usize = 8;
#[cfg(not(feature = "fixed_heap"))]
const GLOBAL_TYPE_CACHE_OWNERSHIP_SHARD_SLOTS: usize = 1024;
#[cfg(feature = "fixed_heap")]
const GLOBAL_TYPE_CACHE_OWNERSHIP_SHARD_SLOTS: usize = 128;
#[cfg(not(feature = "fixed_heap"))]
const GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT: usize = 64;
#[cfg(feature = "fixed_heap")]
const GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT: usize = 32;
const GLOBAL_TYPE_CACHE_OWNERSHIP_SHARD_MASK: usize = GLOBAL_TYPE_CACHE_OWNERSHIP_SHARD_COUNT - 1;
/// Exact-count negative filter for process-visible semantic pointer state.
///
/// Global recovery records and retained T/D ownership contribute to the same
/// counter array. A zero counter proves that no pointer with the same
/// full-address hash is present; a nonzero counter is only a conservative
/// slow-path hint. Counters publish before their record and retire after it, so
/// collisions can add work but can never hide an owner.
#[cfg(not(feature = "fixed_heap"))]
const GLOBAL_SEMANTIC_POINTER_FILTER_SLOTS: usize = 8192;
#[cfg(feature = "fixed_heap")]
const GLOBAL_SEMANTIC_POINTER_FILTER_SLOTS: usize = 1024;
const GLOBAL_SEMANTIC_POINTER_FILTER_MASK: usize = GLOBAL_SEMANTIC_POINTER_FILTER_SLOTS - 1;
/// Keep hosted active lifecycle records below a 37.5% table load.
///
/// A 75% process-wide count can still saturate one 64-slot local probe window:
/// SWC exposed that case as registry churn even though the global table had
/// nominal headroom. The lower hosted target bounds persistent T/depot owners
/// before that clustered-load regime while retaining enough capacity for the
/// measured real-world working sets. The smaller fixed-heap table keeps its
/// existing 75% target and 512-owner retention bound.
#[cfg(not(feature = "fixed_heap"))]
const GLOBAL_ADDRESS_LIFECYCLE_TARGET_OCCUPANCY: usize =
    GLOBAL_TYPE_CACHE_OWNERSHIP_SHARD_COUNT * GLOBAL_TYPE_CACHE_OWNERSHIP_SHARD_SLOTS * 3 / 8;
#[cfg(feature = "fixed_heap")]
const GLOBAL_ADDRESS_LIFECYCLE_TARGET_OCCUPANCY: usize =
    GLOBAL_TYPE_CACHE_OWNERSHIP_SHARD_COUNT * GLOBAL_TYPE_CACHE_OWNERSHIP_SHARD_SLOTS * 3 / 4;
/// Persistent type-cache owners share the lifecycle table with the independent
/// delayed-free registry. Reserve its complete bounded population before
/// deciding how many T/leased records may survive a deallocation.
const GLOBAL_TYPE_CACHE_OWNERSHIP_RETENTION_LIMIT: usize = GLOBAL_ADDRESS_LIFECYCLE_TARGET_OCCUPANCY
    - GLOBAL_DELAYED_FREE_OWNERSHIP_SHARD_COUNT * GLOBAL_DELAYED_FREE_OWNERSHIP_SHARD_SLOTS;
/// Hosted process-wide L2 for exact typed objects that overflow a thread's L1.
///
/// The depot deliberately owns far fewer objects than the hosted lifecycle
/// registry can describe.  It therefore absorbs short producer/consumer
/// bursts without consuming the registry headroom required by per-thread L1s.
#[cfg(not(feature = "fixed_heap"))]
const TYPE_CACHE_DEPOT_SHARD_COUNT: usize = 8;
#[cfg(not(feature = "fixed_heap"))]
const TYPE_CACHE_DEPOT_SHARD_SLOTS: usize = 512;
#[cfg(not(feature = "fixed_heap"))]
const TYPE_CACHE_DEPOT_SHARD_MASK: usize = TYPE_CACHE_DEPOT_SHARD_COUNT - 1;
#[cfg(not(feature = "fixed_heap"))]
const TYPE_CACHE_DEPOT_KEY_SLOTS: usize = 32;
#[cfg(not(feature = "fixed_heap"))]
const TYPE_CACHE_DEPOT_KEY_PROBE_LIMIT: usize = 4;
#[cfg(not(feature = "fixed_heap"))]
const TYPE_CACHE_DEPOT_EMPTY_INDEX: usize = usize::MAX;
#[cfg(not(feature = "fixed_heap"))]
const MAX_TYPE_CACHE_DEPOT_SHARD_BYTES: usize = 64 * 1024;
/// Depot owners use the same authoritative persistent-retention budget as
/// every other T owner. Moving an already-counted T owner between L1 and the
/// depot does not consume another registry record.
#[cfg(not(feature = "fixed_heap"))]
const TYPE_CACHE_DEPOT_REGISTRY_COUNT_LIMIT: usize = GLOBAL_TYPE_CACHE_OWNERSHIP_RETENTION_LIMIT;
const ADDRESS_LIFECYCLE_EMPTY: u8 = 0;
const ADDRESS_LIFECYCLE_PROBE_TOMBSTONE: u8 = 1;
const ADDRESS_LIFECYCLE_TYPE_RETAINED: u8 = 2;
const ADDRESS_LIFECYCLE_DELAYED_RETAINED: u8 = 3;
const ADDRESS_LIFECYCLE_RELEASED: u8 = 4;
const ADDRESS_LIFECYCLE_LIVE: u8 = 5;
/// A live allocation returned by the exact-type cache while its bounded
/// lifecycle-table reservation remains attached to the address.
///
/// Keeping the reservation lets a hot small-object free move directly back to
/// `TYPE_RETAINED` without retiring and recreating two address generations.
const ADDRESS_LIFECYCLE_TYPE_LEASED: u8 = 6;
/// Lease only while total type-cache lifecycle reservations remain within the
/// proven pre-unification bound. Since leased entries remain in
/// `GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT`, this also bounds the leased subset
/// without another atomic counter on the hot path. The 1,266 limit preserves
/// the former 5,888-owner safety envelope after reserving the complete 4,622
/// entry worst-case TLS headroom.
#[cfg(not(feature = "fixed_heap"))]
const TYPE_CACHE_LEASE_REGISTRY_COUNT_LIMIT: usize = 1266;
#[cfg(feature = "fixed_heap")]
const TYPE_CACHE_LEASE_REGISTRY_COUNT_LIMIT: usize = 0;
/// Recent exact-address generations retained after lifecycle entries leave the
/// primary table. Eight-way replacement keeps the raw-only stale-address
/// window allocation-free and bounded while exact keys prevent unrelated hash
/// colliders from being rejected as stale. A ninth distinct key in one history
/// bucket displaces the oldest; a displaced missing address returns to the
/// raw-only epoch-zero contract.
const GLOBAL_ADDRESS_GENERATION_HISTORY_WAYS: usize = 8;
const GLOBAL_ADDRESS_GENERATION_HISTORY_BUCKETS: usize =
    GLOBAL_TYPE_CACHE_OWNERSHIP_SHARD_SLOTS / GLOBAL_ADDRESS_GENERATION_HISTORY_WAYS;
const ADDRESS_GENERATION_HISTORY_EMPTY: u8 = 0;
const ADDRESS_GENERATION_HISTORY_ABSENT: u8 = 1;
const ADDRESS_GENERATION_HISTORY_RETIRED: u8 = 2;
/// Shared ordering for acquisitions that may publish a pointer in either
/// retained-ownership domain.
///
/// The two registries keep independent storage and lookup locks, but competing
/// delayed-free and type-cache acquisitions for the same pointer must have one
/// portable linearization point. Eight pointer-sharded locks keep most
/// unrelated acquisitions independent without relying on cross-atomic
/// observation; hash collisions intentionally share one lock.
const GLOBAL_RETAINED_OWNERSHIP_ARBITRATION_SHARD_COUNT: usize = 8;
const GLOBAL_RETAINED_OWNERSHIP_ARBITRATION_SHARD_MASK: usize =
    GLOBAL_RETAINED_OWNERSHIP_ARBITRATION_SHARD_COUNT - 1;
/// Maximum allocator-rounded bytes retained by one thread's delayed-free quarantine ring.
///
/// Delayed free is a reuse-hardening policy, but retaining 32 large objects can
/// pin multi-megabyte RSS per thread and bypass the allocator's coalescing/unmap
/// paths.  Keep a bounded quarantine for small/medium objects and release
/// over-budget objects through the ordinary deallocation path immediately.
pub const MAX_DELAYED_FREE_RETAINED_BYTES: usize = 256 * 1024;
/// Fast memory-tag records kept in TLS and in the cross-thread global table.
///
/// Memory tagging is a guarded/debug-style policy.  Keeping 1024 full
/// `TaggedAllocation` records in every thread and again in the global table was
/// a large fixed cost for a feature that already has correctness-preserving
/// overflow pages on hosted targets. A hosted 128-entry fast tier stays power-of-two
/// for cheap hashing and is currently 8KiB on 64-bit targets; overflow keeps
/// uncommon high-cardinality tag sets correct without reserving the whole side
/// table up front. Fixed-heap builds retain the prior 256-entry capacity because
/// they cannot allocate hosted overflow pages.
#[cfg(not(feature = "fixed_heap"))]
const MEMORY_TAG_FAST_SLOTS: usize = 128;
#[cfg(feature = "fixed_heap")]
const MEMORY_TAG_FAST_SLOTS: usize = 256;
const MEMORY_TAG_FAST_PROBE_LIMIT: usize = 16;
/// Cross-thread memory-tag records are sharded to avoid one global lock.
///
/// The total fast-tier footprint intentionally stays the same as the TLS table:
/// Hosted builds use 8 shards * 16 records = 128 records and retain cold
/// overflow pages per shard when a bounded probe cannot place a record.
const GLOBAL_MEMORY_TAG_SHARD_COUNT: usize = 8;
const GLOBAL_MEMORY_TAG_SHARD_SLOTS: usize = MEMORY_TAG_FAST_SLOTS / GLOBAL_MEMORY_TAG_SHARD_COUNT;
const GLOBAL_MEMORY_TAG_SHARD_MASK: usize = GLOBAL_MEMORY_TAG_SHARD_COUNT - 1;
const GLOBAL_MEMORY_TAG_FAST_PROBE_LIMIT: usize = 16;
#[cfg(not(feature = "fixed_heap"))]
/// Cold overflow capacity for memory-tag records.
///
/// Overflow pages are allocated only after the bounded fast probe cannot place a
/// record.  128 entries keep the first spill page small (about 8KiB of records)
/// while still amortizing mmap cost for bursts.
const MEMORY_TAG_PAGE_SLOTS: usize = 128;
const AUTO_ALLOCATION_RECORD_SLOTS: usize = 4096;
const AUTO_ALLOCATION_RECORD_SHARD_COUNT: usize = 8;
const AUTO_ALLOCATION_RECORD_SHARD_SLOTS: usize =
    AUTO_ALLOCATION_RECORD_SLOTS / AUTO_ALLOCATION_RECORD_SHARD_COUNT;
const AUTO_ALLOCATION_RECORD_PROBE_LIMIT: usize = 16;
const AUTO_ALLOCATION_RECORD_SHARD_MASK: usize = AUTO_ALLOCATION_RECORD_SHARD_COUNT - 1;
const AUTO_ALLOCATION_RECORD_TOMBSTONE_PTR: usize = usize::MAX;
/// Global recovery records reserve the high alignment bit as an independently
/// authoritative integrity-policy marker. Non-zero allocation layouts cannot
/// use this bit because their padded size must remain within `isize::MAX`.
const AUTO_ALLOCATION_RECORD_INTEGRITY_ALIGN_BIT: usize = 1usize << (usize::BITS - 1);
#[cfg(not(feature = "fixed_heap"))]
const AUTO_ALLOCATION_RECORD_OVERFLOW_INITIAL_CAPACITY: usize = 512;
#[cfg(not(feature = "fixed_heap"))]
const AUTO_ALLOCATION_RECORD_OVERFLOW_LOAD_NUMERATOR: usize = 3;
#[cfg(not(feature = "fixed_heap"))]
const AUTO_ALLOCATION_RECORD_OVERFLOW_LOAD_DENOMINATOR: usize = 4;
#[cfg(not(feature = "fixed_heap"))]
/// Maximum empty recovery-overflow mapping retained by each shard.
///
/// Repeated compiler workloads refill the same cross-thread recovery shards.
/// Keeping one zeroed high-water mapping per shard avoids rebuilding every OA
/// growth level on the next burst while bounding process-wide retention to
/// 8MiB across the eight shards. Larger tiers also need at least 25% use in
/// the drained burst and survive one following shard phase; an inline-only
/// following phase sheds the obsolete high-water mapping at quiescence.
const AUTO_ALLOCATION_RECORD_OVERFLOW_RETAINED_MAPPING_MAX_BYTES: usize = 1024 * 1024;
/// Same-thread compiler recovery is a TLS cache, not the full side table.
///
/// Keep the hosted tier deliberately small (128 records, currently 8KiB on 64-bit targets)
/// so every thread does not reserve a large fixed recovery table just because
/// type-isolation support is compiled in.  When this bounded cache is full the
/// existing sharded global recovery table remains the correctness-preserving
/// spill path. Fixed-heap builds keep the prior 256-record fast tier.
#[cfg(not(feature = "fixed_heap"))]
const FAST_AUTO_ALLOCATION_RECORD_SLOTS: usize = 128;
#[cfg(feature = "fixed_heap")]
const FAST_AUTO_ALLOCATION_RECORD_SLOTS: usize = 256;
const FAST_AUTO_ALLOCATION_RECORD_PROBE_LIMIT: usize = 4;
const SEMANTIC_TYPE_STATS_SLOTS: usize = 512;
const SEMANTIC_TYPE_STATS_SHARD_COUNT: usize = 8;
const SEMANTIC_TYPE_STATS_SHARD_SLOTS: usize =
    SEMANTIC_TYPE_STATS_SLOTS / SEMANTIC_TYPE_STATS_SHARD_COUNT;
const SEMANTIC_SCOPE_STACK_CAPACITY: usize = 64;
const SEMANTIC_SCOPE_OVERFLOW_STACK_CAPACITY: usize = 64;
const GUARD_PAGE_MIN_OBJECT_SIZE: usize = crate::PAGE_SIZE;
const SEGREGATED_TYPE_CACHE_POLICY_MASK: u32 = FLAG_METADATA_SEGREGATED
    | FLAG_HUGEPAGE_METADATA
    | FLAG_POINTER_AUTH
    | FLAG_METADATA_PROTECTION;
#[cfg(not(feature = "fixed_heap"))]
const HUGEPAGE_METADATA_MAPPING_GRANULARITY: usize = 2 * 1024 * 1024;

/// Minimum typed object size that can be cached by the type-isolated frontend.
pub const MIN_TYPE_CACHE_OBJECT_SIZE: usize = TYPE_CACHE_NODE_WORDS * size_of::<usize>();
/// Maximum object size retained by semantic type caches.
///
/// The semantic cache is a per-thread/per-type hot reuse tier.  Keeping very
/// large objects here can pin substantially more RSS than the ordinary allocator
/// thread-cache target, and it bypasses the slab/freelist coalescing policies
/// that handle large cold objects.  Match the thread-cache post-flush hot target
/// (64 KiB) so semantic reuse stays a hot-object optimization instead of a large
/// object retention mechanism.
pub const MAX_TYPE_CACHE_OBJECT_SIZE: usize = 64 * 1024;
/// Maximum cold linked-list bytes retained behind one plain semantic type slot.
///
/// `MAX_TYPE_CACHE_DEPTH` protects the number of cached objects, but a single
/// semantic type can otherwise retain many medium objects. Keep the inline
/// one-object hot path, then allow a hot exact layout to consume at most one
/// quarter of the 512 KiB aggregate plain-cache budget. The cap is enforced by
/// a small per-slot byte counter so typed deallocation stays O(1) instead of
/// scanning the linked cache on every push.
#[cfg(not(feature = "fixed_heap"))]
pub const MAX_TYPE_CACHE_SLOT_BYTES: usize = 128 * 1024;
#[cfg(feature = "fixed_heap")]
pub const MAX_TYPE_CACHE_SLOT_BYTES: usize = 64 * 1024;
/// Maximum allocator-rounded bytes retained by one thread's plain semantic cache.
///
/// Per-slot caps prevent one type/layout from retaining too many objects, but a
/// workload with many distinct semantic identities can otherwise keep every TLS
/// slot just below its own cap.  Keep the plain cache as a bounded hot reuse
/// tier across all slots; overflowed frees fall back to the ordinary allocator
/// deallocation path instead of being privately retained by one thread.
pub const MAX_PLAIN_TYPE_CACHE_RETAINED_BYTES: usize = 512 * 1024;
/// Maximum linked plain-cache owners retained by one thread across all slots.
///
/// This preserves the former 64-slot x 64-node ownership ceiling while letting
/// a single hot exact layout absorb a bounded burst. The process-visible
/// registry therefore sees no larger per-thread worst case than before.
pub const MAX_PLAIN_TYPE_CACHE_RETAINED_ENTRIES: usize = 4096;
/// Maximum plain semantic-cache owners kept by one receiving thread after an
/// actual foreign-thread recovery.
///
/// Cross-thread frees already pay process-visible recovery and lifecycle
/// authentication. Preserve a small exact-reuse window, then terminally
/// release authenticated overflow instead of extending its lifetime in the
/// synchronized process-wide depot.
const MAX_CROSS_THREAD_RECOVERY_PLAIN_CACHE_RETAINED_ENTRIES: usize = 64;
/// Maximum allocator-rounded bytes retained by one metadata-segregated semantic cache bucket.
///
/// Side-table entries carry richer metadata and are stored in bounded buckets
/// instead of an in-object linked list.  Keep the same hot retained-byte target
/// as the plain semantic cache so one policy bucket cannot pin many medium
/// objects merely because its count is still below `SEGREGATED_TYPE_CACHE_DEPTH`.
pub const MAX_SEGREGATED_TYPE_CACHE_BUCKET_BYTES: usize = 64 * 1024;
/// Maximum allocator-rounded bytes retained by one thread's metadata-segregated cache.
///
/// Bucket caps bound each policy/layout group, but many distinct semantic keys
/// can otherwise spread across the TLS bucket table.  Keep the side-table cache
/// as a bounded hot reuse tier just like the plain semantic cache.
pub const MAX_SEGREGATED_TYPE_CACHE_RETAINED_BYTES: usize = 512 * 1024;
const TYPE_CACHE_NODE_ALIGN: usize = core::mem::align_of::<usize>();

#[inline]
fn allocator_retained_bytes_for_object(size: usize) -> usize {
    if size == 0 {
        0
    } else {
        crate::size_class::get_rounded_size(size)
    }
}

#[inline]
fn type_cache_retained_bytes_for_object(size: usize) -> usize {
    allocator_retained_bytes_for_object(size)
}

#[inline]
fn type_cache_retained_bytes_for_layout(layout: Layout) -> usize {
    type_cache_retained_bytes_for_object(layout.size())
}

#[inline]
fn delayed_free_retained_bytes_for_object(size: usize) -> usize {
    allocator_retained_bytes_for_object(size)
}

#[inline]
fn delayed_free_retained_bytes_for_layout(layout: Layout) -> usize {
    delayed_free_retained_bytes_for_object(layout.size())
}

/// Module id used by runtime layout auto-metadata when callers do not provide
/// a more specific module/context identifier.
pub const AUTO_LAYOUT_MODULE_ID: u64 = 0x554e_4941_5554_4f4d; // "UNIAUTOM"

/// Internal placement hint used to mark metadata synthesized from a `Layout`.
///
/// Layout-derived ids are useful for unmodified benchmark coverage accounting,
/// but they are not exact compiler-assigned type ids. Multiple unrelated Rust
/// types can share the same `(size, align)`, so this marker keeps them out of
/// exact type-cache reuse while still preserving typed coverage statistics.
const LAYOUT_DERIVED_PLACEMENT_HINT: u16 = 0xA770;

/// Compiler hint bit requesting thread-independent recovery metadata.
///
/// Rustc lowering can set this bit when escape analysis cannot prove that an
/// allocated heap object is freed on the allocating thread.  The allocator then
/// records the pointer-to-metadata entry in the process-visible recovery table
/// instead of the same-thread TLS fast table, preserving exact typed
/// deallocation for cross-thread drops without penalizing the default
/// single-thread compiler fast path.
pub const PLACEMENT_HINT_CROSS_THREAD_RECOVERY: u16 = 1 << 15;

/// Compiler-local scope hint: allocation and matching drop/realloc scopes are
/// both MIR-rewritten, so ordinary `GlobalAlloc` calls inside the scope do not
/// need a pointer-to-metadata recovery record.
///
/// Cross-thread recovery takes precedence if both bits are present; local
/// elision is only sound when the compiler keeps the object lifetime paired
/// inside the same thread/context.
pub const PLACEMENT_HINT_LOCAL_SCOPE_NO_RECOVERY: u16 = 1 << 14;

/// Prototype lifetime class for allocations expected to die before the next
/// long-lived phase boundary.
///
/// The compiler/runtime ABI has always transported the complete `u16` value.
/// These legacy values retain their original policy semantics. Compiler-proven
/// values use a separate range below so an opt-in runtime can distinguish exact
/// proof from an advisory/profile class without changing existing callers.
pub const LIFETIME_HINT_EPHEMERAL: u16 = 1;

/// Prototype lifetime class for allocations expected to span multiple phases
/// and benefit from dense placement on a long-lived hugepage arena.
pub const LIFETIME_HINT_LONG_LIVED: u16 = 2;

/// Reserved compiler fact for a locally owned allocation with a discovered
/// Drop path. Drop topology carries no pressure-relative Short claim, so every
/// placement classifier treats this value as `Unknown`.
pub const LIFETIME_HINT_LOCAL_DROP_FACT: u16 = 0xA101;

/// Bounded mechanism oracle for allocations whose owner is deliberately leaked
/// or forgotten on every accepted path. This value supports controlled routing
/// experiments; real-program Long classification comes from runtime outcomes.
pub const LIFETIME_HINT_BOUNDED_PROCESS_LONG: u16 = 0xA102;

/// Compiler-authenticated request to observe an exact dynamic Global Vec or
/// String buffer site. Covered scopes are borrowed `Vec::reserve*` and owned
/// `Vec/String::with_capacity` with an existing Return/Escape ownership proof.
/// This tag carries no placement class: adaptive runtime policy may sample an
/// admitted 4--32 KiB allocation on ordinary pages, and only a runtime-
/// confirmed Long prediction may later select Long placement.
pub const LIFETIME_HINT_DYNAMIC_BUFFER_OBSERVE: u16 = 0xA103;

/// Compatibility alias for the first compiler rule that emitted the generic
/// dynamic-buffer observation tag.
pub const LIFETIME_HINT_BORROWED_VEC_RESERVE_OBSERVE: u16 = LIFETIME_HINT_DYNAMIC_BUFFER_OBSERVE;

/// Compatibility name for the reserved local-Drop fact. The value classifies
/// as `Unknown` and must not authorize ephemeral placement.
pub const LIFETIME_HINT_PROVEN_EPHEMERAL: u16 = LIFETIME_HINT_LOCAL_DROP_FACT;

/// Compatibility name for the bounded process-long mechanism oracle.
pub const LIFETIME_HINT_PROVEN_LONG_LIVED: u16 = LIFETIME_HINT_BOUNDED_PROCESS_LONG;

/// Placement class understood by the prototype lifetime/hugepage policy.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[repr(u8)]
pub enum LifetimePlacementClass {
    Unknown = 0,
    Ephemeral = 1,
    LongLived = 2,
}

/// Interpret an ABI lifetime hint without assigning policy to legacy/custom
/// values. This exact-match rule keeps existing hint identities unchanged.
#[inline]
pub const fn lifetime_placement_class(lifetime_hint: u16) -> LifetimePlacementClass {
    match lifetime_hint {
        LIFETIME_HINT_EPHEMERAL => LifetimePlacementClass::Ephemeral,
        LIFETIME_HINT_LONG_LIVED | LIFETIME_HINT_BOUNDED_PROCESS_LONG => {
            LifetimePlacementClass::LongLived
        }
        _ => LifetimePlacementClass::Unknown,
    }
}

/// Interpret only the bounded compiler mechanism oracle. Legacy/advisory hints
/// and local-Drop facts resolve to `Unknown`; runtime ground truth supplies
/// performance-lifetime labels for real programs.
#[inline]
pub const fn compiler_bounded_lifetime_placement_class(
    lifetime_hint: u16,
) -> LifetimePlacementClass {
    match lifetime_hint {
        LIFETIME_HINT_BOUNDED_PROCESS_LONG => LifetimePlacementClass::LongLived,
        _ => LifetimePlacementClass::Unknown,
    }
}

/// Route covered objects through type-isolated policy state.
pub const FLAG_TYPE_ISOLATED: u32 = 1 << 0;
/// Store allocator metadata out-of-line when the selected backend supports it.
pub const FLAG_METADATA_SEGREGATED: u32 = 1 << 1;
/// Prefer metadata placement backed by huge pages.
pub const FLAG_HUGEPAGE_METADATA: u32 = 1 << 2;
/// Zero or otherwise initialize memory on allocation/deallocation.
pub const FLAG_FORCE_INITIALIZE: u32 = 1 << 3;
/// Delay reuse of freed objects.
pub const FLAG_DELAYED_FREE: u32 = 1 << 4;
/// Enable guard-page placement for large/high-risk objects.
pub const FLAG_GUARD_PAGES: u32 = 1 << 5;
/// Hardware/software pointer authentication is desired for metadata pointers.
pub const FLAG_POINTER_AUTH: u32 = 1 << 6;
/// Hardware/software memory tagging is desired for this allocation.
pub const FLAG_MEMORY_TAGGING: u32 = 1 << 7;
/// Hardware/software metadata write protection is desired.
pub const FLAG_METADATA_PROTECTION: u32 = 1 << 8;

/// Compiler- or caller-provided allocation semantics.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[repr(C)]
pub struct AllocationMetadata {
    /// Stable compiler-assigned object type id. Zero means unknown/fallback.
    pub type_id: u64,
    /// Optional module/crate/context id. Zero means unknown/fallback.
    pub module_id: u64,
    /// Policy flags requested for this allocation site.
    pub flags: u32,
    /// Optional lifetime/class hint for future placement policies.
    pub lifetime_hint: u16,
    /// Optional alignment/placement class hint for future backends.
    pub placement_hint: u16,
    /// Optional callsite hash for coverage/debug accounting.
    pub callsite: u64,
}

impl AllocationMetadata {
    pub const fn unknown() -> Self {
        Self {
            type_id: UNKNOWN_SEMANTIC_ID,
            module_id: UNKNOWN_SEMANTIC_ID,
            flags: 0,
            lifetime_hint: 0,
            placement_hint: 0,
            callsite: 0,
        }
    }

    pub const fn for_type(type_id: u64) -> Self {
        Self {
            type_id,
            module_id: UNKNOWN_SEMANTIC_ID,
            flags: FLAG_TYPE_ISOLATED,
            lifetime_hint: 0,
            placement_hint: 0,
            callsite: 0,
        }
    }

    pub fn for_rust_type<T: 'static>() -> Self {
        Self::for_type(semantic_type_id::<T>())
    }

    pub const fn with_flags(mut self, flags: u32) -> Self {
        self.flags = flags;
        self
    }

    pub const fn with_module(mut self, module_id: u64) -> Self {
        self.module_id = module_id;
        self
    }

    pub const fn with_callsite(mut self, callsite: u64) -> Self {
        self.callsite = callsite;
        self
    }

    pub const fn with_lifetime_hint(mut self, lifetime_hint: u16) -> Self {
        self.lifetime_hint = lifetime_hint;
        self
    }

    pub const fn with_placement_hint(mut self, placement_hint: u16) -> Self {
        self.placement_hint = placement_hint;
        self
    }

    pub const fn has_type(self) -> bool {
        self.type_id != UNKNOWN_SEMANTIC_ID
    }

    pub const fn requests(self, flag: u32) -> bool {
        (self.flags & flag) != 0
    }

    pub const fn is_layout_derived(self) -> bool {
        self.placement_hint == LAYOUT_DERIVED_PLACEMENT_HINT
    }
}

#[inline]
fn fnv1a_mix(mut hash: u64, bytes: &[u8]) -> u64 {
    for byte in bytes {
        hash ^= *byte as u64;
        hash = hash.wrapping_mul(FNV1A_PRIME);
    }
    hash
}

#[inline]
fn non_zero_hash(hash: u64) -> u64 {
    if hash == UNKNOWN_SEMANTIC_ID {
        FNV1A_OFFSET
    } else {
        hash
    }
}

struct SemanticTypeIdHasher(u64);

impl core::hash::Hasher for SemanticTypeIdHasher {
    #[inline]
    fn finish(&self) -> u64 {
        self.0
    }

    #[inline]
    fn write(&mut self, bytes: &[u8]) {
        self.0 = fnv1a_mix(self.0, bytes);
    }
}

#[inline]
fn mix_semantic_metadata_fields(
    hash: u64,
    metadata: AllocationMetadata,
    include_callsite: bool,
) -> u64 {
    let hash = fnv1a_mix(hash, &metadata.type_id.to_le_bytes());
    let hash = fnv1a_mix(hash, &metadata.module_id.to_le_bytes());
    let hash = fnv1a_mix(hash, &metadata.flags.to_le_bytes());
    let hash = fnv1a_mix(hash, &metadata.lifetime_hint.to_le_bytes());
    let hash = fnv1a_mix(hash, &metadata.placement_hint.to_le_bytes());
    if include_callsite {
        fnv1a_mix(hash, &metadata.callsite.to_le_bytes())
    } else {
        hash
    }
}

/// Derive a non-zero, compiler-disambiguated semantic id for a Rust type.
///
/// The compiler intrinsic is evaluated after generic monomorphization. Its
/// opaque `TypeId` includes crate disambiguation, so identically named types
/// from two dependency versions remain distinct. Hashing that value into the
/// allocator's 64-bit metadata field gives compiler-inserted generic scopes and
/// in-tree manual instrumentation one process-local identity contract without
/// hashing unresolved `T`/`K`/`V` placeholder text.
pub fn semantic_type_id<T: 'static>() -> u64 {
    let compiler_type_id = const { core::intrinsics::type_id::<T>() };
    let mut hasher = SemanticTypeIdHasher(fnv1a_mix(FNV1A_OFFSET, b"rust-type-id-v2"));
    core::hash::Hash::hash(&compiler_type_id, &mut hasher);
    non_zero_hash(core::hash::Hasher::finish(&hasher))
}

/// Deterministically derive a non-zero semantic id from allocation layout.
///
/// This is intentionally an evaluation/runtime compatibility helper, not a
/// replacement for compiler-assigned type metadata. Many Rust types share a
/// `(size, align)` pair, so layout IDs are useful for unmodified benchmark smoke
/// coverage and upper-bound accounting only. Claim-grade C002 evidence must
/// still come from compiler/runtime type metadata.
pub fn semantic_layout_id(size: usize, align: usize) -> u64 {
    let hash = fnv1a_mix(FNV1A_OFFSET, b"layout-auto-v1");
    let hash = fnv1a_mix(hash, &size.to_le_bytes());
    let hash = fnv1a_mix(hash, &align.to_le_bytes());
    non_zero_hash(hash)
}

impl Default for AllocationMetadata {
    fn default() -> Self {
        Self::unknown()
    }
}

