#[derive(Clone, Copy)]
struct MetadataRecordAuthHotSlot {
    seed: u64,
    ptr: usize,
    size: usize,
    align: usize,
    metadata: AllocationMetadata,
    auth: u64,
    active: bool,
}

impl MetadataRecordAuthHotSlot {
    const fn empty() -> Self {
        Self {
            seed: 0,
            ptr: 0,
            size: 0,
            align: EMPTY_LAYOUT_ALIGN,
            metadata: AllocationMetadata::unknown(),
            auth: 0,
            active: false,
        }
    }

    #[inline]
    fn matches(
        self,
        seed: u64,
        ptr: *mut u8,
        layout: Layout,
        metadata: AllocationMetadata,
    ) -> bool {
        self.active
            && self.seed == seed
            && self.ptr == ptr as usize
            && self.size == layout.size()
            && self.align == layout.align()
            && self.metadata == metadata
    }
}

#[derive(Clone, Copy)]
struct InlineTypeCacheEntry {
    cache_key: u64,
    identity: TypeCacheIdentity,
    ptr: *mut u8,
    size: usize,
    align: usize,
}

impl InlineTypeCacheEntry {
    const fn empty() -> Self {
        Self {
            cache_key: UNKNOWN_SEMANTIC_ID,
            identity: TypeCacheIdentity::unknown(),
            ptr: core::ptr::null_mut(),
            size: 0,
            align: EMPTY_LAYOUT_ALIGN,
        }
    }

    #[inline]
    fn is_empty(self) -> bool {
        self.ptr.is_null()
    }

    #[inline]
    fn matches(self, layout: Layout, metadata: AllocationMetadata) -> bool {
        self.matches_cached_key(layout, metadata, type_cache_identity_key(metadata))
    }

    #[inline]
    fn matches_cached_key(
        self,
        layout: Layout,
        metadata: AllocationMetadata,
        cache_key: u64,
    ) -> bool {
        self.cache_key == cache_key
            && self.identity == TypeCacheIdentity::from_metadata(metadata)
            && self.size == layout.size()
            && self.align == layout.align()
            && !self.ptr.is_null()
    }

    #[inline]
    fn retained_bytes(self) -> usize {
        type_cache_retained_bytes_for_object(self.size)
    }
}

#[thread_local]
static mut TYPE_CACHE: [TypeCacheSlot; TYPE_CACHE_SLOTS] =
    [TypeCacheSlot::empty(); TYPE_CACHE_SLOTS];

// Allocator-rounded bytes owned by the linked (non-inline) plain type-cache
// slots.  The inline entry is deliberately accounted at the call site: it is
// a single O(1) value and changes independently of the linked-slot table.
//
// The counter starts untrusted so the first cold-cache growth after a reset
// rebuilds it from the bounded table.  Healthy push/pop operations then update
// it exactly, avoiding a 64-slot aggregate scan on every typed free.  Any
// observed slot corruption or accounting repair marks it untrusted again; no
// further cache growth is accepted until one bounded rebuild proves the
// remaining visible table state is consistent.
#[thread_local]
static mut PLAIN_TYPE_CACHE_RETAINED_BYTES: usize = 0;

// Linked plain-cache owners represented by `PLAIN_TYPE_CACHE_RETAINED_BYTES`.
// The inline object consumes aggregate byte budget directly at admission but
// consumes no linked-entry budget.
#[thread_local]
static mut PLAIN_TYPE_CACHE_RETAINED_ENTRIES: usize = 0;

#[thread_local]
static mut PLAIN_TYPE_CACHE_RETAINED_BYTES_TRUSTED: bool = false;

#[thread_local]
static mut TYPE_CACHE_HOT_SLOT: TypeCacheHotSlot = TypeCacheHotSlot::empty();

#[thread_local]
static mut TYPE_CACHE_IDENTITY_HOT_SLOT: TypeCacheIdentityHotSlot =
    TypeCacheIdentityHotSlot::empty();

#[cfg(not(unialloc_target_arm64e))]
#[thread_local]
static mut METADATA_RECORD_AUTH_HOT_SLOT: MetadataRecordAuthHotSlot =
    MetadataRecordAuthHotSlot::empty();

#[cfg(test)]
static TYPE_CACHE_IDENTITY_HOT_HITS: AtomicUsize = AtomicUsize::new(0);

#[cfg(test)]
static PLAIN_TYPE_CACHE_AGGREGATE_SCANS: AtomicUsize = AtomicUsize::new(0);

#[thread_local]
static mut INLINE_TYPE_CACHE_ENTRY: InlineTypeCacheEntry = InlineTypeCacheEntry::empty();

#[thread_local]
static mut SMALL_EXACT_TYPE_CACHE: [InlineTypeCacheEntry; SMALL_EXACT_TYPE_CACHE_SLOTS] =
    [InlineTypeCacheEntry::empty(); SMALL_EXACT_TYPE_CACHE_SLOTS];

#[thread_local]
static mut SMALL_EXACT_TYPE_CACHE_OCCUPIED: usize = 0;

#[thread_local]
static mut SMALL_EXACT_TYPE_CACHE_RETAINED_BYTES: usize = 0;

#[thread_local]
static mut SMALL_EXACT_TYPE_CACHE_HOT_SLOT: TypeCacheHotSlot = TypeCacheHotSlot::empty();

#[derive(Clone, Copy)]
struct SegregatedTypeCacheEntry {
    cache_key: u64,
    structural_auth: u64,
    policy_key: u32,
    ptr: *mut u8,
    size: usize,
    align: usize,
    auth: u64,
    metadata: AllocationMetadata,
}

impl SegregatedTypeCacheEntry {
    const fn empty() -> Self {
        Self {
            cache_key: UNKNOWN_SEMANTIC_ID,
            structural_auth: 0,
            policy_key: 0,
            ptr: core::ptr::null_mut(),
            size: 0,
            align: EMPTY_LAYOUT_ALIGN,
            auth: 0,
            metadata: AllocationMetadata::unknown(),
        }
    }

    #[inline]
    fn new(
        cache_key: u64,
        policy_key: u32,
        ptr: *mut u8,
        layout: Layout,
        metadata: AllocationMetadata,
    ) -> Self {
        let type_id = metadata.type_id;
        let auth = metadata_record_auth(ptr, layout, metadata);
        Self {
            cache_key,
            structural_auth: derive_segregated_type_cache_structural_auth(
                cache_key, type_id, policy_key, ptr, layout, auth, metadata,
            ),
            policy_key,
            ptr,
            size: layout.size(),
            align: layout.align(),
            auth,
            metadata,
        }
    }

    fn is_empty(self) -> bool {
        if !self.ptr.is_null() {
            return false;
        }
        if self.cache_key != UNKNOWN_SEMANTIC_ID
            || self.structural_auth != 0
            || self.policy_key != 0
            || self.size != 0
            || self.align != EMPTY_LAYOUT_ALIGN
            || self.auth != 0
            || self.metadata != AllocationMetadata::unknown()
        {
            panic!("metadata integrity check failed");
        }
        true
    }

    #[inline]
    fn validate_structural_integrity(self) {
        if self.is_empty() {
            return;
        }

        let stored_layout = checked_side_table_layout(self.size, self.align, "segregated metadata");
        if self.policy_key != segregated_type_cache_policy_key(self.metadata)
            || self.structural_auth
                != derive_segregated_type_cache_structural_auth(
                    self.cache_key,
                    self.metadata.type_id,
                    self.policy_key,
                    self.ptr,
                    stored_layout,
                    self.auth,
                    self.metadata,
                )
        {
            panic!("metadata integrity check failed");
        }
    }

    #[inline]
    fn matches_cached_key(
        self,
        layout: Layout,
        identity: TypeCacheIdentity,
        cache_key: u64,
        policy_key: u32,
    ) -> bool {
        if self.is_empty() {
            return false;
        }
        // Authenticate every occupied candidate before any discriminator is
        // allowed to turn it into a hit or miss.  Otherwise a corrupted key,
        // layout, policy, or identity could make a protected entry invisible.
        self.validate_structural_integrity();

        // The hash is only a lookup accelerator.  Exact reuse also binds the
        // allocator-visible identity; TypeCacheIdentity intentionally omits
        // callsite so allocation and Drop sites for one owner can still pair.
        if self.cache_key != cache_key
            || self.size != layout.size()
            || self.align != layout.align()
            || self.ptr.is_null()
            || self.policy_key != policy_key
        {
            return false;
        }

        TypeCacheIdentity::from_metadata(self.metadata) == identity
    }

    #[inline]
    fn retained_bytes(self) -> usize {
        type_cache_retained_bytes_for_object(self.size)
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum TypeCacheDepotSource {
    ProbeWindowFull,
    SlotDepth,
    SlotByteBudget,
    AggregateByteBudget,
    AggregateEntryBudget,
    SegregatedCapacity,
    LocalEviction,
}

#[cfg(not(feature = "fixed_heap"))]
#[derive(Clone, Copy)]
struct TypeCacheDepotKeySlot {
    cache_key: u64,
    identity: TypeCacheIdentity,
    policy_key: u32,
    size: usize,
    align: usize,
    head: usize,
    count: usize,
    active: bool,
}

#[cfg(not(feature = "fixed_heap"))]
impl TypeCacheDepotKeySlot {
    const fn empty() -> Self {
        Self {
            cache_key: UNKNOWN_SEMANTIC_ID,
            identity: TypeCacheIdentity::unknown(),
            policy_key: 0,
            size: 0,
            align: EMPTY_LAYOUT_ALIGN,
            head: TYPE_CACHE_DEPOT_EMPTY_INDEX,
            count: 0,
            active: false,
        }
    }

    fn matches(
        self,
        layout: Layout,
        identity: TypeCacheIdentity,
        cache_key: u64,
        policy_key: u32,
    ) -> bool {
        self.active
            && self.cache_key == cache_key
            && self.identity == identity
            && self.policy_key == policy_key
            && self.size == layout.size()
            && self.align == layout.align()
    }
}

#[cfg(not(feature = "fixed_heap"))]
struct TypeCacheDepotShard {
    entries: [SegregatedTypeCacheEntry; TYPE_CACHE_DEPOT_SHARD_SLOTS],
    next: [usize; TYPE_CACHE_DEPOT_SHARD_SLOTS],
    keys: [TypeCacheDepotKeySlot; TYPE_CACHE_DEPOT_KEY_SLOTS],
    count: usize,
    retained_bytes: usize,
    free_cursor: usize,
}

#[cfg(not(feature = "fixed_heap"))]
impl TypeCacheDepotShard {
    const fn empty() -> Self {
        Self {
            entries: [SegregatedTypeCacheEntry::empty(); TYPE_CACHE_DEPOT_SHARD_SLOTS],
            next: [TYPE_CACHE_DEPOT_EMPTY_INDEX; TYPE_CACHE_DEPOT_SHARD_SLOTS],
            keys: [TypeCacheDepotKeySlot::empty(); TYPE_CACHE_DEPOT_KEY_SLOTS],
            count: 0,
            retained_bytes: 0,
            free_cursor: 0,
        }
    }

    fn find_free_entry(&self) -> Option<usize> {
        let mut offset = 0usize;
        while offset < TYPE_CACHE_DEPOT_SHARD_SLOTS {
            let idx = (self.free_cursor + offset) & (TYPE_CACHE_DEPOT_SHARD_SLOTS - 1);
            if self.entries[idx].is_empty() {
                return Some(idx);
            }
            offset += 1;
        }
        None
    }

    fn push(
        &mut self,
        entry: SegregatedTypeCacheEntry,
        key_start: usize,
    ) -> Result<Option<SegregatedTypeCacheEntry>, ()> {
        entry.validate_structural_integrity();
        if entry.is_empty() {
            return Err(());
        }
        let incoming_bytes = entry.retained_bytes();
        if incoming_bytes > MAX_TYPE_CACHE_DEPOT_SHARD_BYTES {
            return Err(());
        }

        let layout = checked_side_table_layout(entry.size, entry.align, "type-cache depot");
        let identity = TypeCacheIdentity::from_metadata(entry.metadata);
        let mut matching_key = None;
        let mut empty_key = None;
        let mut offset = 0usize;
        while offset < TYPE_CACHE_DEPOT_KEY_PROBE_LIMIT {
            let idx = (key_start + offset) & (TYPE_CACHE_DEPOT_KEY_SLOTS - 1);
            let key = self.keys[idx];
            if key.matches(layout, identity, entry.cache_key, entry.policy_key) {
                matching_key = Some(idx);
                break;
            }
            if !key.active && empty_key.is_none() {
                empty_key = Some(idx);
            }
            offset += 1;
        }

        let key_idx = match matching_key.or(empty_key) {
            Some(idx) => idx,
            None => return Err(()),
        };
        let free_entry = if self.count < TYPE_CACHE_DEPOT_SHARD_SLOTS {
            self.find_free_entry()
        } else {
            None
        };
        if let Some(entry_idx) = free_entry {
            if self.retained_bytes.saturating_add(incoming_bytes)
                <= MAX_TYPE_CACHE_DEPOT_SHARD_BYTES
            {
                if !self.keys[key_idx].active {
                    self.keys[key_idx] = TypeCacheDepotKeySlot {
                        cache_key: entry.cache_key,
                        identity,
                        policy_key: entry.policy_key,
                        size: entry.size,
                        align: entry.align,
                        head: TYPE_CACHE_DEPOT_EMPTY_INDEX,
                        count: 0,
                        active: true,
                    };
                }
                self.next[entry_idx] = self.keys[key_idx].head;
                self.entries[entry_idx] = entry;
                self.keys[key_idx].head = entry_idx;
                self.keys[key_idx].count += 1;
                self.count += 1;
                self.retained_bytes = self.retained_bytes.saturating_add(incoming_bytes);
                self.free_cursor = (entry_idx + 1) & (TYPE_CACHE_DEPOT_SHARD_SLOTS - 1);
                return Ok(None);
            }
        }

        // Saturation keeps the existing exact owners stable. Replacing one
        // interchangeable pointer with every later free preserves no extra
        // isolation capacity and turns large free bursts into depot-lock and
        // backend-release churn. The caller releases the incoming owner.
        Err(())
    }

    fn pop(
        &mut self,
        layout: Layout,
        identity: TypeCacheIdentity,
        cache_key: u64,
        policy_key: u32,
        key_start: usize,
        record_foreign: bool,
    ) -> (
        Option<SegregatedTypeCacheEntry>,
        Option<TypeCacheWrongIdentityCandidate>,
    ) {
        let mut foreign = None;
        let mut offset = 0usize;
        while offset < TYPE_CACHE_DEPOT_KEY_PROBE_LIMIT {
            let key_idx = (key_start + offset) & (TYPE_CACHE_DEPOT_KEY_SLOTS - 1);
            let key = self.keys[key_idx];
            if key.matches(layout, identity, cache_key, policy_key) {
                let entry_idx = key.head;
                if entry_idx >= TYPE_CACHE_DEPOT_SHARD_SLOTS {
                    panic!("type-cache depot directory corrupt");
                }
                let entry = self.entries[entry_idx];
                if !entry.matches_cached_key(layout, identity, cache_key, policy_key) {
                    panic!("type-cache depot directory corrupt");
                }
                self.keys[key_idx].head = self.next[entry_idx];
                self.keys[key_idx].count = self.keys[key_idx].count.saturating_sub(1);
                if self.keys[key_idx].count == 0 {
                    self.keys[key_idx] = TypeCacheDepotKeySlot::empty();
                }
                self.entries[entry_idx] = SegregatedTypeCacheEntry::empty();
                self.next[entry_idx] = TYPE_CACHE_DEPOT_EMPTY_INDEX;
                self.free_cursor = entry_idx;
                self.count = self.count.saturating_sub(1);
                self.retained_bytes = self.retained_bytes.saturating_sub(entry.retained_bytes());
                return (Some(entry), foreign);
            }
            if record_foreign
                && foreign.is_none()
                && key.active
                && key.size == layout.size()
                && key.align == layout.align()
                && key.policy_key == policy_key
                && key.identity != identity
            {
                let entry_idx = key.head;
                if key.count == 0 || entry_idx >= TYPE_CACHE_DEPOT_SHARD_SLOTS {
                    panic!("type-cache depot directory corrupt");
                }
                let entry = self.entries[entry_idx];
                if !entry.matches_cached_key(layout, key.identity, key.cache_key, key.policy_key) {
                    panic!("type-cache depot directory corrupt");
                }
                foreign = Some(TypeCacheWrongIdentityCandidate::new(
                    key.identity,
                    entry.ptr,
                ));
            }
            offset += 1;
        }
        (None, foreign)
    }
}

#[cfg(not(feature = "fixed_heap"))]
unsafe impl Send for TypeCacheDepotShard {}

#[cfg(not(feature = "fixed_heap"))]
static TYPE_CACHE_DEPOT: [Mutex<TypeCacheDepotShard>; TYPE_CACHE_DEPOT_SHARD_COUNT] = [
    Mutex::new(TypeCacheDepotShard::empty()),
    Mutex::new(TypeCacheDepotShard::empty()),
    Mutex::new(TypeCacheDepotShard::empty()),
    Mutex::new(TypeCacheDepotShard::empty()),
    Mutex::new(TypeCacheDepotShard::empty()),
    Mutex::new(TypeCacheDepotShard::empty()),
    Mutex::new(TypeCacheDepotShard::empty()),
    Mutex::new(TypeCacheDepotShard::empty()),
];

#[cfg(not(feature = "fixed_heap"))]
static TYPE_CACHE_DEPOT_SHARD_OCCUPANCY: [AtomicUsize; TYPE_CACHE_DEPOT_SHARD_COUNT] =
    [const { AtomicUsize::new(0) }; TYPE_CACHE_DEPOT_SHARD_COUNT];

#[cfg(all(test, not(feature = "fixed_heap")))]
fn clear_type_cache_depot_for_test() {
    let mut shard_idx = 0usize;
    while shard_idx < TYPE_CACHE_DEPOT_SHARD_COUNT {
        *TYPE_CACHE_DEPOT[shard_idx].lock() = TypeCacheDepotShard::empty();
        TYPE_CACHE_DEPOT_SHARD_OCCUPANCY[shard_idx].store(0, Ordering::Release);
        shard_idx += 1;
    }
    TYPE_CACHE_ADMISSION_STATS
        .depot_current_entries
        .store(0, Ordering::Relaxed);
    TYPE_CACHE_ADMISSION_STATS
        .depot_current_rounded_bytes
        .store(0, Ordering::Relaxed);
}

#[cfg(all(test, feature = "fixed_heap"))]
fn clear_type_cache_depot_for_test() {}

#[cfg(all(test, not(feature = "fixed_heap")))]
unsafe fn drain_type_cache_depot_for_test(alloc: &RustAllocator) -> usize {
    let mut released = 0usize;
    let mut shard_idx = 0usize;
    while shard_idx < TYPE_CACHE_DEPOT_SHARD_COUNT {
        let drained = {
            let mut shard = TYPE_CACHE_DEPOT[shard_idx].lock();
            let old_entries = shard.count;
            let old_bytes = shard.retained_bytes;
            let drained = core::mem::replace(&mut *shard, TypeCacheDepotShard::empty());
            note_type_cache_depot_occupancy_change(old_entries, old_bytes, 0, 0);
            TYPE_CACHE_DEPOT_SHARD_OCCUPANCY[shard_idx].store(0, Ordering::Release);
            drained
        };
        let mut slot_idx = 0usize;
        while slot_idx < TYPE_CACHE_DEPOT_SHARD_SLOTS {
            let entry = drained.entries[slot_idx];
            if !entry.is_empty() {
                entry.validate_structural_integrity();
                let layout = checked_side_table_layout(entry.size, entry.align, "type-cache depot");
                if terminal_release_retained_raw(
                    alloc,
                    entry.ptr,
                    layout,
                    TerminalRetainedOwnership::TypeCache,
                ) {
                    released = released.saturating_add(1);
                }
            }
            slot_idx += 1;
        }
        shard_idx += 1;
    }
    released
}

#[cfg(all(test, feature = "fixed_heap"))]
unsafe fn drain_type_cache_depot_for_test(_alloc: &RustAllocator) -> usize {
    0
}

// The entry owns only an allocator object pointer plus metadata authenticator.
// On arm64e the diagnostic no_std side-cache stores this single-entry hot path
// behind a spin mutex so it can avoid Rust TLV descriptors while still
// exercising the real PAC metadata record used by the normal segregated cache.
unsafe impl Send for SegregatedTypeCacheEntry {}

#[derive(Clone, Copy)]
struct SegregatedTypeCacheBucket {
    entries: [SegregatedTypeCacheEntry; SEGREGATED_TYPE_CACHE_DEPTH],
    count: usize,
    evict_cursor: usize,
    /// Allocator-rounded bytes stored in the compact active prefix of `entries`.
    ///
    /// The metadata-segregated cache has richer entries than the plain linked
    /// type-cache, but it is still on the typed free hot path.  Keep the byte
    /// budget as explicit bucket state so `can_accept_object_size` does not
    /// rescan the active prefix after the normal corruption check has already
    /// selected a bucket.
    retained_bytes: usize,
}

impl SegregatedTypeCacheBucket {
    const fn empty() -> Self {
        Self {
            entries: [SegregatedTypeCacheEntry::empty(); SEGREGATED_TYPE_CACHE_DEPTH],
            count: 0,
            evict_cursor: 0,
            retained_bytes: 0,
        }
    }

    fn retained_bytes(&self) -> Option<usize> {
        if self.is_structurally_corrupt() {
            return None;
        }

        let mut total = 0usize;
        let mut idx = 0usize;
        while idx < self.count {
            let entry = self.entries[idx];
            entry.validate_structural_integrity();
            total = total.saturating_add(entry.retained_bytes());
            idx += 1;
        }
        Some(total)
    }

    fn can_accept_object_size(&self, incoming_size: usize) -> bool {
        if self.is_structurally_corrupt() {
            return false;
        }
        self.validate_active_entry_integrity();
        if self.has_corrupt_accounting() {
            return false;
        }
        debug_assert_eq!(
            self.retained_bytes(),
            Some(self.retained_bytes),
            "segregated type-cache retained-byte counter must match entries"
        );
        let incoming_retained_bytes = type_cache_retained_bytes_for_object(incoming_size);
        let projected = if self.count < SEGREGATED_TYPE_CACHE_DEPTH {
            self.retained_bytes.saturating_add(incoming_retained_bytes)
        } else {
            let evict_idx = self.evict_cursor & (SEGREGATED_TYPE_CACHE_DEPTH - 1);
            self.retained_bytes
                .saturating_sub(self.entries[evict_idx].retained_bytes())
                .saturating_add(incoming_retained_bytes)
        };
        projected <= MAX_SEGREGATED_TYPE_CACHE_BUCKET_BYTES
    }

    fn pop(
        &mut self,
        layout: Layout,
        identity: TypeCacheIdentity,
        cache_key: u64,
        policy_key: u32,
    ) -> Option<SegregatedTypeCacheEntry> {
        if self.clear_if_corrupt() {
            return None;
        }

        let mut idx = self.count;
        while idx > 0 {
            idx -= 1;
            let entry = self.entries[idx];
            if entry.matches_cached_key(layout, identity, cache_key, policy_key) {
                let last_idx = self.count - 1;
                self.entries[idx] = self.entries[last_idx];
                self.entries[last_idx] = SegregatedTypeCacheEntry::empty();
                self.count -= 1;
                self.retained_bytes = self.retained_bytes.saturating_sub(entry.retained_bytes());
                if self.count < SEGREGATED_TYPE_CACHE_DEPTH {
                    self.evict_cursor = 0;
                }
                if self.count == 0 {
                    self.retained_bytes = 0;
                } else if !self.repair_accounting_if_possible() {
                    *self = Self::empty();
                }
                return Some(entry);
            }
        }
        None
    }

    fn push(&mut self, entry: SegregatedTypeCacheEntry) -> Option<SegregatedTypeCacheEntry> {
        self.clear_if_corrupt();
        self.validate_active_entry_integrity();

        if self.count < SEGREGATED_TYPE_CACHE_DEPTH {
            self.entries[self.count] = entry;
            self.count += 1;
            self.retained_bytes = self.retained_bytes.saturating_add(entry.retained_bytes());
            return None;
        }

        let idx = self.evict_cursor & (SEGREGATED_TYPE_CACHE_DEPTH - 1);
        let evicted = self.entries[idx];
        self.entries[idx] = entry;
        self.retained_bytes = self
            .retained_bytes
            .saturating_sub(evicted.retained_bytes())
            .saturating_add(entry.retained_bytes());
        self.evict_cursor = (idx + 1) & (SEGREGATED_TYPE_CACHE_DEPTH - 1);
        Some(evicted)
    }

    #[inline]
    fn validate_active_entry_integrity(&self) {
        let mut idx = 0usize;
        while idx < core::cmp::min(self.count, SEGREGATED_TYPE_CACHE_DEPTH) {
            self.entries[idx].validate_structural_integrity();
            idx += 1;
        }
    }

    fn matching_entry_count(
        &self,
        layout: Layout,
        identity: TypeCacheIdentity,
        cache_key: u64,
        policy_key: u32,
    ) -> usize {
        if self.is_corrupt() {
            return 0;
        }

        let mut count = 0;
        let mut idx = 0;
        while idx < self.count {
            if self.entries[idx].matches_cached_key(layout, identity, cache_key, policy_key) {
                count += 1;
            }
            idx += 1;
        }
        count
    }

    #[inline]
    fn has_corrupt_accounting(&self) -> bool {
        self.retained_bytes > MAX_SEGREGATED_TYPE_CACHE_BUCKET_BYTES
            || (self.count == 0 && self.retained_bytes != 0)
            || (self.count != 0 && self.retained_bytes == 0)
    }

    #[inline]
    fn is_corrupt(&self) -> bool {
        self.is_structurally_corrupt() || self.has_corrupt_accounting()
    }

    #[inline]
    fn is_structurally_corrupt(&self) -> bool {
        if self.count > SEGREGATED_TYPE_CACHE_DEPTH {
            return true;
        }

        let mut idx = 0usize;
        while idx < SEGREGATED_TYPE_CACHE_DEPTH {
            let occupied = !self.entries[idx].is_empty();
            if idx < self.count {
                if !occupied {
                    return true;
                }
            } else if occupied {
                return true;
            }
            idx += 1;
        }
        false
    }

    #[inline]
    fn repair_accounting_if_possible(&mut self) -> bool {
        if self.is_structurally_corrupt() {
            return false;
        }
        if !self.has_corrupt_accounting() {
            return true;
        }

        // The retained-byte counter is a hot-path budget hint, not ownership
        // metadata.  When the compact entry prefix is still valid, recompute the
        // counter instead of dropping owned cached objects on counter-only drift.
        // Structural corruption still clears the bucket through `clear_if_corrupt`.
        match self.retained_bytes() {
            Some(total)
                if total <= MAX_SEGREGATED_TYPE_CACHE_BUCKET_BYTES
                    && ((self.count == 0 && total == 0) || (self.count != 0 && total != 0)) =>
            {
                self.retained_bytes = total;
                true
            }
            _ => false,
        }
    }

    #[inline]
    fn clear_if_corrupt(&mut self) -> bool {
        if self.repair_accounting_if_possible() {
            return false;
        }
        *self = Self::empty();
        true
    }
}

#[derive(Clone, Copy)]
struct SegregatedTypeCacheHotBucket {
    cache_key: u64,
    size: usize,
    align: usize,
    policy_key: u32,
    cache_domain: u8,
    bucket_idx: usize,
}

impl SegregatedTypeCacheHotBucket {
    const fn empty() -> Self {
        Self {
            cache_key: UNKNOWN_SEMANTIC_ID,
            size: 0,
            align: EMPTY_LAYOUT_ALIGN,
            policy_key: 0,
            cache_domain: SEGREGATED_TYPE_CACHE_DOMAIN_ORDINARY,
            bucket_idx: 0,
        }
    }

    #[inline]
    fn matches_cached_key(
        self,
        layout: Layout,
        cache_key: u64,
        policy_key: u32,
        cache_domain: u8,
    ) -> bool {
        self.cache_key == cache_key
            && self.size == layout.size()
            && self.align == layout.align()
            && self.policy_key == policy_key
            && self.cache_domain == cache_domain
    }

    #[inline]
    fn matches(self, layout: Layout, metadata: AllocationMetadata) -> bool {
        self.matches_cached_key(
            layout,
            type_cache_identity_key(metadata),
            segregated_type_cache_policy_key(metadata),
            SEGREGATED_TYPE_CACHE_DOMAIN_ORDINARY,
        )
    }
}

#[thread_local]
