#[inline]
fn record_segregated_type_cache_bucket_probe_step() {
    SEGREGATED_TYPE_CACHE_BUCKET_PROBE_STEPS.fetch_add(1, Ordering::Relaxed);
}

#[cfg(not(test))]
#[inline]
fn record_segregated_type_cache_bucket_probe_step() {}

