#[cfg(test)]
static FAST_AUTO_ALLOCATION_RECORD_PROBE_STEPS: AtomicUsize = AtomicUsize::new(0);

#[cfg(test)]
#[inline]
fn record_fast_auto_allocation_record_probe_step() {
    FAST_AUTO_ALLOCATION_RECORD_PROBE_STEPS.fetch_add(1, Ordering::Relaxed);
}

#[cfg(not(test))]
#[inline]
fn record_fast_auto_allocation_record_probe_step() {}

#[inline]
fn fast_auto_allocation_record_probe_already_checked(
    checked_hot_idx: Option<usize>,
    idx: usize,
) -> bool {
    checked_hot_idx == Some(idx)
}

struct MetadataScopeGuard {
    previous: AllocationMetadata,
}

impl Drop for MetadataScopeGuard {
    fn drop(&mut self) {
        unsafe {
            restore_active_metadata(self.previous);
        }
    }
}

struct AutoAllocationRecoveryRecordingGuard;

impl Drop for AutoAllocationRecoveryRecordingGuard {
    fn drop(&mut self) {
        unsafe {
            AUTO_ALLOCATION_RECOVERY_RECORDING_DEPTH =
                AUTO_ALLOCATION_RECOVERY_RECORDING_DEPTH.saturating_sub(1);
        }
    }
}

struct AutoAllocationRecoverySuppressionGuard {
    previous_depth: usize,
}

impl Drop for AutoAllocationRecoverySuppressionGuard {
    fn drop(&mut self) {
        unsafe {
            AUTO_ALLOCATION_RECOVERY_RECORDING_DEPTH = self.previous_depth;
        }
    }
}

struct AutoMetadataSelectionSuppressionGuard;

impl Drop for AutoMetadataSelectionSuppressionGuard {
    fn drop(&mut self) {
        unsafe {
            AUTO_METADATA_SELECTION_SUPPRESSION_DEPTH =
                AUTO_METADATA_SELECTION_SUPPRESSION_DEPTH.saturating_sub(1);
        }
    }
}

/// Run `f` while semantic allocations create pointer-to-metadata recovery
/// records for later ordinary `GlobalAlloc` dealloc/realloc calls.
///
/// Explicit Rust `SemanticAlloc` callers pass metadata again at deallocation
/// time and should not pay the recovery-record side-table cost. The ordinary
/// `GlobalAlloc` scoped/auto-metadata bridge and rustc-driver direct
/// allocator ABI are the paths that need recovery records after a compiler
/// scope exits, an auto allocation-site stream advances, or only the
/// allocation half of Box lowering was rewritten.
pub(crate) fn with_auto_allocation_recovery_recording<R>(f: impl FnOnce() -> R) -> R {
    unsafe {
        AUTO_ALLOCATION_RECOVERY_RECORDING_DEPTH =
            AUTO_ALLOCATION_RECOVERY_RECORDING_DEPTH.saturating_add(1);
    }
    let _guard = AutoAllocationRecoveryRecordingGuard;
    f()
}

/// Run `f` as an exact paired local ABI operation that must not publish a new
/// recovery record, while restoring any outer conservative recording scope on
/// return or unwind.
pub(crate) fn without_auto_allocation_recovery_recording<R>(f: impl FnOnce() -> R) -> R {
    let previous_depth = unsafe { AUTO_ALLOCATION_RECOVERY_RECORDING_DEPTH };
    unsafe {
        AUTO_ALLOCATION_RECOVERY_RECORDING_DEPTH = 0;
    }
    let _guard = AutoAllocationRecoverySuppressionGuard { previous_depth };
    f()
}

/// Run `f` without consuming or synthesizing process-wide auto metadata.
///
/// Compiler ownership-transfer helpers use this while they either preserve an
/// exact source record or deliberately fall back to raw allocation.
/// Otherwise a rejected transfer could consume an unrelated compiler-stream
/// entry or attach layout-derived metadata to the replacement allocation.
fn without_auto_metadata_selection<R>(f: impl FnOnce() -> R) -> R {
    unsafe {
        AUTO_METADATA_SELECTION_SUPPRESSION_DEPTH =
            AUTO_METADATA_SELECTION_SUPPRESSION_DEPTH.saturating_add(1);
    }
    let _guard = AutoMetadataSelectionSuppressionGuard;
    f()
}

#[inline]
fn auto_metadata_selection_suppressed() -> bool {
    unsafe { AUTO_METADATA_SELECTION_SUPPRESSION_DEPTH != 0 }
}

#[inline]
fn auto_allocation_recovery_recording_enabled() -> bool {
    unsafe { AUTO_ALLOCATION_RECOVERY_RECORDING_DEPTH != 0 }
}

/// Return true when runtime layout auto-metadata is enabled.
///
/// Auto metadata is global process state used by evaluation harnesses that need
/// to run existing `GlobalAlloc` benchmarks without source-level wrappers. It
/// deliberately derives a semantic id from `Layout`, so it is non-claim-grade
/// unless paired with compiler-assigned type metadata evidence.
pub fn semantic_auto_metadata_enabled() -> bool {
    AUTO_METADATA_CONFIG.read().flags != 0
}

/// Return true when ordinary `GlobalAlloc` calls need semantic-side checks.
///
/// The default allocator path is intentionally cold for semantic features:
/// when no coverage accounting, process-wide auto metadata, or scoped compiler
/// metadata is active, `GlobalAlloc` can skip thread-local metadata probes and
/// auto-metadata synthesis entirely.
#[inline]
pub fn semantic_runtime_slow_path_enabled() -> bool {
    // The exact global-record count is authoritative.  The coarse slow-path
    // flag can be cleared by a last-record removal racing an insertion in a
    // different shard, so it must not be the only deallocation/reallocation
    // gate for live cross-thread recovery metadata.
    if AUTO_ALLOCATION_RECORD_COUNT.load(Ordering::Relaxed) != 0 {
        return true;
    }
    let global_flags = SEMANTIC_SLOW_PATH_FLAGS.load(Ordering::Relaxed);
    if scoped_metadata_slow_path_enabled(global_flags) {
        return true;
    }
    if FAST_AUTO_ALLOCATION_RECORD_GLOBAL_COUNT.load(Ordering::Relaxed) != 0
        && current_thread_fast_auto_allocation_records_active()
    {
        return true;
    }
    let mut runtime_flags = global_flags & !SLOW_PATH_SCOPED_METADATA_MASK;
    if runtime_flags & SLOW_PATH_AUTO_METADATA != 0 && auto_metadata_allocations_exhausted() {
        runtime_flags &= !SLOW_PATH_AUTO_METADATA;
    }
    runtime_flags != 0
}

#[inline]
unsafe fn current_thread_fast_recovery_maybe_tracks_pointer(ptr: *mut u8) -> bool {
    if ptr.is_null() || !current_thread_fast_auto_allocation_records_active() {
        return false;
    }
    let ptr_key = ptr as usize;
    if FAST_AUTO_ALLOCATION_RECORD_INLINE.ptr == ptr_key {
        return true;
    }
    let start = fast_auto_allocation_record_slot(ptr);
    let mut offset = 0usize;
    while offset < FAST_AUTO_ALLOCATION_RECORD_PROBE_LIMIT {
        let idx = (start + offset) & (FAST_AUTO_ALLOCATION_RECORD_SLOTS - 1);
        let record = FAST_AUTO_ALLOCATION_RECORDS[idx];
        if record.is_empty() {
            break;
        }
        if record.ptr == ptr_key {
            return true;
        }
        offset += 1;
    }
    false
}

/// Pointer-specific deallocation/reallocation gate.
///
/// A positive result preserves the complete semantic path. A negative result
/// requires the exact-count recovery/retained filter to be empty for this
/// address hash and is therefore safe for the ordinary raw backend path.
#[inline]
pub(crate) unsafe fn semantic_runtime_slow_path_enabled_for_pointer(ptr: *mut u8) -> bool {
    let lifecycle_active = global_address_lifecycle_tracking_active();
    if global_address_generation_tracking_active() && lifecycle_active {
        return true;
    }
    if !lifecycle_active {
        return semantic_runtime_slow_path_enabled();
    }
    let global_flags = SEMANTIC_SLOW_PATH_FLAGS.load(Ordering::Relaxed);
    if scoped_metadata_slow_path_enabled(global_flags) {
        return true;
    }
    let pointer_maybe_tracked = current_thread_fast_recovery_maybe_tracks_pointer(ptr)
        || global_semantic_pointer_maybe_tracked(ptr);
    if pointer_maybe_tracked {
        #[cfg(test)]
        pause_after_pointer_filter_slow_path_for_test();
        return true;
    }
    let mut runtime_flags =
        global_flags & !(SLOW_PATH_ALLOCATION_RECORDS | SLOW_PATH_SCOPED_METADATA_MASK);
    if runtime_flags & SLOW_PATH_AUTO_METADATA != 0 && auto_metadata_allocations_exhausted() {
        runtime_flags &= !SLOW_PATH_AUTO_METADATA;
    }
    runtime_flags != 0
}

#[inline]
fn auto_metadata_allocations_exhausted() -> bool {
    // The hot allocation/deallocation gates call this whenever auto metadata is
    // enabled.  Layout-derived and cyclic compiler replay modes cannot become
    // exhausted, and consuming streams explicitly set this flag when their last
    // ID is consumed.  Avoid taking AUTO_METADATA_CONFIG's read lock on the
    // common non-exhausted path; only confirm the active mode after the sticky
    // exhaustion bit is observed.
    if !AUTO_COMPILER_TYPE_IDS_STREAM_EXHAUSTED.load(Ordering::Relaxed) {
        return false;
    }
    let config = *AUTO_METADATA_CONFIG.read();
    auto_metadata_allocations_exhausted_for(config)
}

#[inline]
fn auto_metadata_allocations_exhausted_for(config: AutoMetadataConfig) -> bool {
    let exhausted = AUTO_COMPILER_TYPE_IDS_STREAM_EXHAUSTED.load(Ordering::Relaxed)
        && config.compiler_stream_enabled();
    if exhausted {
        semantic_slow_path_clear(SLOW_PATH_AUTO_METADATA);
    }
    exhausted
}

#[inline]
fn mark_auto_compiler_stream_exhausted() {
    AUTO_COMPILER_TYPE_IDS_STREAM_EXHAUSTED.store(true, Ordering::Relaxed);
    semantic_slow_path_clear(SLOW_PATH_AUTO_METADATA);
}

/// Return true when ordinary `GlobalAlloc::alloc` needs semantic-side work.
///
/// Outstanding allocation records are needed by later dealloc/realloc recovery,
/// but they do not require unrelated future allocations to probe thread-local
/// scopes, synthesize auto metadata, or record fallback coverage counters.
#[inline]
pub fn semantic_allocation_slow_path_enabled() -> bool {
    let global_flags = SEMANTIC_SLOW_PATH_FLAGS.load(Ordering::Relaxed);
    if scoped_metadata_slow_path_enabled(global_flags) {
        return true;
    }
    let mut allocation_flags =
        global_flags & !(SLOW_PATH_ALLOCATION_RECORDS | SLOW_PATH_SCOPED_METADATA_MASK);
    if allocation_flags & SLOW_PATH_AUTO_METADATA != 0 && auto_metadata_allocations_exhausted() {
        allocation_flags &= !SLOW_PATH_AUTO_METADATA;
    }
    allocation_flags != 0
}

#[inline]
fn semantic_slow_path_set(flag: usize) {
    SEMANTIC_SLOW_PATH_FLAGS.fetch_or(flag, Ordering::Relaxed);
}

#[inline]
fn semantic_slow_path_clear(flag: usize) {
    SEMANTIC_SLOW_PATH_FLAGS.fetch_and(!flag, Ordering::Relaxed);
}

#[inline]
fn scoped_metadata_is_active(metadata: AllocationMetadata) -> bool {
    metadata != AllocationMetadata::unknown()
}

#[inline]
fn allocator_metadata_is_effective(metadata: AllocationMetadata) -> bool {
    metadata.flags != 0
        || semantic_stats_any_recording_enabled()
        || lifetime_metadata_policy_is_effective(metadata)
}

#[inline]
fn lifetime_metadata_policy_is_effective(metadata: AllocationMetadata) -> bool {
    #[cfg(all(feature = "lifetime_hugepage", not(feature = "fixed_heap")))]
    {
        super::lifetime_hugepage::flags_zero_exact_scope_is_effective(metadata)
    }
    #[cfg(not(all(feature = "lifetime_hugepage", not(feature = "fixed_heap"))))]
    {
        let _ = metadata;
        false
    }
}

#[inline]
fn scoped_metadata_requests_allocator_policy(metadata: AllocationMetadata) -> bool {
    metadata.flags != 0
}

#[inline]
fn compose_mandatory_allocator_policy(metadata: AllocationMetadata) -> AllocationMetadata {
    #[cfg(feature = "quarantine")]
    if metadata.flags == 0 {
        return metadata.with_flags(metadata.flags | FLAG_DELAYED_FREE);
    }
    metadata
}

#[inline]
fn current_thread_allocator_metadata_active() -> bool {
    unsafe {
        scoped_metadata_is_active(ACTIVE_METADATA)
            && allocator_metadata_is_effective(ACTIVE_METADATA)
    }
}

#[inline]
fn scoped_metadata_slow_path_enabled(global_flags: usize) -> bool {
    global_flags & SLOW_PATH_SCOPED_METADATA_MASK != 0 && current_thread_allocator_metadata_active()
}

#[inline]
fn current_thread_fast_auto_allocation_records_active() -> bool {
    unsafe {
        FAST_AUTO_ALLOCATION_RECORD_COUNT != 0 || !FAST_AUTO_ALLOCATION_RECORD_INLINE.is_empty()
    }
}

#[inline]
fn scoped_metadata_publish_coarse_gate() {
    if SEMANTIC_SLOW_PATH_FLAGS.load(Ordering::Relaxed) & SLOW_PATH_SCOPED_METADATA_MASK == 0 {
        semantic_slow_path_set(SLOW_PATH_SCOPED_METADATA_UNIT);
    }
}

fn scoped_metadata_activate() {
    activate_semantic_address_lifecycle_tracking();
    scoped_metadata_publish_coarse_gate();
}

#[inline]
fn scoped_metadata_deactivate() {
    // The process-wide flag is only a coarse gate telling ordinary GlobalAlloc
    // calls that scoped metadata has been used in this process.  Exact activity
    // is thread-local (`ACTIVE_METADATA`), checked by
    // `current_thread_allocator_metadata_active()`. Keeping this bit sticky avoids
    // an atomic decrement/CAS on every compiler-inserted scope pop; unrelated
    // threads still return false from the slow-path predicate because their TLS
    // active metadata is empty.
}

#[inline]
fn prepare_active_metadata_transition(previous: AllocationMetadata, next: AllocationMetadata) {
    let previous_active = scoped_metadata_is_active(previous);
    let next_active = scoped_metadata_is_active(next);
    if !previous_active && next_active {
        // Transport-only metadata still uses the semantic ABI. Preserve the
        // release-build feature boundary before publishing TLS or the coarse
        // process gate, even though it does not activate allocator policy.
        require_semantic_lifecycle_feature();
        if scoped_metadata_requests_allocator_policy(next) {
            scoped_metadata_activate();
        } else {
            scoped_metadata_publish_coarse_gate();
        }
    } else if previous_active
        && next_active
        && !scoped_metadata_requests_allocator_policy(previous)
        && scoped_metadata_requests_allocator_policy(next)
    {
        // A nested policy scope must activate the lifecycle even when its
        // transport-only outer scope already made ACTIVE_METADATA non-empty.
        scoped_metadata_activate();
    } else if previous_active && !next_active {
        scoped_metadata_deactivate();
    }
}

#[inline]
fn fast_auto_allocation_record_global_activate() {
    FAST_AUTO_ALLOCATION_RECORD_GLOBAL_COUNT.fetch_add(1, Ordering::Relaxed);
}

#[inline]
fn fast_auto_allocation_record_global_deactivate() {
    let mut count = FAST_AUTO_ALLOCATION_RECORD_GLOBAL_COUNT.load(Ordering::Relaxed);
    loop {
        if count == 0 {
            return;
        }
        match FAST_AUTO_ALLOCATION_RECORD_GLOBAL_COUNT.compare_exchange_weak(
            count,
            count - 1,
            Ordering::Relaxed,
            Ordering::Relaxed,
        ) {
            Ok(_) => return,
            Err(next) => count = next,
        }
    }
}

#[inline]
unsafe fn replace_active_metadata(metadata: AllocationMetadata) -> AllocationMetadata {
    let previous = ACTIVE_METADATA;
    prepare_active_metadata_transition(previous, metadata);
    ACTIVE_METADATA = metadata;
    previous
}

#[inline(always)]
unsafe fn set_semantic_scope_active_metadata(metadata: AllocationMetadata) {
    prepare_active_metadata_transition(ACTIVE_METADATA, metadata);
    ACTIVE_METADATA = metadata;
}

fn normalize_auto_metadata_flags(flags: u32) -> u32 {
    if flags == 0 {
        FLAG_TYPE_ISOLATED
    } else {
        flags | FLAG_TYPE_ISOLATED
    }
}

#[inline]
unsafe fn clear_auto_layout_metadata_hot_slot() {
    AUTO_LAYOUT_METADATA_HOT_SLOT = AutoLayoutMetadataHotSlot::empty();
}

#[inline]
fn synthesize_layout_auto_metadata(
    layout: Layout,
    flags: u32,
    module_id: u64,
    callsite: u64,
) -> AllocationMetadata {
    AllocationMetadata {
        type_id: semantic_layout_id(layout.size(), layout.align()),
        module_id,
        flags,
        lifetime_hint: 0,
        placement_hint: LAYOUT_DERIVED_PLACEMENT_HINT,
        callsite,
    }
}

#[inline]
fn layout_auto_metadata(
    layout: Layout,
    flags: u32,
    module_id: u64,
    callsite: u64,
) -> AllocationMetadata {
    unsafe {
        let cached = AUTO_LAYOUT_METADATA_HOT_SLOT;
        if cached.matches(layout, flags, module_id, callsite) {
            return cached.metadata;
        }
        let metadata = synthesize_layout_auto_metadata(layout, flags, module_id, callsite);
        AUTO_LAYOUT_METADATA_HOT_SLOT = AutoLayoutMetadataHotSlot {
            size: layout.size(),
            align: layout.align(),
            flags,
            module_id,
            callsite,
            metadata,
        };
        metadata
    }
}

/// Return true when process-wide auto metadata is replaying compiler-provided
/// allocation-site ids rather than synthesizing ids from layout alone.
pub fn semantic_auto_compiler_metadata_enabled() -> bool {
    AUTO_METADATA_CONFIG.read().compiler_metadata_enabled()
}

/// Return true when compiler-provided ids are consumed once without wrapping.
pub fn semantic_auto_compiler_metadata_stream_enabled() -> bool {
    AUTO_METADATA_CONFIG.read().compiler_stream_enabled()
}

/// Identify the current process-wide auto metadata type-id basis for emitted
/// evaluation events.
pub fn semantic_auto_metadata_type_id_basis() -> &'static str {
    let config = *AUTO_METADATA_CONFIG.read();
    if config.flags == 0 {
        "none"
    } else if config.compiler_stream_enabled() {
        "compiler-assigned-allocation-site-object-type-id-consuming-stream"
    } else if config.compiler_metadata_enabled() {
        "compiler-assigned-allocation-site-object-type-id-cyclic-replay"
    } else {
        "layout-derived-size-align"
    }
}

/// Enable process-wide layout auto-metadata for ordinary `GlobalAlloc` calls.
///
/// `flags == 0` selects `FLAG_TYPE_ISOLATED`; otherwise the supplied flags are
/// ORed with `FLAG_TYPE_ISOLATED` so the typed frontend is exercised. Scoped
/// metadata on the current thread still takes precedence over this mode.
/// Release builds require the `type_isolation` feature. Activation panics
/// before publishing state when that feature is disabled.
pub fn semantic_auto_metadata_enable(module_id: u64, flags: u32, callsite: u64) {
    activate_semantic_address_lifecycle_tracking();
    let normalized_flags = normalize_auto_metadata_flags(flags);
    let mut config = AUTO_METADATA_CONFIG.write();
    let generation = next_auto_metadata_config_generation(*config);
    unsafe {
        clear_auto_layout_metadata_hot_slot();
        AUTO_COMPILER_TYPE_IDS_TLS_CURSOR = 0;
        AUTO_COMPILER_TYPE_IDS_TLS_GENERATION = generation;
    }
    semantic_slow_path_set(SLOW_PATH_AUTO_METADATA);
    AUTO_COMPILER_TYPE_IDS_CURSOR.store(0, Ordering::Relaxed);
    AUTO_COMPILER_TYPE_IDS_STREAM_EXHAUSTED.store(false, Ordering::Relaxed);
    *config = AutoMetadataConfig {
        generation,
        flags: normalized_flags,
        module_id,
        callsite,
        ..AutoMetadataConfig::disabled()
    };
}

unsafe fn semantic_auto_compiler_metadata_enable_with_mode(
    module_id: u64,
    flags: u32,
    callsite: u64,
    type_ids: *const u64,
    len: usize,
    mode: usize,
    global_recovery: bool,
) -> bool {
    if type_ids.is_null() || len == 0 {
        return false;
    }
    activate_semantic_address_lifecycle_tracking();
    let normalized_flags = normalize_auto_metadata_flags(flags);
    let mut config = AUTO_METADATA_CONFIG.write();
    let generation = next_auto_metadata_config_generation(*config);
    clear_auto_layout_metadata_hot_slot();
    semantic_slow_path_set(SLOW_PATH_AUTO_METADATA);
    AUTO_COMPILER_TYPE_IDS_CURSOR.store(0, Ordering::Relaxed);
    AUTO_COMPILER_TYPE_IDS_TLS_CURSOR = 0;
    AUTO_COMPILER_TYPE_IDS_TLS_GENERATION = generation;
    AUTO_COMPILER_TYPE_IDS_STREAM_EXHAUSTED.store(false, Ordering::Relaxed);
    *config = AutoMetadataConfig {
        generation,
        flags: normalized_flags,
        module_id,
        callsite,
        compiler_type_ids_ptr: type_ids as usize,
        compiler_type_ids_len: len,
        compiler_type_ids_mode: mode,
        compiler_type_ids_global_recovery: global_recovery,
    };
    true
}

/// Enable process-wide auto metadata by replaying compiler-provided
/// allocation-site type ids for ordinary `GlobalAlloc` calls.
///
/// This bridge is intentionally labeled as cyclic replay: it validates that
/// unmodified benchmark allocations can flow through the same runtime ABI with
/// compiler-assigned ids, but it is not by itself proof that a compiler pass
/// dynamically attributed each runtime allocation to its exact site.
/// Release builds require the `type_isolation` feature. Activation panics
/// before publishing state when that feature is disabled.
///
/// # Safety
///
/// `type_ids` must point to `len` valid `u64` entries that remain alive until
/// `semantic_auto_metadata_disable` is called or a different auto metadata mode
/// is enabled. The caller is also responsible for avoiding concurrent mutation
/// of that slice while allocation may occur.
pub unsafe fn semantic_auto_compiler_metadata_enable(
    module_id: u64,
    flags: u32,
    callsite: u64,
    type_ids: *const u64,
    len: usize,
) -> bool {
    semantic_auto_compiler_metadata_enable_with_mode(
        module_id,
        flags,
        callsite,
        type_ids,
        len,
        AUTO_COMPILER_TYPE_IDS_MODE_CYCLIC_REPLAY,
        true,
    )
}

/// Enable cyclic compiler-site replay with same-thread recovery records.
///
/// This mode is intended for single-threaded benchmark/evaluation harnesses.
/// Exact metadata recovery stays in the TLS fast table instead of the sharded
/// global table, so the ordinary `GlobalAlloc` hot path avoids a global lock.
/// Use `semantic_auto_compiler_metadata_enable` for conservative cross-thread
/// visibility.
/// Release builds require the `type_isolation` feature. Activation panics
/// before publishing state when that feature is disabled.
///
/// # Safety
///
/// `type_ids` must satisfy the same lifetime contract as
/// `semantic_auto_compiler_metadata_enable`.  Pointers allocated in this mode
/// must be deallocated/reallocated on the allocating thread unless another ABI
/// path supplies exact deallocation metadata.
pub unsafe fn semantic_auto_compiler_metadata_thread_local_recovery_enable(
    module_id: u64,
    flags: u32,
    callsite: u64,
    type_ids: *const u64,
    len: usize,
) -> bool {
    semantic_auto_compiler_metadata_enable_with_mode(
        module_id,
        flags,
        callsite,
        type_ids,
        len,
        AUTO_COMPILER_TYPE_IDS_MODE_CYCLIC_REPLAY,
        false,
    )
}

/// Enable process-wide auto metadata by consuming compiler-provided
/// allocation-site type ids exactly once for ordinary `GlobalAlloc` calls.
///
/// Unlike cyclic replay, this mode never wraps. After the finite stream is
/// exhausted, additional ordinary allocations are left untyped so coverage
/// evidence can expose a short runtime id stream rather than hiding it behind
/// layout-derived fallback ids.
/// Release builds require the `type_isolation` feature. Activation panics
/// before publishing state when that feature is disabled.
///
/// # Safety
///
/// `type_ids` must point to `len` valid `u64` entries that remain alive until
/// `semantic_auto_metadata_disable` is called or a different auto metadata mode
/// is enabled. The caller is also responsible for avoiding concurrent mutation
/// of that slice while allocation may occur.
pub unsafe fn semantic_auto_compiler_metadata_stream_enable(
    module_id: u64,
    flags: u32,
    callsite: u64,
    type_ids: *const u64,
    len: usize,
) -> bool {
    semantic_auto_compiler_metadata_enable_with_mode(
        module_id,
        flags,
        callsite,
        type_ids,
        len,
        AUTO_COMPILER_TYPE_IDS_MODE_CONSUMING_STREAM,
        true,
    )
}

/// Enable finite compiler-site replay with same-thread recovery records.
///
/// This keeps exact metadata recovery in the TLS fast table rather than the
/// process-global table.  It is appropriate for local benchmark replay and for
/// compiler paths that prove same-thread deallocation; the default stream API
/// remains conservative for unknown cross-thread ownership transfer.
/// Release builds require the `type_isolation` feature. Activation panics
/// before publishing state when that feature is disabled.
///
/// # Safety
///
/// `type_ids` must satisfy the same lifetime contract as
/// `semantic_auto_compiler_metadata_stream_enable`.  Pointers allocated in this
/// mode must be deallocated/reallocated on the allocating thread unless exact
/// metadata is supplied by another path.
pub unsafe fn semantic_auto_compiler_metadata_stream_thread_local_recovery_enable(
    module_id: u64,
    flags: u32,
    callsite: u64,
    type_ids: *const u64,
    len: usize,
) -> bool {
    semantic_auto_compiler_metadata_enable_with_mode(
        module_id,
        flags,
        callsite,
        type_ids,
        len,
        AUTO_COMPILER_TYPE_IDS_MODE_CONSUMING_STREAM,
        false,
    )
}

/// Disable process-wide layout auto-metadata for ordinary `GlobalAlloc` calls.
pub fn semantic_auto_metadata_disable() {
    let mut config = AUTO_METADATA_CONFIG.write();
    let generation = next_auto_metadata_config_generation(*config);
    unsafe {
        clear_auto_layout_metadata_hot_slot();
        AUTO_COMPILER_TYPE_IDS_TLS_CURSOR = 0;
        AUTO_COMPILER_TYPE_IDS_TLS_GENERATION = generation;
    }
    AUTO_COMPILER_TYPE_IDS_CURSOR.store(0, Ordering::Relaxed);
    AUTO_COMPILER_TYPE_IDS_STREAM_EXHAUSTED.store(false, Ordering::Relaxed);
    *config = AutoMetadataConfig {
        generation,
        ..AutoMetadataConfig::disabled()
    };
    semantic_slow_path_clear(SLOW_PATH_AUTO_METADATA);
}

#[inline]
fn next_auto_compiler_type_id_index(
    len: usize,
    stream_mode: bool,
    global_recovery: bool,
    generation: usize,
) -> Option<usize> {
    if !stream_mode {
        if !global_recovery {
            // Thread-local compiler replay is used by single-thread benchmark
            // validation and by compiler paths that prove same-thread drop.
            // It does not require a process-global allocation-site order, so a
            // TLS cursor avoids a global atomic fetch_add on every allocation.
            unsafe {
                if AUTO_COMPILER_TYPE_IDS_TLS_GENERATION != generation {
                    AUTO_COMPILER_TYPE_IDS_TLS_CURSOR = 0;
                    AUTO_COMPILER_TYPE_IDS_TLS_GENERATION = generation;
                }
                let idx = AUTO_COMPILER_TYPE_IDS_TLS_CURSOR % len;
                AUTO_COMPILER_TYPE_IDS_TLS_CURSOR = (idx + 1) % len;
                return Some(idx);
            }
        }
        return Some(AUTO_COMPILER_TYPE_IDS_CURSOR.fetch_add(1, Ordering::Relaxed) % len);
    }

    if AUTO_COMPILER_TYPE_IDS_STREAM_EXHAUSTED.load(Ordering::Relaxed) {
        return None;
    }

    let mut cursor = AUTO_COMPILER_TYPE_IDS_CURSOR.load(Ordering::Relaxed);
    loop {
        if cursor >= len {
            mark_auto_compiler_stream_exhausted();
            return None;
        }
        match AUTO_COMPILER_TYPE_IDS_CURSOR.compare_exchange_weak(
            cursor,
            cursor + 1,
            Ordering::Relaxed,
            Ordering::Relaxed,
        ) {
            Ok(_) => {
                if cursor + 1 == len {
                    mark_auto_compiler_stream_exhausted();
                }
                return Some(cursor);
            }
            Err(next) => cursor = next,
        }
    }
}

/// Select metadata for one unscoped allocation event while retaining whether
/// an auto policy was active when that event was consumed.  The distinction is
/// required for finite compiler streams: `None` can mean either "no policy"
/// or a deliberate UNKNOWN/exhausted event that must remain raw.
pub(crate) fn select_auto_allocation_metadata(
    layout: Layout,
) -> (bool, Option<AllocationMetadata>) {
    if auto_metadata_selection_suppressed() {
        return (false, None);
    }
    let config = AUTO_METADATA_CONFIG.read();
    if config.flags == 0 {
        return (false, None);
    }
    if config.compiler_metadata_enabled() {
        let stream_mode = config.compiler_stream_enabled();
        let idx = match next_auto_compiler_type_id_index(
            config.compiler_type_ids_len,
            stream_mode,
            config.compiler_type_ids_global_recovery,
            config.generation,
        ) {
            Some(idx) => idx,
            None => return (true, None),
        };
        // The read guard intentionally remains live through this dereference.
        // Disable/reconfigure cannot acquire the write side and return control
        // to a caller that may free the old slice until this load completes.
        let type_id = unsafe { *((config.compiler_type_ids_ptr as *const u64).add(idx)) };
        if type_id != UNKNOWN_SEMANTIC_ID {
            // Bind recovery visibility to the same coherent config generation
            // that supplied this compiler id. Recording happens after the
            // backing allocation and may race disable/reconfiguration, so it
            // must not consult whatever config happens to be current then.
            let recovery_placement_hint = if config.compiler_type_ids_global_recovery {
                PLACEMENT_HINT_CROSS_THREAD_RECOVERY
            } else {
                0
            };
            return (
                true,
                Some(AllocationMetadata {
                    type_id,
                    module_id: config.module_id,
                    flags: config.flags,
                    lifetime_hint: 0,
                    placement_hint: recovery_placement_hint,
                    callsite: config.callsite.wrapping_add(idx as u64),
                }),
            );
        }
        if stream_mode {
            return (true, None);
        }
    }
    (
        true,
        Some(layout_auto_metadata(
            layout,
            config.flags,
            config.module_id,
            config.callsite,
        )),
    )
}

/// Synthesize evaluation-only metadata for an unscoped `GlobalAlloc` layout.
pub fn auto_allocation_metadata(layout: Layout) -> Option<AllocationMetadata> {
    select_auto_allocation_metadata(layout).1
}

/// Synthesize metadata for an unscoped `GlobalAlloc::dealloc` without
/// advancing allocation-site ID streams.
///
/// Allocation-site streams model allocation events.  A plain `GlobalAlloc`
/// deallocation does not carry enough information to recover the exact
/// compiler-emitted allocation-site id, and consuming the next stream entry at
/// deallocation time would shift all later allocation events to the wrong
/// compiler site.  Keep policy flags available for zeroing/quarantine-style
/// experiments, but mark compiler-stream deallocations as fallback metadata
/// unless a real scoped/compiler deallocation metadata path is active.
pub fn auto_deallocation_metadata(layout: Layout) -> Option<AllocationMetadata> {
    let config = *AUTO_METADATA_CONFIG.read();
    if config.flags == 0 {
        return None;
    }

    if config.compiler_metadata_enabled() {
        if auto_metadata_allocations_exhausted_for(config) {
            return None;
        }
        return Some(AllocationMetadata {
            type_id: UNKNOWN_SEMANTIC_ID,
            module_id: config.module_id,
            flags: config.flags,
            lifetime_hint: 0,
            placement_hint: 0,
            callsite: config.callsite,
        });
    }

    Some(layout_auto_metadata(
        layout,
        config.flags,
        config.module_id,
        config.callsite,
    ))
}

#[inline]
fn auto_allocation_recording_required(metadata: AllocationMetadata) -> bool {
    // Any semantic policy that reaches recovery-record installation must keep
    // the exact allocation-time identity until the pointer is destroyed.
    // Layout-derived metadata is not eligible for exact type-cache reuse, but
    // it can still carry deallocation-sensitive policy (for example delayed
    // free, guard pages, memory tagging, or stats attribution). Auto-metadata
    // disable/reconfigure therefore cannot safely substitute the current
    // layout policy for a live allocation's selected generation.
    metadata.has_type()
}

#[inline]
pub(crate) fn active_allocation_metadata_requires_recovery_record(
    metadata: AllocationMetadata,
) -> bool {
    metadata.placement_hint & PLACEMENT_HINT_CROSS_THREAD_RECOVERY != 0
        || metadata.placement_hint & PLACEMENT_HINT_LOCAL_SCOPE_NO_RECOVERY == 0
}

#[inline]
fn auto_allocation_record_eligible(
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
) -> bool {
    let ptr_key = ptr as usize;
    !ptr.is_null()
        && ptr_key != AUTO_ALLOCATION_RECORD_TOMBSTONE_PTR
        && layout.size() != 0
        && auto_allocation_recording_required(metadata)
}

#[inline]
fn auto_allocation_record_requires_global_visibility(metadata: AllocationMetadata) -> bool {
    // Stats collection reads allocation/deallocation events on the same slow
    // path that records or consumes recovery metadata; it does not require the
    // pointer-to-metadata record to be process-visible.  Keep ordinary
    // same-thread compiler recovery in the TLS fast table so claim probes can
    // gather stats without paying the global mutex/inline-table footprint.
    //
    // Process-wide compiler replay defaults to global visibility because the
    // matching deallocation may happen on a different thread after the stream
    // cursor has advanced.  Benchmark harnesses that prove same-thread replay
    // can opt into TLS recovery so every allocation does not take the global
    // recovery-table lock.
    // Auto compiler selection copies its config generation's recovery policy
    // into this hint before releasing AUTO_METADATA_CONFIG. Explicit compiler
    // metadata uses the same public hint. Never re-read mutable process config
    // here: disable/reconfigure and finite-stream exhaustion may occur between
    // metadata selection and recovery-record installation.
    metadata.placement_hint & PLACEMENT_HINT_CROSS_THREAD_RECOVERY != 0
}

#[inline]
fn auto_allocation_record_slot(ptr: *mut u8) -> usize {
    let mut value = (ptr as usize) >> 4;
    value ^= value >> 17;
    value ^= value >> 33;
    value.wrapping_mul(0x517c_c1b7usize) & (AUTO_ALLOCATION_RECORD_SLOTS - 1)
}

#[inline]
fn auto_allocation_record_shard_and_slot(ptr: *mut u8) -> (usize, usize) {
    let slot = auto_allocation_record_slot(ptr);
    (
        slot / AUTO_ALLOCATION_RECORD_SHARD_SLOTS,
        slot & (AUTO_ALLOCATION_RECORD_SHARD_SLOTS - 1),
    )
}

#[inline]
fn auto_allocation_record_shard(ptr: *mut u8) -> usize {
    auto_allocation_record_shard_and_slot(ptr).0
}

#[inline]
fn next_auto_allocation_record_shard(home_shard_idx: usize, shard_offset: usize) -> usize {
    (home_shard_idx + shard_offset) & AUTO_ALLOCATION_RECORD_SHARD_MASK
}

#[inline]
fn auto_allocation_record_shard_bit(shard_idx: usize) -> usize {
    1usize << shard_idx
}

#[inline]
fn auto_allocation_record_active_shards() -> usize {
    AUTO_ALLOCATION_RECORD_ACTIVE_SHARDS.load(Ordering::Acquire)
}

#[inline]
fn auto_allocation_record_shard_is_active(active_mask: usize, shard_idx: usize) -> bool {
    active_mask & auto_allocation_record_shard_bit(shard_idx) != 0
}

#[inline]
fn auto_allocation_record_all_shards_mask() -> usize {
    (1usize << AUTO_ALLOCATION_RECORD_SHARD_COUNT) - 1
}

#[inline]
fn auto_allocation_record_active_offsets_from_home(
    active_mask: usize,
    home_shard_idx: usize,
) -> usize {
    let active_mask = active_mask & auto_allocation_record_all_shards_mask();
    if home_shard_idx == 0 {
        active_mask
    } else {
        ((active_mask >> home_shard_idx)
            | (active_mask << (AUTO_ALLOCATION_RECORD_SHARD_COUNT - home_shard_idx)))
            & auto_allocation_record_all_shards_mask()
    }
}

#[inline]
fn auto_allocation_record_probe_offsets_including_home(
    active_mask: usize,
    home_shard_idx: usize,
) -> usize {
    if active_mask == 0 {
        auto_allocation_record_all_shards_mask()
    } else {
        // The active-shard mask is a lock-skipping hint, not an authority for
        // where the pointer's home slot may be.  Include offset zero even if a
        // stale mask forgot the home bit; insertion already uses this policy,
        // and recovery must not be weaker than recording.
        auto_allocation_record_active_offsets_from_home(active_mask, home_shard_idx) | 1usize
    }
}

#[inline]
fn pop_next_auto_allocation_record_active_shard(
    home_shard_idx: usize,
    active_offsets: &mut usize,
) -> Option<(usize, usize)> {
    if *active_offsets == 0 {
        return None;
    }
    let shard_offset = active_offsets.trailing_zeros() as usize;
    *active_offsets &= *active_offsets - 1;
    Some((
        next_auto_allocation_record_shard(home_shard_idx, shard_offset),
        shard_offset,
    ))
}

#[inline]
fn auto_allocation_record_mark_shard_active(shard_idx: usize) {
    AUTO_ALLOCATION_RECORD_ACTIVE_SHARDS.fetch_or(
        auto_allocation_record_shard_bit(shard_idx),
        Ordering::Release,
    );
}

#[inline]
fn auto_allocation_record_clear_shard_active(shard_idx: usize) {
    AUTO_ALLOCATION_RECORD_ACTIVE_SHARDS.fetch_and(
        !auto_allocation_record_shard_bit(shard_idx),
        Ordering::Release,
    );
}

#[inline]
fn fast_auto_allocation_record_slot(ptr: *mut u8) -> usize {
    let mut value = (ptr as usize) >> 4;
    value ^= value >> 16;
    value ^= value >> 32;
    value.wrapping_mul(0x9e37_79b1usize) & (FAST_AUTO_ALLOCATION_RECORD_SLOTS - 1)
}

#[inline]
fn fast_auto_allocation_record_auth(
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
) -> u64 {
    if metadata_integrity_required(metadata) {
        derive_auto_allocation_record_auth(ptr, layout, metadata)
    } else {
        0
    }
}

#[inline]
fn fast_auto_allocation_record_auth_matches(
    ptr: *mut u8,
    layout: Layout,
    record: AutoAllocationRecord,
) -> bool {
    if record.auth == 0 && !metadata_integrity_required(record.metadata) {
        true
    } else {
        record.auth == derive_auto_allocation_record_auth(ptr, layout, record.metadata)
    }
}

#[inline]
fn global_auto_allocation_record_auth(
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
) -> u64 {
    if auto_allocation_record_tracks_publisher_thread(metadata) {
        current_auto_allocation_publisher_thread_token()
    } else {
        fast_auto_allocation_record_auth(ptr, layout, metadata)
    }
}

#[inline]
fn fast_auto_allocation_record_for(
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
) -> AutoAllocationRecord {
    AutoAllocationRecord {
        ptr: ptr as usize,
        size: layout.size(),
        align: layout.align(),
        auth: fast_auto_allocation_record_auth(ptr, layout, metadata),
        metadata,
    }
}

#[inline]
fn auto_allocation_record_for(
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
) -> AutoAllocationRecord {
    debug_assert_eq!(
        layout.align() & AUTO_ALLOCATION_RECORD_INTEGRITY_ALIGN_BIT,
        0,
        "valid allocation alignment must leave the recovery integrity marker available"
    );
    AutoAllocationRecord {
        ptr: ptr as usize,
        size: layout.size(),
        align: layout.align()
            | if metadata_integrity_required(metadata) {
                AUTO_ALLOCATION_RECORD_INTEGRITY_ALIGN_BIT
            } else {
                0
            },
        // Recovery metadata requests authenticated storage explicitly through
        // the metadata-protection/PAC policy flags. Plain type isolation keeps
        // the same private-table trust boundary as the TLS recovery tier and
        // avoids hashing eight metadata fields twice per allocation lifetime.
        auth: global_auto_allocation_record_auth(ptr, layout, metadata),
        metadata,
    }
}

#[cfg(not(feature = "fixed_heap"))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum AutoAllocationRecordOverflowProbe {
    Found(usize),
    Vacant(usize),
    Full,
}

#[cfg(not(feature = "fixed_heap"))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum AutoAllocationRecordOverflowInsert {
    Updated,
    Inserted,
    Full,
}

#[cfg(not(feature = "fixed_heap"))]
#[inline]
fn auto_allocation_record_overflow_mapping_size(capacity: usize) -> Option<usize> {
    let size = capacity.checked_mul(size_of::<AutoAllocationRecord>())?;
    if size > isize::MAX as usize {
        None
    } else {
        Some(size)
    }
}

#[cfg(not(feature = "fixed_heap"))]
#[inline]
fn auto_allocation_record_overflow_mapping_is_retainable(capacity: usize) -> bool {
    matches!(
        auto_allocation_record_overflow_mapping_size(capacity),
        Some(size) if size <= AUTO_ALLOCATION_RECORD_OVERFLOW_RETAINED_MAPPING_MAX_BYTES
    )
}

#[cfg(not(feature = "fixed_heap"))]
#[inline]
fn auto_allocation_record_overflow_should_retain_after_drain(
    capacity: usize,
    occupied_before_drain: usize,
) -> bool {
    auto_allocation_record_overflow_mapping_is_retainable(capacity)
        && (capacity == AUTO_ALLOCATION_RECORD_OVERFLOW_INITIAL_CAPACITY
            || occupied_before_drain >= capacity / 4)
}

#[cfg(not(feature = "fixed_heap"))]
#[inline]
fn auto_allocation_record_overflow_is_empty(overflow: &AutoAllocationRecordOverflowTable) -> bool {
    overflow.slots.is_null()
        && overflow.capacity == 0
        && overflow.live == 0
        && overflow.tombstones == 0
        && overflow.retention == AutoAllocationRecordOverflowRetention::None
}

#[cfg(not(feature = "fixed_heap"))]
#[inline]
fn auto_allocation_record_overflow_is_mapped_valid(
    overflow: &AutoAllocationRecordOverflowTable,
) -> bool {
    !overflow.slots.is_null()
        && overflow.capacity.is_power_of_two()
        && overflow.live.saturating_add(overflow.tombstones) <= overflow.capacity
        && (overflow.retention == AutoAllocationRecordOverflowRetention::None
            || (overflow.live == 0 && overflow.tombstones == 0))
}

#[cfg(not(feature = "fixed_heap"))]
#[inline]
fn auto_allocation_record_overflow_start(ptr_key: usize, capacity: usize) -> usize {
    debug_assert!(capacity.is_power_of_two());
    let hash = type_cache_avalanche(((ptr_key >> 4) as u64) ^ 0xa076_1d64_78bd_642f);
    hash as usize & (capacity - 1)
}

#[cfg(not(feature = "fixed_heap"))]
unsafe fn allocate_auto_allocation_record_overflow_slots(
    capacity: usize,
) -> *mut AutoAllocationRecord {
    if !capacity.is_power_of_two() || capacity == 0 {
        return core::ptr::null_mut();
    }
    #[cfg(test)]
    if TEST_FAIL_NEXT_GLOBAL_RECOVERY_OVERFLOW_MMAP.swap(false, Ordering::AcqRel) {
        return core::ptr::null_mut();
    }
    let mapping_size = match auto_allocation_record_overflow_mapping_size(capacity) {
        Some(size) => size,
        None => return core::ptr::null_mut(),
    };
    let prot = system_alloc::prots::get_prot(true, true, false);
    let slots = system_alloc::mmap(mapping_size, prot) as *mut AutoAllocationRecord;
    if slots.is_null() || slots as usize == usize::MAX {
        return core::ptr::null_mut();
    }
    // Anonymous mappings are zero-filled. `ptr == 0` is the authoritative empty
    // marker, so no allocator-recursive initialization pass is needed here.
    slots
}

#[cfg(not(feature = "fixed_heap"))]
unsafe fn release_auto_allocation_record_overflow_slots(
    slots: *mut AutoAllocationRecord,
    capacity: usize,
) {
    if slots.is_null() {
        return;
    }
    let mapping_size = auto_allocation_record_overflow_mapping_size(capacity)
        .expect("live recovery overflow mapping size must remain representable");
    #[cfg(test)]
    TEST_GLOBAL_RECOVERY_OVERFLOW_UNMAP_CALLS.fetch_add(1, Ordering::Relaxed);
    system_alloc::munmap(slots as *mut u8, mapping_size);
}

#[cfg(not(feature = "fixed_heap"))]
fn probe_auto_allocation_record_overflow(
    overflow: &AutoAllocationRecordOverflowTable,
    ptr_key: usize,
) -> AutoAllocationRecordOverflowProbe {
    if !auto_allocation_record_overflow_is_mapped_valid(overflow) {
        return AutoAllocationRecordOverflowProbe::Full;
    }
    debug_assert!(overflow.capacity.is_power_of_two());
    let start = auto_allocation_record_overflow_start(ptr_key, overflow.capacity);
    let mut first_tombstone = None;
    let mut offset = 0usize;
    while offset < overflow.capacity {
        #[cfg(test)]
        TEST_GLOBAL_RECOVERY_OVERFLOW_PROBE_STEPS.fetch_add(1, Ordering::Relaxed);
        let idx = (start + offset) & (overflow.capacity - 1);
        let record = unsafe { *overflow.slots.add(idx) };
        if record.ptr == ptr_key {
            return AutoAllocationRecordOverflowProbe::Found(idx);
        }
        if record.is_empty() {
            return AutoAllocationRecordOverflowProbe::Vacant(first_tombstone.unwrap_or(idx));
        }
        if record.is_tombstone() && first_tombstone.is_none() {
            first_tombstone = Some(idx);
        }
        offset += 1;
    }
    match first_tombstone {
        Some(idx) => AutoAllocationRecordOverflowProbe::Vacant(idx),
        None => AutoAllocationRecordOverflowProbe::Full,
    }
}

#[cfg(not(feature = "fixed_heap"))]
fn find_auto_allocation_record_in_overflow(
    overflow: &AutoAllocationRecordOverflowTable,
    ptr_key: usize,
) -> Option<*mut AutoAllocationRecord> {
    match probe_auto_allocation_record_overflow(overflow, ptr_key) {
        AutoAllocationRecordOverflowProbe::Found(idx) => Some(unsafe { overflow.slots.add(idx) }),
        AutoAllocationRecordOverflowProbe::Vacant(_) | AutoAllocationRecordOverflowProbe::Full => {
            None
        }
    }
}

#[cfg(not(feature = "fixed_heap"))]
unsafe fn rehash_auto_allocation_record_overflow(
    shard_idx: usize,
    overflow: &mut AutoAllocationRecordOverflowTable,
    new_capacity: usize,
) -> bool {
    let old_is_empty = auto_allocation_record_overflow_is_empty(overflow);
    let old_is_mapped = auto_allocation_record_overflow_is_mapped_valid(overflow);
    if (!old_is_empty && !old_is_mapped)
        || !new_capacity.is_power_of_two()
        || new_capacity == 0
        || new_capacity < overflow.live
    {
        return false;
    }
    #[cfg(test)]
    if TEST_FAIL_NEXT_GLOBAL_RECOVERY_OVERFLOW_REHASH.swap(false, Ordering::AcqRel) {
        return false;
    }
    let new_slots = allocate_auto_allocation_record_overflow_slots(new_capacity);
    if new_slots.is_null() {
        return false;
    }
    let mut replacement = AutoAllocationRecordOverflowTable {
        slots: new_slots,
        capacity: new_capacity,
        live: 0,
        tombstones: 0,
        retention: AutoAllocationRecordOverflowRetention::None,
    };

    let mut old_idx = 0usize;
    let mut old_tombstones = 0usize;
    while old_idx < overflow.capacity {
        let record = *overflow.slots.add(old_idx);
        if record.is_tombstone() {
            old_tombstones += 1;
        } else if !record.is_empty() {
            if auto_allocation_record_shard(record.ptr as *mut u8) != shard_idx {
                release_auto_allocation_record_overflow_slots(
                    replacement.slots,
                    replacement.capacity,
                );
                return false;
            }
            match probe_auto_allocation_record_overflow(&replacement, record.ptr) {
                AutoAllocationRecordOverflowProbe::Vacant(new_idx) => {
                    *replacement.slots.add(new_idx) = record;
                    replacement.live += 1;
                }
                AutoAllocationRecordOverflowProbe::Found(_)
                | AutoAllocationRecordOverflowProbe::Full => {
                    release_auto_allocation_record_overflow_slots(
                        replacement.slots,
                        replacement.capacity,
                    );
                    return false;
                }
            }
        }
        old_idx += 1;
    }
    if replacement.live != overflow.live || old_tombstones != overflow.tombstones {
        release_auto_allocation_record_overflow_slots(replacement.slots, replacement.capacity);
        return false;
    }

    let old = *overflow;
    *overflow = replacement;
    release_auto_allocation_record_overflow_slots(old.slots, old.capacity);
    true
}

#[cfg(not(feature = "fixed_heap"))]
unsafe fn insert_auto_allocation_record_overflow(
    shard_idx: usize,
    overflow: &mut AutoAllocationRecordOverflowTable,
    record: AutoAllocationRecord,
) -> AutoAllocationRecordOverflowInsert {
    if auto_allocation_record_shard(record.ptr as *mut u8) != shard_idx {
        return AutoAllocationRecordOverflowInsert::Full;
    }
    let mut probe = probe_auto_allocation_record_overflow(overflow, record.ptr);
    if let AutoAllocationRecordOverflowProbe::Found(idx) = probe {
        *overflow.slots.add(idx) = record;
        overflow.retention = AutoAllocationRecordOverflowRetention::None;
        return AutoAllocationRecordOverflowInsert::Updated;
    }

    let occupied = overflow.live.saturating_add(overflow.tombstones);
    let load_limit = overflow.capacity / AUTO_ALLOCATION_RECORD_OVERFLOW_LOAD_DENOMINATOR
        * AUTO_ALLOCATION_RECORD_OVERFLOW_LOAD_NUMERATOR;
    let rebuild_needed = overflow.capacity == 0 || occupied.saturating_add(1) > load_limit;
    if rebuild_needed {
        let new_capacity = if overflow.capacity == 0 {
            Some(AUTO_ALLOCATION_RECORD_OVERFLOW_INITIAL_CAPACITY)
        } else {
            let live_after_insert = overflow.live.saturating_add(1);
            if live_after_insert > load_limit {
                overflow.capacity.checked_mul(2)
            } else {
                Some(overflow.capacity)
            }
        };
        let new_capacity = match new_capacity {
            Some(new_capacity) => new_capacity,
            None => return AutoAllocationRecordOverflowInsert::Full,
        };
        if !rehash_auto_allocation_record_overflow(shard_idx, overflow, new_capacity) {
            // Resource failures and invariant failures share one fail-closed
            // result. The old descriptor remains byte-for-byte authoritative,
            // and the new identity never becomes partially visible.
            return AutoAllocationRecordOverflowInsert::Full;
        }
        probe = probe_auto_allocation_record_overflow(overflow, record.ptr);
        if let AutoAllocationRecordOverflowProbe::Found(idx) = probe {
            *overflow.slots.add(idx) = record;
            overflow.retention = AutoAllocationRecordOverflowRetention::None;
            return AutoAllocationRecordOverflowInsert::Updated;
        }
    }

    let idx = match probe {
        AutoAllocationRecordOverflowProbe::Vacant(idx) => idx,
        AutoAllocationRecordOverflowProbe::Found(idx) => {
            *overflow.slots.add(idx) = record;
            overflow.retention = AutoAllocationRecordOverflowRetention::None;
            return AutoAllocationRecordOverflowInsert::Updated;
        }
        AutoAllocationRecordOverflowProbe::Full => {
            return AutoAllocationRecordOverflowInsert::Full;
        }
    };
    if (*overflow.slots.add(idx)).is_tombstone() {
        overflow.tombstones = overflow.tombstones.saturating_sub(1);
    }
    *overflow.slots.add(idx) = record;
    overflow.live = overflow.live.saturating_add(1);
    overflow.retention = AutoAllocationRecordOverflowRetention::None;
    AutoAllocationRecordOverflowInsert::Inserted
}

#[cfg(not(feature = "fixed_heap"))]
unsafe fn insert_filtered_auto_allocation_record_overflow(
    shard_idx: usize,
    overflow: &mut AutoAllocationRecordOverflowTable,
    record: AutoAllocationRecord,
) -> AutoAllocationRecordOverflowInsert {
    // The extra publication is conservative while an update/full result is
    // resolved under the authoritative shard lock. Only a new record keeps it.
    increment_global_recovery_pointer_filter(record.ptr as *mut u8);
    let result = insert_auto_allocation_record_overflow(shard_idx, overflow, record);
    if result != AutoAllocationRecordOverflowInsert::Inserted {
        decrement_global_recovery_pointer_filter(record.ptr as *mut u8);
    }
    result
}

#[cfg(not(feature = "fixed_heap"))]
unsafe fn try_remove_auto_allocation_record_overflow_at(
    shard_idx: usize,
    overflow: &mut AutoAllocationRecordOverflowTable,
    idx: usize,
) -> bool {
    if !auto_allocation_record_overflow_is_mapped_valid(overflow)
        || idx >= overflow.capacity
        || overflow.live == 0
        || (*overflow.slots.add(idx)).is_available()
    {
        return false;
    }
    if overflow.live == 1 {
        let mut actual_live = 0usize;
        let mut actual_tombstones = 0usize;
        let mut scan_idx = 0usize;
        while scan_idx < overflow.capacity {
            let record = *overflow.slots.add(scan_idx);
            if record.is_tombstone() {
                actual_tombstones += 1;
            } else if !record.is_empty() {
                actual_live += 1;
                if auto_allocation_record_shard(record.ptr as *mut u8) != shard_idx {
                    return false;
                }
            }
            scan_idx += 1;
        }
        if actual_live != overflow.live || actual_tombstones != overflow.tombstones {
            return false;
        }
        if auto_allocation_record_overflow_should_retain_after_drain(
            overflow.capacity,
            actual_live.saturating_add(actual_tombstones),
        ) {
            let mapping_size = auto_allocation_record_overflow_mapping_size(overflow.capacity)
                .expect("validated recovery overflow mapping size");
            // Validate before mutation so a logical count or home-shard
            // inconsistency remains byte-for-byte available for fail-closed
            // diagnosis. The shard lock excludes concurrent probes while the
            // retained mapping is reset for the next burst.
            core::ptr::write_bytes(overflow.slots as *mut u8, 0, mapping_size);
            overflow.live = 0;
            overflow.tombstones = 0;
            overflow.retention =
                if overflow.capacity == AUTO_ALLOCATION_RECORD_OVERFLOW_INITIAL_CAPACITY {
                    AutoAllocationRecordOverflowRetention::None
                } else {
                    AutoAllocationRecordOverflowRetention::Fresh
                };
        } else {
            let old = *overflow;
            *overflow = AutoAllocationRecordOverflowTable::empty();
            release_auto_allocation_record_overflow_slots(old.slots, old.capacity);
        }
        return true;
    }
    *overflow.slots.add(idx) = AutoAllocationRecord::tombstone();
    overflow.live -= 1;
    overflow.tombstones = overflow.tombstones.saturating_add(1);
    true
}

/// Destructively reset recovery bookkeeping for isolated tests.
///
/// Production auto-metadata control changes must never call this helper: a
/// recovery record belongs to its live allocation, not to the currently
/// selected auto-metadata configuration. Callers must prove that no live
/// allocation can still own any record before resetting this state.
#[cfg(test)]
fn clear_auto_allocation_records() {
    for table_lock in AUTO_ALLOCATION_RECORDS.iter() {
        let mut table = table_lock.lock();
        #[cfg(not(feature = "fixed_heap"))]
        {
            let overflow = table.overflow;
            table.overflow = AutoAllocationRecordOverflowTable::empty();
            unsafe {
                release_auto_allocation_record_overflow_slots(overflow.slots, overflow.capacity);
            }
        }
        *table = GlobalAutoAllocationRecordTable::empty();
    }
    AUTO_ALLOCATION_RECORD_COUNT.store(0, Ordering::Relaxed);
    clear_semantic_pointer_filter_contributions_for_test(
        &TEST_RECOVERY_POINTER_FILTER_CONTRIBUTIONS,
    );
    AUTO_ALLOCATION_RECORD_ACTIVE_SHARDS.store(0, Ordering::Release);
    #[cfg(not(feature = "fixed_heap"))]
    AUTO_ALLOCATION_RECORD_LEGACY_NON_HOME_POSSIBLE.store(false, Ordering::Release);
    unsafe {
        FAST_AUTO_ALLOCATION_RECORD_INLINE = AutoAllocationRecord::empty();
        FAST_AUTO_ALLOCATION_RECORDS =
            [AutoAllocationRecord::empty(); FAST_AUTO_ALLOCATION_RECORD_SLOTS];
        FAST_AUTO_ALLOCATION_RECORD_COUNT = 0;
        FAST_AUTO_ALLOCATION_RECORD_HOT_SLOT = FastAutoAllocationRecordHotSlot::empty();
    }
    #[cfg(test)]
    FAST_AUTO_ALLOCATION_RECORD_PROBE_STEPS.store(0, Ordering::Relaxed);
    #[cfg(all(test, not(feature = "fixed_heap")))]
    TEST_GLOBAL_RECOVERY_OVERFLOW_PROBE_STEPS.store(0, Ordering::Relaxed);
    #[cfg(all(test, not(feature = "fixed_heap")))]
    TEST_FAIL_NEXT_GLOBAL_RECOVERY_OVERFLOW_MMAP.store(false, Ordering::Release);
    #[cfg(all(test, not(feature = "fixed_heap")))]
    TEST_FAIL_NEXT_GLOBAL_RECOVERY_OVERFLOW_REHASH.store(false, Ordering::Release);
    FAST_AUTO_ALLOCATION_RECORD_GLOBAL_COUNT.store(0, Ordering::Relaxed);
    semantic_slow_path_clear(SLOW_PATH_ALLOCATION_RECORDS);
}

#[inline]
unsafe fn remember_fast_auto_allocation_record_hot_slot(ptr_key: usize, slot_idx: usize) {
    FAST_AUTO_ALLOCATION_RECORD_HOT_SLOT = FastAutoAllocationRecordHotSlot {
        ptr: ptr_key,
        slot_idx,
    };
}

#[inline]
unsafe fn clear_fast_auto_allocation_record_hot_slot(ptr_key: usize) {
    if FAST_AUTO_ALLOCATION_RECORD_HOT_SLOT.ptr == ptr_key {
        FAST_AUTO_ALLOCATION_RECORD_HOT_SLOT = FastAutoAllocationRecordHotSlot::empty();
    }
}

#[inline]
unsafe fn fast_auto_allocation_record_hot_slot(ptr_key: usize) -> Option<usize> {
    let hot = FAST_AUTO_ALLOCATION_RECORD_HOT_SLOT;
    if hot.ptr == ptr_key {
        Some(hot.slot_idx & (FAST_AUTO_ALLOCATION_RECORD_SLOTS - 1))
    } else {
        None
    }
}

#[inline]
fn remember_global_auto_allocation_record_hot_slot(
    table: &mut GlobalAutoAllocationRecordTable,
    ptr_key: usize,
    slot_idx: usize,
) {
    table.hot = GlobalAutoAllocationRecordHotSlot {
        ptr: ptr_key,
        slot_idx,
    };
}

#[inline]
fn clear_global_auto_allocation_record_hot_slot(
    table: &mut GlobalAutoAllocationRecordTable,
    ptr_key: usize,
) {
    if table.hot.ptr == ptr_key {
        table.hot = GlobalAutoAllocationRecordHotSlot::empty();
    }
}

#[inline]
fn global_auto_allocation_record_hot_slot(
    table: &GlobalAutoAllocationRecordTable,
    ptr_key: usize,
) -> Option<usize> {
    if table.hot.ptr == ptr_key {
        Some(table.hot.slot_idx & (AUTO_ALLOCATION_RECORD_SHARD_SLOTS - 1))
    } else {
        None
    }
}

#[inline]
fn increment_global_auto_allocation_record_shard_live_count(
    shard_idx: usize,
    table: &mut GlobalAutoAllocationRecordTable,
) {
    let was_empty = table.live_count == 0;
    table.live_count = table.live_count.saturating_add(1);
    if was_empty {
        auto_allocation_record_mark_shard_active(shard_idx);
    }
}

#[cfg(not(feature = "fixed_heap"))]
#[inline]
fn advance_or_release_empty_retained_auto_allocation_record_overflow(
    table: &mut GlobalAutoAllocationRecordTable,
) {
    if table.live_count != 0
        || !auto_allocation_record_overflow_is_mapped_valid(&table.overflow)
        || table.overflow.live != 0
        || table.overflow.tombstones != 0
    {
        return;
    }

    match table.overflow.retention {
        AutoAllocationRecordOverflowRetention::Fresh => {
            // Preserve one recently useful high-water mapping for the next
            // complete shard phase. A subsequent overflow insertion disarms
            // this state; an inline-only phase advances it to release below.
            table.overflow.retention = AutoAllocationRecordOverflowRetention::Armed;
        }
        AutoAllocationRecordOverflowRetention::Armed => {
            let old = table.overflow;
            table.overflow = AutoAllocationRecordOverflowTable::empty();
            unsafe {
                release_auto_allocation_record_overflow_slots(old.slots, old.capacity);
            }
        }
        AutoAllocationRecordOverflowRetention::None => {}
    }
}

#[inline]
fn decrement_global_auto_allocation_record_shard_live_count(
    shard_idx: usize,
    table: &mut GlobalAutoAllocationRecordTable,
) {
    let becomes_empty = table.live_count <= 1;
    table.live_count = table.live_count.saturating_sub(1);
    if becomes_empty {
        #[cfg(not(feature = "fixed_heap"))]
        advance_or_release_empty_retained_auto_allocation_record_overflow(table);
        auto_allocation_record_clear_shard_active(shard_idx);
    }
}

#[cfg(test)]
fn pause_after_last_global_recovery_count_decrement_for_test() {
    if TEST_LAST_GLOBAL_RECOVERY_REMOVE_PHASE
        .compare_exchange(1, 2, Ordering::AcqRel, Ordering::Acquire)
        .is_ok()
    {
        while TEST_LAST_GLOBAL_RECOVERY_REMOVE_PHASE.load(Ordering::Acquire) == 2 {
            core::hint::spin_loop();
        }
    }
}

#[cfg(test)]
fn pause_after_recovery_record_insert_for_test(recorded: bool) {
    if recorded
        && TEST_RECOVERY_RECORD_INSERT_PHASE
            .compare_exchange(1, 2, Ordering::AcqRel, Ordering::Acquire)
            .is_ok()
    {
        while TEST_RECOVERY_RECORD_INSERT_PHASE.load(Ordering::Acquire) == 2 {
            core::hint::spin_loop();
        }
    }
}

#[inline]
unsafe fn record_fast_auto_allocation_metadata_eligible(
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
) -> bool {
    let ptr_key = ptr as usize;

    let inline_record = FAST_AUTO_ALLOCATION_RECORD_INLINE;
    if inline_record.is_empty() || inline_record.ptr == ptr_key {
        if inline_record.is_empty() {
            fast_auto_allocation_record_global_activate();
        }
        FAST_AUTO_ALLOCATION_RECORD_INLINE = fast_auto_allocation_record_for(ptr, layout, metadata);
        return true;
    }

    let mut checked_hot_idx = None;
    if let Some(idx) = fast_auto_allocation_record_hot_slot(ptr_key) {
        checked_hot_idx = Some(idx);
        record_fast_auto_allocation_record_probe_step();
        let record = FAST_AUTO_ALLOCATION_RECORDS[idx];
        if record.ptr == ptr_key || record.is_available() {
            if record.is_available() {
                FAST_AUTO_ALLOCATION_RECORD_COUNT =
                    FAST_AUTO_ALLOCATION_RECORD_COUNT.saturating_add(1);
                fast_auto_allocation_record_global_activate();
            }
            FAST_AUTO_ALLOCATION_RECORDS[idx] =
                fast_auto_allocation_record_for(ptr, layout, metadata);
            return true;
        }
        // The hot hint is pointer-specific.  If the hinted slot now contains a
        // different live record, keep probing for an available slot but do not
        // let future calls repeatedly pay this stale hot check.
        clear_fast_auto_allocation_record_hot_slot(ptr_key);
    }

    let start = fast_auto_allocation_record_slot(ptr);
    let mut first_available = None;
    let mut offset = 0;
    while offset < FAST_AUTO_ALLOCATION_RECORD_PROBE_LIMIT {
        let idx = (start + offset) & (FAST_AUTO_ALLOCATION_RECORD_SLOTS - 1);
        if fast_auto_allocation_record_probe_already_checked(checked_hot_idx, idx) {
            offset += 1;
            continue;
        }
        record_fast_auto_allocation_record_probe_step();
        let record = FAST_AUTO_ALLOCATION_RECORDS[idx];
        if record.ptr == ptr_key {
            FAST_AUTO_ALLOCATION_RECORDS[idx] =
                fast_auto_allocation_record_for(ptr, layout, metadata);
            remember_fast_auto_allocation_record_hot_slot(ptr_key, idx);
            return true;
        }
        if record.is_available() && first_available.is_none() {
            first_available = Some(idx);
            if record.is_empty() {
                break;
            }
        }
        offset += 1;
    }

    let idx = match first_available {
        Some(idx) => idx,
        None => return false,
    };
    if FAST_AUTO_ALLOCATION_RECORDS[idx].is_available() {
        FAST_AUTO_ALLOCATION_RECORD_COUNT = FAST_AUTO_ALLOCATION_RECORD_COUNT.saturating_add(1);
        fast_auto_allocation_record_global_activate();
    }
    FAST_AUTO_ALLOCATION_RECORDS[idx] = fast_auto_allocation_record_for(ptr, layout, metadata);
    remember_fast_auto_allocation_record_hot_slot(ptr_key, idx);
    true
}

fn lookup_fast_auto_allocation_record(
    ptr: *mut u8,
    layout: Layout,
    remove: bool,
) -> AutoAllocationRecordLookup {
    let ptr_key = ptr as usize;
    if ptr.is_null()
        || ptr_key == AUTO_ALLOCATION_RECORD_TOMBSTONE_PTR
        || layout.size() == 0
        || !current_thread_fast_auto_allocation_records_active()
    {
        return AutoAllocationRecordLookup::Missing;
    }

    unsafe {
        let inline_record = FAST_AUTO_ALLOCATION_RECORD_INLINE;
        if inline_record.ptr == ptr_key {
            if inline_record.size == layout.size()
                && inline_record.align == layout.align()
                && fast_auto_allocation_record_auth_matches(ptr, layout, inline_record)
            {
                if remove {
                    FAST_AUTO_ALLOCATION_RECORD_INLINE = AutoAllocationRecord::empty();
                    fast_auto_allocation_record_global_deactivate();
                }
                return AutoAllocationRecordLookup::exact(inline_record);
            }
            return AutoAllocationRecordLookup::Mismatched(
                AutoAllocationRecordMismatch::from_record(inline_record),
            );
        }

        let mut checked_hot_idx = None;
        if let Some(idx) = fast_auto_allocation_record_hot_slot(ptr_key) {
            record_fast_auto_allocation_record_probe_step();
            let record = FAST_AUTO_ALLOCATION_RECORDS[idx];
            if record.ptr == ptr_key {
                if record.size == layout.size()
                    && record.align == layout.align()
                    && fast_auto_allocation_record_auth_matches(ptr, layout, record)
                {
                    if remove {
                        FAST_AUTO_ALLOCATION_RECORD_COUNT =
                            FAST_AUTO_ALLOCATION_RECORD_COUNT.saturating_sub(1);
                        fast_auto_allocation_record_global_deactivate();
                        FAST_AUTO_ALLOCATION_RECORDS[idx] =
                            if FAST_AUTO_ALLOCATION_RECORD_COUNT == 0 {
                                AutoAllocationRecord::empty()
                            } else {
                                AutoAllocationRecord::tombstone()
                            };
                    }
                    return AutoAllocationRecordLookup::exact(record);
                }
                return AutoAllocationRecordLookup::Mismatched(
                    AutoAllocationRecordMismatch::from_record(record),
                );
            }
            // A stale non-empty/tombstone hot slot has already been inspected;
            // skip it in the bounded probe below.  If it is empty, preserve the
            // old empty-stop semantics by letting the normal probe see it.
            if !record.is_empty() {
                checked_hot_idx = Some(idx);
            }
            clear_fast_auto_allocation_record_hot_slot(ptr_key);
        }

        let start = fast_auto_allocation_record_slot(ptr);
        let mut offset = 0;
        while offset < FAST_AUTO_ALLOCATION_RECORD_PROBE_LIMIT {
            let idx = (start + offset) & (FAST_AUTO_ALLOCATION_RECORD_SLOTS - 1);
            if fast_auto_allocation_record_probe_already_checked(checked_hot_idx, idx) {
                offset += 1;
                continue;
            }
            record_fast_auto_allocation_record_probe_step();
            let record = FAST_AUTO_ALLOCATION_RECORDS[idx];
            if record.is_empty() {
                return AutoAllocationRecordLookup::Missing;
            }
            if record.ptr == ptr_key {
                if record.size == layout.size()
                    && record.align == layout.align()
                    && fast_auto_allocation_record_auth_matches(ptr, layout, record)
                {
                    if remove {
                        FAST_AUTO_ALLOCATION_RECORD_COUNT =
                            FAST_AUTO_ALLOCATION_RECORD_COUNT.saturating_sub(1);
                        fast_auto_allocation_record_global_deactivate();
                        // This TLS table is on the compiler-scoped alloc/dealloc hot path.  The
                        // previous implementation zeroed every TLS slot whenever the last
                        // outstanding scoped allocation was freed, which made a one-allocation
                        // std_bench leaf spend most of its time clearing bookkeeping memory.  We
                        // only need probe-chain tombstones while other live records remain; when
                        // the table becomes empty, this slot can be cleared in O(1).
                        FAST_AUTO_ALLOCATION_RECORDS[idx] =
                            if FAST_AUTO_ALLOCATION_RECORD_COUNT == 0 {
                                AutoAllocationRecord::empty()
                            } else {
                                AutoAllocationRecord::tombstone()
                            };
                    }
                    remember_fast_auto_allocation_record_hot_slot(ptr_key, idx);
                    return AutoAllocationRecordLookup::exact(record);
                }
                return AutoAllocationRecordLookup::Mismatched(
                    AutoAllocationRecordMismatch::from_record(record),
                );
            }
            offset += 1;
        }
    }
    AutoAllocationRecordLookup::Missing
}

fn recover_fast_auto_allocation_record_metadata(
    ptr: *mut u8,
    layout: Layout,
    remove: bool,
) -> Option<AllocationMetadata> {
    lookup_fast_auto_allocation_record(ptr, layout, remove).exact_metadata()
}

#[inline]
unsafe fn record_auto_allocation_metadata(
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
) -> bool {
    if !auto_allocation_record_eligible(ptr, layout, metadata) {
        return true;
    }

    if auto_allocation_recovery_recording_enabled() {
        return record_recovery_auto_allocation_metadata_eligible(ptr, layout, metadata);
    }

    record_global_auto_allocation_metadata_eligible(ptr, layout, metadata)
}

#[inline]
unsafe fn record_recovery_auto_allocation_metadata_eligible(
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
) -> bool {
    let recorded = if auto_allocation_record_requires_global_visibility(metadata) {
        record_global_auto_allocation_metadata_eligible(ptr, layout, metadata)
    } else if !record_fast_auto_allocation_metadata_eligible(ptr, layout, metadata) {
        record_global_auto_allocation_metadata_eligible(ptr, layout, metadata)
    } else {
        true
    };
    #[cfg(test)]
    pause_after_recovery_record_insert_for_test(recorded);
    recorded
}

#[inline]
unsafe fn record_recovery_auto_allocation_metadata(
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
) -> bool {
    if !auto_allocation_record_eligible(ptr, layout, metadata) {
        return true;
    }

    record_recovery_auto_allocation_metadata_eligible(ptr, layout, metadata)
}

#[inline]
fn install_global_auto_allocation_inline_record(
    shard_idx: usize,
    table: &mut GlobalAutoAllocationRecordTable,
    idx: usize,
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
) -> bool {
    let ptr_key = ptr as usize;
    #[cfg(not(feature = "fixed_heap"))]
    if shard_idx != auto_allocation_record_shard(ptr) {
        // Publish the compatibility gate before the foreign-shard record. A
        // normal hosted process never reaches this branch; it exists for
        // defensive legacy/test state handled by the exhaustive fallback.
        AUTO_ALLOCATION_RECORD_LEGACY_NON_HOME_POSSIBLE.store(true, Ordering::Release);
    }
    let existing = table.inline[idx];
    if existing.ptr != ptr_key && !existing.is_available() {
        return false;
    }
    if existing.is_available() {
        // Publish the negative-filter gate before the record becomes visible.
        increment_global_recovery_pointer_filter(ptr);
        AUTO_ALLOCATION_RECORD_COUNT.fetch_add(1, Ordering::Relaxed);
        increment_global_auto_allocation_record_shard_live_count(shard_idx, table);
    } else {
        auto_allocation_record_mark_shard_active(shard_idx);
    }
    table.inline[idx] = auto_allocation_record_for(ptr, layout, metadata);
    remember_global_auto_allocation_record_hot_slot(table, ptr_key, idx);
    semantic_slow_path_set(SLOW_PATH_ALLOCATION_RECORDS);
    true
}

fn update_global_auto_allocation_record_in_shard(
    shard_idx: usize,
    table: &mut GlobalAutoAllocationRecordTable,
    start: usize,
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
    search_overflow: bool,
    first_available: &mut Option<(usize, usize)>,
) -> bool {
    #[cfg(feature = "fixed_heap")]
    let _ = search_overflow;

    let ptr_key = ptr as usize;
    if let Some(idx) = global_auto_allocation_record_hot_slot(table, ptr_key) {
        let record = table.inline[idx];
        if record.ptr == ptr_key {
            auto_allocation_record_mark_shard_active(shard_idx);
            table.inline[idx] = auto_allocation_record_for(ptr, layout, metadata);
            remember_global_auto_allocation_record_hot_slot(table, ptr_key, idx);
            semantic_slow_path_set(SLOW_PATH_ALLOCATION_RECORDS);
            return true;
        }
        if record.is_available() && first_available.is_none() {
            *first_available = Some((shard_idx, idx));
        } else {
            clear_global_auto_allocation_record_hot_slot(table, ptr_key);
        }
    }

    let mut offset = 0;
    while offset < AUTO_ALLOCATION_RECORD_PROBE_LIMIT {
        let idx = (start + offset) & (AUTO_ALLOCATION_RECORD_SHARD_SLOTS - 1);
        let record = table.inline[idx];
        if record.ptr == ptr_key {
            auto_allocation_record_mark_shard_active(shard_idx);
            table.inline[idx] = auto_allocation_record_for(ptr, layout, metadata);
            remember_global_auto_allocation_record_hot_slot(table, ptr_key, idx);
            semantic_slow_path_set(SLOW_PATH_ALLOCATION_RECORDS);
            return true;
        }
        if record.is_available() {
            if first_available.is_none() {
                *first_available = Some((shard_idx, idx));
            }
            if record.is_empty() {
                break;
            }
        }
        offset += 1;
    }

    #[cfg(feature = "fixed_heap")]
    {
        // fixed_heap builds do not have an mmap-backed overflow table. Scan the
        // rest of this shard after the bounded hot probe, then continue to
        // later shards so total inline capacity remains 4096 records.
        let mut slow_offset = AUTO_ALLOCATION_RECORD_PROBE_LIMIT;
        while slow_offset < AUTO_ALLOCATION_RECORD_SHARD_SLOTS {
            let idx = (start + slow_offset) & (AUTO_ALLOCATION_RECORD_SHARD_SLOTS - 1);
            let record = table.inline[idx];
            if record.ptr == ptr_key {
                auto_allocation_record_mark_shard_active(shard_idx);
                table.inline[idx] = auto_allocation_record_for(ptr, layout, metadata);
                remember_global_auto_allocation_record_hot_slot(table, ptr_key, idx);
                semantic_slow_path_set(SLOW_PATH_ALLOCATION_RECORDS);
                return true;
            }
            if record.is_available() {
                if first_available.is_none() {
                    *first_available = Some((shard_idx, idx));
                }
                if record.is_empty() {
                    break;
                }
            }
            slow_offset += 1;
        }
    }

    #[cfg(not(feature = "fixed_heap"))]
    {
        // The overflow table belongs only to the pointer's home shard after
        // every shard-local inline table is full.  Inline records may live in a
        // different shard to preserve the historical global inline capacity,
        // but overflow records do not migrate.  Skipping non-home overflow
        // chains avoids scanning unrelated cold pages under their shard locks
        // and prevents a corrupt impossible non-home overflow entry from
        // shadowing the authoritative home-shard record.
        if search_overflow {
            if let Some(slot) = find_auto_allocation_record_in_overflow(&table.overflow, ptr_key) {
                auto_allocation_record_mark_shard_active(shard_idx);
                unsafe {
                    *slot = auto_allocation_record_for(ptr, layout, metadata);
                }
                semantic_slow_path_set(SLOW_PATH_ALLOCATION_RECORDS);
                return true;
            }
        }
    }

    false
}

#[inline]
unsafe fn record_global_auto_allocation_metadata_eligible_sharded(
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
) -> bool {
    let (home_shard_idx, home_start) = auto_allocation_record_shard_and_slot(ptr);
    let active_mask = auto_allocation_record_active_shards();
    let use_active_mask = active_mask != 0;
    let mut first_available: Option<(usize, usize)> = None;
    let active_offsets =
        auto_allocation_record_active_offsets_from_home(active_mask, home_shard_idx);
    let first_inactive: Option<(usize, usize)> = if use_active_mask {
        let inactive_offsets =
            (!active_offsets) & auto_allocation_record_all_shards_mask() & !1usize;
        if inactive_offsets != 0 {
            let shard_offset = inactive_offsets.trailing_zeros() as usize;
            let shard_idx = next_auto_allocation_record_shard(home_shard_idx, shard_offset);
            Some((shard_idx, 0))
        } else {
            None
        }
    } else {
        None
    };

    // Search every shard before inserting into a reusable slot.  That preserves
    // the old "replace, don't shadow" rule for in-place realloc/replay while
    // avoiding one process-wide mutex for unrelated cross-thread records.
    if use_active_mask {
        let mut search_offsets =
            auto_allocation_record_probe_offsets_including_home(active_mask, home_shard_idx);
        while let Some((shard_idx, shard_offset)) =
            pop_next_auto_allocation_record_active_shard(home_shard_idx, &mut search_offsets)
        {
            let start = if shard_offset == 0 { home_start } else { 0 };
            let mut table = AUTO_ALLOCATION_RECORDS[shard_idx].lock();
            if update_global_auto_allocation_record_in_shard(
                shard_idx,
                &mut *table,
                start,
                ptr,
                layout,
                metadata,
                shard_idx == home_shard_idx,
                &mut first_available,
            ) {
                return true;
            }
        }
    } else {
        let mut shard_offset = 0;
        while shard_offset < AUTO_ALLOCATION_RECORD_SHARD_COUNT {
            let shard_idx = next_auto_allocation_record_shard(home_shard_idx, shard_offset);
            let start = if shard_offset == 0 { home_start } else { 0 };
            let mut table = AUTO_ALLOCATION_RECORDS[shard_idx].lock();
            if update_global_auto_allocation_record_in_shard(
                shard_idx,
                &mut *table,
                start,
                ptr,
                layout,
                metadata,
                shard_idx == home_shard_idx,
                &mut first_available,
            ) {
                return true;
            }
            shard_offset += 1;
        }
    }

    if let Some((shard_idx, bucket_idx)) = first_available {
        let mut table = AUTO_ALLOCATION_RECORDS[shard_idx].lock();
        if install_global_auto_allocation_inline_record(
            shard_idx,
            &mut *table,
            bucket_idx,
            ptr,
            layout,
            metadata,
        ) {
            return true;
        }
    }

    if let Some((shard_idx, start)) = first_inactive {
        let ptr_key = ptr as usize;
        let mut table = AUTO_ALLOCATION_RECORDS[shard_idx].lock();
        let mut offset = 0;
        while offset < AUTO_ALLOCATION_RECORD_SHARD_SLOTS {
            let idx = (start + offset) & (AUTO_ALLOCATION_RECORD_SHARD_SLOTS - 1);
            let record = table.inline[idx];
            if record.ptr == ptr_key {
                auto_allocation_record_mark_shard_active(shard_idx);
                table.inline[idx] = auto_allocation_record_for(ptr, layout, metadata);
                remember_global_auto_allocation_record_hot_slot(&mut *table, ptr_key, idx);
                semantic_slow_path_set(SLOW_PATH_ALLOCATION_RECORDS);
                return true;
            }
            if record.is_available()
                && install_global_auto_allocation_inline_record(
                    shard_idx,
                    &mut *table,
                    idx,
                    ptr,
                    layout,
                    metadata,
                )
            {
                return true;
            }
            offset += 1;
        }
    }

    #[cfg(not(feature = "fixed_heap"))]
    {
        // All shard-local inline probe windows were occupied. Spill into the
        // home shard's dynamically sized overflow table.
        let mut table = AUTO_ALLOCATION_RECORDS[home_shard_idx].lock();
        match insert_filtered_auto_allocation_record_overflow(
            home_shard_idx,
            &mut table.overflow,
            auto_allocation_record_for(ptr, layout, metadata),
        ) {
            AutoAllocationRecordOverflowInsert::Updated => return true,
            AutoAllocationRecordOverflowInsert::Inserted => {
                increment_global_auto_allocation_record_shard_live_count(
                    home_shard_idx,
                    &mut *table,
                );
                AUTO_ALLOCATION_RECORD_COUNT.fetch_add(1, Ordering::Relaxed);
                semantic_slow_path_set(SLOW_PATH_ALLOCATION_RECORDS);
                return true;
            }
            AutoAllocationRecordOverflowInsert::Full => {}
        }
    }
    false
}

/// Install or update a hosted recovery record in its pointer-derived home
/// shard. The hosted overflow table is shard-local and dynamically sized, so
/// spreading a record into foreign inline capacity only makes every normal
/// insert and miss scan unrelated locks.
#[cfg(not(feature = "fixed_heap"))]
#[inline]
unsafe fn record_home_auto_allocation_metadata_eligible(
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
) -> bool {
    let (home_shard_idx, home_start) = auto_allocation_record_shard_and_slot(ptr);
    let mut first_available = None;
    let mut table = AUTO_ALLOCATION_RECORDS[home_shard_idx].lock();

    if update_global_auto_allocation_record_in_shard(
        home_shard_idx,
        &mut *table,
        home_start,
        ptr,
        layout,
        metadata,
        true,
        &mut first_available,
    ) {
        return true;
    }

    if let Some((shard_idx, bucket_idx)) = first_available {
        debug_assert_eq!(shard_idx, home_shard_idx);
        if install_global_auto_allocation_inline_record(
            home_shard_idx,
            &mut *table,
            bucket_idx,
            ptr,
            layout,
            metadata,
        ) {
            return true;
        }
    }

    match insert_filtered_auto_allocation_record_overflow(
        home_shard_idx,
        &mut table.overflow,
        auto_allocation_record_for(ptr, layout, metadata),
    ) {
        AutoAllocationRecordOverflowInsert::Updated => true,
        AutoAllocationRecordOverflowInsert::Inserted => {
            increment_global_auto_allocation_record_shard_live_count(home_shard_idx, &mut *table);
            AUTO_ALLOCATION_RECORD_COUNT.fetch_add(1, Ordering::Relaxed);
            semantic_slow_path_set(SLOW_PATH_ALLOCATION_RECORDS);
            true
        }
        AutoAllocationRecordOverflowInsert::Full => false,
    }
}

#[inline]
unsafe fn record_global_auto_allocation_metadata_eligible(
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
) -> bool {
    #[cfg(not(feature = "fixed_heap"))]
    if !AUTO_ALLOCATION_RECORD_LEGACY_NON_HOME_POSSIBLE.load(Ordering::Acquire) {
        return record_home_auto_allocation_metadata_eligible(ptr, layout, metadata);
    }

    // Fixed-heap builds need the complete inline capacity because they have no
    // mmap overflow. Hosted builds retain this path for observed legacy/test
    // records that may live outside the pointer-derived home shard.
    record_global_auto_allocation_metadata_eligible_sharded(ptr, layout, metadata)
}

#[inline]
unsafe fn record_global_auto_allocation_metadata(
    ptr: *mut u8,
    layout: Layout,
    metadata: AllocationMetadata,
) -> bool {
    if !auto_allocation_record_eligible(ptr, layout, metadata) {
        return true;
    }

    record_global_auto_allocation_metadata_eligible(ptr, layout, metadata)
}

fn lookup_auto_allocation_record(
    ptr: *mut u8,
    layout: Layout,
    remove: bool,
) -> AutoAllocationRecordLookup {
    let fast_lookup = lookup_fast_auto_allocation_record(ptr, layout, remove);
    if let AutoAllocationRecordLookup::Exact(_, _) = fast_lookup {
        return fast_lookup;
    }

    let global_lookup = lookup_global_auto_allocation_record(ptr, layout, remove);
    match global_lookup {
        AutoAllocationRecordLookup::Exact(_, _) => global_lookup,
        AutoAllocationRecordLookup::Mismatched(mismatch) => {
            AutoAllocationRecordLookup::Mismatched(mismatch)
        }
        AutoAllocationRecordLookup::Missing => fast_lookup,
    }
}

fn recover_auto_allocation_record_metadata(
    ptr: *mut u8,
    layout: Layout,
    remove: bool,
) -> Option<AllocationMetadata> {
    lookup_auto_allocation_record(ptr, layout, remove).exact_metadata()
}

fn take_auto_allocation_records_for_reallocation(
    ptr: *mut u8,
    layout: Layout,
) -> Option<AllocationMetadata> {
    // In-place realloc changes the allocator-visible layout while preserving
    // the pointer.  The old recovery record must be replaced, not shadowed:
    // visibility can change between the TLS fast table and the process-global
    // table when stats/compiler-stream/cross-thread gates change.  Probe both
    // tables explicitly so a stale record in one table cannot outlive the new
    // record in the other table.
    let fast_metadata = recover_fast_auto_allocation_record_metadata(ptr, layout, true);
    let global_metadata = recover_global_auto_allocation_record_metadata(ptr, layout, true);
    fast_metadata.or(global_metadata)
}

pub(crate) fn take_recorded_reallocation_old_metadata(
    ptr: *mut u8,
    layout: Layout,
) -> Option<AllocationMetadata> {
    take_auto_allocation_records_for_reallocation(ptr, layout)
}

unsafe fn replace_auto_allocation_record_for_reallocation(
    ptr: *mut u8,
    old_layout: Layout,
    new_layout: Layout,
    new_metadata: AllocationMetadata,
) -> bool {
    let old_metadata = take_auto_allocation_records_for_reallocation(ptr, old_layout);
    if record_recovery_auto_allocation_metadata(ptr, new_layout, new_metadata) {
        return true;
    }

    if let Some(old_metadata) = old_metadata {
        if !record_recovery_auto_allocation_metadata(ptr, old_layout, old_metadata) {
            // The caller still owns durable T lifecycle admission here. Keep
            // that fail-stop ownership through unwind rather than returning a
            // live allocation whose required recovery identity was lost.
            panic!("failed to restore old recovery identity after realloc record replacement");
        }
    }
    false
}

fn remove_global_auto_allocation_inline_record(
    shard_idx: usize,
    table: &mut GlobalAutoAllocationRecordTable,
    idx: usize,
    ptr_key: usize,
) {
    clear_global_auto_allocation_record_hot_slot(table, ptr_key);
    if atomic_saturating_decrement(&AUTO_ALLOCATION_RECORD_COUNT) == 0 {
        #[cfg(test)]
        pause_after_last_global_recovery_count_decrement_for_test();
        // This global recovery table is on the compiler-scoped GlobalAlloc
        // deallocation path.  The TLS fast table already avoids clearing all
        // slots when the last live record is removed; keep the same O(1)
        // behavior here. Tombstones are only needed while another live record
        // may depend on the probe chain, so the final removed slot can become
        // an empty stop marker and the slow-path flag can be cleared
        // immediately.
        table.inline[idx] = AutoAllocationRecord::empty();
        // Only clear this shard's hint.  A concurrent insertion can publish a
        // live record in another shard after the count reaches zero; a global
        // store here would erase that new shard bit and hide its record.
        decrement_global_auto_allocation_record_shard_live_count(shard_idx, table);
        semantic_slow_path_clear(SLOW_PATH_ALLOCATION_RECORDS);
    } else {
        table.inline[idx] = AutoAllocationRecord::tombstone();
        decrement_global_auto_allocation_record_shard_live_count(shard_idx, table);
    }
    // Retire the filter only after the authoritative record is gone.
    decrement_global_recovery_pointer_filter(ptr_key as *mut u8);
}

fn lookup_global_auto_allocation_record_in_shard(
    ptr: *mut u8,
    layout: Layout,
    remove: bool,
    shard_idx: usize,
    start: usize,
    search_home_overflow: bool,
) -> AutoAllocationRecordLookup {
    let ptr_key = ptr as usize;
    let mut table = AUTO_ALLOCATION_RECORDS[shard_idx].lock();

    if let Some(idx) = global_auto_allocation_record_hot_slot(&*table, ptr_key) {
        let record = table.inline[idx];
        if record.ptr == ptr_key {
            if record.matches_allocation(ptr, layout) {
                if remove {
                    remove_global_auto_allocation_inline_record(
                        shard_idx,
                        &mut *table,
                        idx,
                        ptr_key,
                    );
                }
                return AutoAllocationRecordLookup::exact(record);
            }
            return AutoAllocationRecordLookup::Mismatched(
                AutoAllocationRecordMismatch::from_record(record),
            );
        }
        clear_global_auto_allocation_record_hot_slot(&mut *table, ptr_key);
    }

    let mut offset = 0;
    while offset < AUTO_ALLOCATION_RECORD_PROBE_LIMIT {
        let idx = (start + offset) & (AUTO_ALLOCATION_RECORD_SHARD_SLOTS - 1);
        let record = table.inline[idx];
        if record.is_empty() {
            break;
        }
        if record.ptr == ptr_key {
            if record.matches_allocation(ptr, layout) {
                if remove {
                    remove_global_auto_allocation_inline_record(
                        shard_idx,
                        &mut *table,
                        idx,
                        ptr_key,
                    );
                } else {
                    remember_global_auto_allocation_record_hot_slot(&mut *table, ptr_key, idx);
                }
                return AutoAllocationRecordLookup::exact(record);
            }
            return AutoAllocationRecordLookup::Mismatched(
                AutoAllocationRecordMismatch::from_record(record),
            );
        }
        offset += 1;
    }

    #[cfg(not(feature = "fixed_heap"))]
    {
        // Hosted overflow records are authoritative only in the pointer's home
        // shard. The caller passes this explicitly so legacy foreign-shard
        // fallback never accepts a corrupt non-home overflow entry.
        if search_home_overflow {
            if let AutoAllocationRecordOverflowProbe::Found(idx) =
                probe_auto_allocation_record_overflow(&table.overflow, ptr_key)
            {
                let record = unsafe { *table.overflow.slots.add(idx) };
                if record.matches_allocation(ptr, layout) {
                    if remove {
                        if !unsafe {
                            try_remove_auto_allocation_record_overflow_at(
                                shard_idx,
                                &mut table.overflow,
                                idx,
                            )
                        } {
                            return AutoAllocationRecordLookup::Mismatched(
                                AutoAllocationRecordMismatch::from_record(record),
                            );
                        }
                        // The overflow slot is no longer authoritative before
                        // its negative-filter publication is retired.
                        decrement_global_recovery_pointer_filter(ptr);
                        let removed_last_global =
                            atomic_saturating_decrement(&AUTO_ALLOCATION_RECORD_COUNT) == 0;
                        if removed_last_global {
                            #[cfg(test)]
                            pause_after_last_global_recovery_count_decrement_for_test();
                        }
                        decrement_global_auto_allocation_record_shard_live_count(
                            shard_idx,
                            &mut *table,
                        );
                        if removed_last_global {
                            semantic_slow_path_clear(SLOW_PATH_ALLOCATION_RECORDS);
                        }
                    }
                    return AutoAllocationRecordLookup::exact(record);
                }
                return AutoAllocationRecordLookup::Mismatched(
                    AutoAllocationRecordMismatch::from_record(record),
                );
            }
        }
    }

    #[cfg(feature = "fixed_heap")]
    {
        let _ = search_home_overflow;
        let mut slow_offset = AUTO_ALLOCATION_RECORD_PROBE_LIMIT;
        while slow_offset < AUTO_ALLOCATION_RECORD_SHARD_SLOTS {
            let idx = (start + slow_offset) & (AUTO_ALLOCATION_RECORD_SHARD_SLOTS - 1);
            let record = table.inline[idx];
            if record.is_empty() {
                break;
            }
            if record.ptr == ptr_key {
                if record.matches_allocation(ptr, layout) {
                    if remove {
                        remove_global_auto_allocation_inline_record(
                            shard_idx,
                            &mut *table,
                            idx,
                            ptr_key,
                        );
                    } else {
                        remember_global_auto_allocation_record_hot_slot(&mut *table, ptr_key, idx);
                    }
                    return AutoAllocationRecordLookup::exact(record);
                }
                return AutoAllocationRecordLookup::Mismatched(
                    AutoAllocationRecordMismatch::from_record(record),
                );
            }
            slow_offset += 1;
        }
    }

    AutoAllocationRecordLookup::Missing
}

fn lookup_global_auto_allocation_record(
    ptr: *mut u8,
    layout: Layout,
    remove: bool,
) -> AutoAllocationRecordLookup {
    let ptr_key = ptr as usize;
    if ptr.is_null()
        || ptr_key == AUTO_ALLOCATION_RECORD_TOMBSTONE_PTR
        || layout.size() == 0
        || AUTO_ALLOCATION_RECORD_COUNT.load(Ordering::Relaxed) == 0
    {
        return AutoAllocationRecordLookup::Missing;
    }

    let (home_shard_idx, home_start) = auto_allocation_record_shard_and_slot(ptr);

    #[cfg(not(feature = "fixed_heap"))]
    {
        let home = lookup_global_auto_allocation_record_in_shard(
            ptr,
            layout,
            remove,
            home_shard_idx,
            home_start,
            true,
        );
        if !matches!(home, AutoAllocationRecordLookup::Missing) {
            return home;
        }
        if !AUTO_ALLOCATION_RECORD_LEGACY_NON_HOME_POSSIBLE.load(Ordering::Acquire) {
            return AutoAllocationRecordLookup::Missing;
        }
    }

    let active_mask = auto_allocation_record_active_shards();
    // Fixed-heap records may consume the complete cross-shard inline budget.
    // Hosted records take this exhaustive path only after a supported non-home
    // install publishes the sticky compatibility gate.
    let mut active_offsets =
        auto_allocation_record_probe_offsets_including_home(active_mask, home_shard_idx);
    while let Some((shard_idx, shard_offset)) =
        pop_next_auto_allocation_record_active_shard(home_shard_idx, &mut active_offsets)
    {
        #[cfg(not(feature = "fixed_heap"))]
        if shard_offset == 0 {
            continue;
        }
        let start = if shard_offset == 0 { home_start } else { 0 };
        let result = lookup_global_auto_allocation_record_in_shard(
            ptr,
            layout,
            remove,
            shard_idx,
            start,
            shard_offset == 0,
        );
        if !matches!(result, AutoAllocationRecordLookup::Missing) {
            return result;
        }
    }
    AutoAllocationRecordLookup::Missing
}

fn recover_global_auto_allocation_record_metadata(
    ptr: *mut u8,
    layout: Layout,
    remove: bool,
) -> Option<AllocationMetadata> {
    lookup_global_auto_allocation_record(ptr, layout, remove).exact_metadata()
}

fn lookup_auto_allocation_metadata(ptr: *mut u8, layout: Layout) -> Option<AllocationMetadata> {
    recover_auto_allocation_record_metadata(ptr, layout, false)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum AutoAllocationRecordStorage {
    Fast,
    Global,
}

/// Locate one unambiguous, exact recovery record for an owned allocation.
/// Integrity-policy records additionally require keyed authentication.
///
/// A pointer must not be rebound while duplicate fast/global records exist. Even
/// if both copies currently agree, changing only one copy could let a later
/// lookup recover the stale identity. The ordinary allocator should keep one
/// authoritative record; treating any other state as non-rebindable is the
/// fail-closed behavior for this ownership transition.
fn exact_auto_allocation_record_for_identity_rebind(
    ptr: *mut u8,
    layout: Layout,
) -> Option<(AutoAllocationRecordStorage, AllocationMetadata)> {
    let fast = lookup_fast_auto_allocation_record(ptr, layout, false);
    let global = lookup_global_auto_allocation_record(ptr, layout, false);
    match (fast, global) {
        (AutoAllocationRecordLookup::Exact(metadata, _), AutoAllocationRecordLookup::Missing) => {
            Some((AutoAllocationRecordStorage::Fast, metadata))
        }
        (AutoAllocationRecordLookup::Missing, AutoAllocationRecordLookup::Exact(metadata, _)) => {
            Some((AutoAllocationRecordStorage::Global, metadata))
        }
        _ => None,
    }
}

/// Return whether a software memory-tag record exists for `ptr` in either the
/// current-thread or process-visible table.
unsafe fn memory_tag_record_exists_for_identity_rebind(ptr: *mut u8) -> bool {
    let local = exact_local_memory_tag_record_for_identity_rebind(ptr);
    let mut table = global_memory_tag_table_for_ptr(ptr).lock();
    let global = exact_global_memory_tag_record_for_identity_rebind(&mut *table, ptr);
    !matches!(local, MemoryTagIdentityRecordLookup::Missing)
        || !matches!(global, MemoryTagIdentityRecordLookup::Missing)
}

enum MemoryTagIdentityRecordLookup {
    Missing,
    Unique(*mut TaggedAllocation),
    Duplicate,
}

#[inline]
fn include_memory_tag_identity_record(
    unique: &mut *mut TaggedAllocation,
    slot: *mut TaggedAllocation,
) -> bool {
    if unique.is_null() {
        *unique = slot;
        false
    } else {
        true
    }
}

/// Exhaustively classify the current thread's tag storage for one pointer.
///
/// Identity transfer is cold and security-sensitive, so it scans the complete
/// fixed tier and every currently allocated overflow page instead of trusting
/// the hot hint, probe window, or live-record counter. It stops as soon as a
/// second record proves ambiguity.
unsafe fn exact_local_memory_tag_record_for_identity_rebind(
    ptr: *mut u8,
) -> MemoryTagIdentityRecordLookup {
    let mut unique = core::ptr::null_mut();
    let mut idx = 0;
    while idx < MEMORY_TAG_FAST_SLOTS {
        let slot = &mut MEMORY_TAGS[idx] as *mut TaggedAllocation;
        if (*slot).ptr == ptr && include_memory_tag_identity_record(&mut unique, slot) {
            return MemoryTagIdentityRecordLookup::Duplicate;
        }
        idx += 1;
    }

    #[cfg(not(feature = "fixed_heap"))]
    {
        let mut page = MEMORY_TAG_OVERFLOW;
        while !page.is_null() {
            let mut entry_idx = 0;
            while entry_idx < MEMORY_TAG_PAGE_SLOTS {
                let slot = &mut (*page).entries[entry_idx] as *mut TaggedAllocation;
                if (*slot).ptr == ptr && include_memory_tag_identity_record(&mut unique, slot) {
                    return MemoryTagIdentityRecordLookup::Duplicate;
                }
                entry_idx += 1;
            }
            page = (*page).next;
        }
    }

    if unique.is_null() {
        MemoryTagIdentityRecordLookup::Missing
    } else {
        MemoryTagIdentityRecordLookup::Unique(unique)
    }
}

/// Classify the complete process-visible tag shard while its lock is held.
fn exact_global_memory_tag_record_for_identity_rebind(
    table: &mut GlobalMemoryTagTable,
    ptr: *mut u8,
) -> MemoryTagIdentityRecordLookup {
    let mut unique = core::ptr::null_mut();
    let mut idx = 0;
    while idx < GLOBAL_MEMORY_TAG_SHARD_SLOTS {
        let slot = &mut table.fast[idx] as *mut TaggedAllocation;
        if unsafe { (*slot).ptr == ptr } && include_memory_tag_identity_record(&mut unique, slot) {
            return MemoryTagIdentityRecordLookup::Duplicate;
        }
        idx += 1;
    }

    #[cfg(not(feature = "fixed_heap"))]
    {
        let mut page = table.overflow;
        while !page.is_null() {
            let mut entry_idx = 0;
            while entry_idx < MEMORY_TAG_PAGE_SLOTS {
                let slot = unsafe { &mut (*page).entries[entry_idx] as *mut TaggedAllocation };
                if unsafe { (*slot).ptr == ptr }
                    && include_memory_tag_identity_record(&mut unique, slot)
                {
                    return MemoryTagIdentityRecordLookup::Duplicate;
                }
                entry_idx += 1;
            }
            page = unsafe { (*page).next };
        }
    }

    if unique.is_null() {
        MemoryTagIdentityRecordLookup::Missing
    } else {
        MemoryTagIdentityRecordLookup::Unique(unique)
    }
}

/// Replace one exact software memory-tag identity without removing its slot.
///
/// The ownership-transfer helper guarantees exclusive ownership of `ptr`, so a
/// concurrent deallocation is already outside its contract.  Keeping the slot
/// in place avoids a missing-record window.  The replacement is accepted only
/// when exactly one correctly placed, authenticated tag record agrees with the
/// recovery record that authorized the transition.
unsafe fn try_rebind_memory_tag_identity(
    ptr: *mut u8,
    layout: Layout,
    expected: AllocationMetadata,
    replacement: AllocationMetadata,
) -> bool {
    let local = exact_local_memory_tag_record_for_identity_rebind(ptr);
    let mut table = global_memory_tag_table_for_ptr(ptr).lock();
    let global = exact_global_memory_tag_record_for_identity_rebind(&mut *table, ptr);
    let slot = if memory_tag_requires_global_visibility(expected) {
        match (local, global) {
            (
                MemoryTagIdentityRecordLookup::Missing,
                MemoryTagIdentityRecordLookup::Unique(slot),
            ) => slot,
            _ => return false,
        }
    } else {
        match (local, global) {
            (
                MemoryTagIdentityRecordLookup::Unique(slot),
                MemoryTagIdentityRecordLookup::Missing,
            ) => slot,
            _ => return false,
        }
    };

    if memory_tag_requires_global_visibility(expected) {
        let record = *slot;
        if record.metadata != expected
            || memory_tag_record_layout(record).ok() != Some(layout)
            || try_verify_memory_tag_record(record).is_err()
        {
            return false;
        }
        *slot = TaggedAllocation {
            tag: derive_memory_tag(ptr, layout, replacement),
            metadata: replacement,
            ..record
        };
        return true;
    }
    let record = *slot;
    if record.metadata != expected
        || memory_tag_record_layout(record).ok() != Some(layout)
        || try_verify_memory_tag_record(record).is_err()
    {
        return false;
    }
    *slot = TaggedAllocation {
        tag: derive_memory_tag(ptr, layout, replacement),
        metadata: replacement,
        ..record
    };
    true
}

/// Change the type component of one live allocation's recovery identity.
///
/// The caller must uniquely own `ptr` for the duration of this operation. The
/// exact pointer/layout record remains the authority: missing, mismatched,
/// duplicated, or already-transitioned records are not changed. Tagged records
/// additionally require one exact authenticated memory-tag record. The tag is
/// updated in place first, then rolled back if the recovery-record update cannot
/// commit, so callers never continue after a half-applied transition.
unsafe fn try_rebind_auto_allocation_type_identity(
    ptr: *mut u8,
    layout: Layout,
    expected_old_type_id: u64,
    new_type_id: u64,
) -> bool {
    if ptr.is_null()
        || layout.size() == 0
        || expected_old_type_id == UNKNOWN_SEMANTIC_ID
        || new_type_id == UNKNOWN_SEMANTIC_ID
        || expected_old_type_id == new_type_id
    {
        return false;
    }

    let (storage, recorded) = match exact_auto_allocation_record_for_identity_rebind(ptr, layout) {
        Some(record) => record,
        None => return false,
    };
    if recorded.type_id != expected_old_type_id {
        return false;
    }

    let rebound = AllocationMetadata {
        type_id: new_type_id,
        ..recorded
    };
    let tagged = recorded.requests(FLAG_MEMORY_TAGGING);
    if tagged {
        if !try_rebind_memory_tag_identity(ptr, layout, recorded, rebound) {
            return false;
        }
    } else if memory_tag_record_exists_for_identity_rebind(ptr) {
        return false;
    }

    #[cfg(test)]
    let force_recovery_update_failure =
        TEST_IDENTITY_REBIND_RECOVERY_UPDATE_FAIL.swap(false, Ordering::AcqRel);
    #[cfg(not(test))]
    let force_recovery_update_failure = false;
    let recovery_rebound = !force_recovery_update_failure
        && match storage {
            AutoAllocationRecordStorage::Fast => {
                record_fast_auto_allocation_metadata_eligible(ptr, layout, rebound)
            }
            AutoAllocationRecordStorage::Global => {
                record_global_auto_allocation_metadata_eligible(ptr, layout, rebound)
            }
        };
    if recovery_rebound {
        return true;
    }

    if tagged && !try_rebind_memory_tag_identity(ptr, layout, rebound, recorded) {
        panic!("memory-tag identity rebind rollback failed");
    }
    false
}

/// Convert a boxed slice into a vector while transferring the allocator's live
/// type-isolation identity from the exact boxed-slice type to the exact vector
/// type selected by the compiler.
///
/// This is a compiler-lowering helper, not a general source-level conversion
/// API. The standard-library conversion preserves the allocation pointer,
/// length, capacity, and allocator. UniAlloc changes only `type_id` in an exact
/// recovery record and, when enabled, its matching authenticated memory-tag
/// record; module, policy flags, lifetime/placement hints, and the allocation
/// callsite remain bound to the allocation event. If either record is
/// unavailable or cannot be safely rebound, the conversion still succeeds but
/// the old recovery identity remains authoritative.
#[doc(hidden)]
pub fn __unialloc_semantic_box_slice_into_vec<T, A: Allocator>(
    boxed: AllocBox<[T], A>,
    expected_old_type_id: u64,
    new_type_id: u64,
) -> AllocVec<T, A> {
    let old_ptr = boxed.as_ptr() as *mut u8;
    let old_len = boxed.len();
    let layout = Layout::array::<T>(old_len).ok();
    let vec = boxed.into_vec();

    let applied = if let Some(layout) = layout {
        // Keep the identity mutation narrower than the standard-library
        // contract: if a future implementation stops preserving these exact
        // representation properties, retain the old authoritative record.
        if layout.size() != 0 && vec.as_ptr() as *mut u8 == old_ptr && vec.capacity() == old_len {
            unsafe {
                try_rebind_auto_allocation_type_identity(
                    old_ptr,
                    layout,
                    expected_old_type_id,
                    new_type_id,
                )
            }
        } else {
            false
        }
    } else {
        false
    };
    if semantic_stats_recording_enabled() {
        if applied {
            SEMANTIC_OWNERSHIP_TRANSFER_APPLIED.fetch_add(1, Ordering::Relaxed);
        } else {
            SEMANTIC_OWNERSHIP_TRANSFER_REJECTED.fetch_add(1, Ordering::Relaxed);
        }
    }

    vec
}

