    #[cfg(not(feature = "reclaim_checks"))]
    struct PointerFilterFirstZeroHookGuard;

    #[cfg(not(feature = "reclaim_checks"))]
    impl PointerFilterFirstZeroHookGuard {
        fn arm(ptr: *mut u8) -> Self {
            assert!(!ptr.is_null());
            assert_eq!(
                TEST_POINTER_FILTER_FIRST_ZERO_PTR.swap(ptr as usize, Ordering::AcqRel),
                0,
                "pointer-filter first-zero hook target must start idle"
            );
            assert!(
                TEST_POINTER_FILTER_FIRST_ZERO_PHASE
                    .compare_exchange(0, 1, Ordering::AcqRel, Ordering::Acquire)
                    .is_ok(),
                "pointer-filter first-zero hook phase must start idle"
            );
            Self
        }

        fn wait_for_first_zero(&self) {
            while TEST_POINTER_FILTER_FIRST_ZERO_PHASE.load(Ordering::Acquire) != 2 {
                core::hint::spin_loop();
            }
        }

        fn release_query(&self) {
            TEST_POINTER_FILTER_FIRST_ZERO_PHASE.store(3, Ordering::Release);
        }
    }

    #[cfg(not(feature = "reclaim_checks"))]
    impl Drop for PointerFilterFirstZeroHookGuard {
        fn drop(&mut self) {
            TEST_POINTER_FILTER_FIRST_ZERO_PHASE.store(0, Ordering::Release);
            TEST_POINTER_FILTER_FIRST_ZERO_PTR.store(0, Ordering::Release);
        }
    }

    struct DelayedToTypeReclaimPhaseGuard;

    impl DelayedToTypeReclaimPhaseGuard {
        fn arm() -> Self {
            assert!(
                TEST_DELAYED_TO_TYPE_RECLAIM_PHASE
                    .compare_exchange(0, 1, Ordering::AcqRel, Ordering::Acquire)
                    .is_ok(),
                "delayed-to-type reclaim test phase must start idle"
            );
            Self
        }

        fn release_worker(&self) {
            TEST_DELAYED_TO_TYPE_RECLAIM_PHASE.store(3, Ordering::Release);
        }

        fn reset(&self) {
            TEST_DELAYED_TO_TYPE_RECLAIM_PHASE.store(0, Ordering::Release);
        }
    }

    impl Drop for DelayedToTypeReclaimPhaseGuard {
        fn drop(&mut self) {
            loop {
                let phase = TEST_DELAYED_TO_TYPE_RECLAIM_PHASE.load(Ordering::Acquire);
                let next = match phase {
                    0 => return,
                    1 => 0,
                    2 => 3,
                    // The worker resets these states after consuming the
                    // synthetic missed-handoff sentinel.
                    3 | 4 => return,
                    _ => 0,
                };
                if TEST_DELAYED_TO_TYPE_RECLAIM_PHASE
                    .compare_exchange(phase, next, Ordering::AcqRel, Ordering::Acquire)
                    .is_ok()
                {
                    return;
                }
            }
        }
    }

    struct TerminalReleasePhaseGuard {
        phase: &'static AtomicUsize,
    }

    impl TerminalReleasePhaseGuard {
        fn arm(phase: &'static AtomicUsize) -> Self {
            assert!(
                phase
                    .compare_exchange(0, 1, Ordering::AcqRel, Ordering::Acquire)
                    .is_ok(),
                "terminal-release test phase must start idle"
            );
            Self { phase }
        }

        fn release_owner(&self) {
            self.phase.store(3, Ordering::Release);
        }

        fn reset(&self) {
            self.phase.store(0, Ordering::Release);
        }
    }

    impl Drop for TerminalReleasePhaseGuard {
        fn drop(&mut self) {
            loop {
                let phase = self.phase.load(Ordering::Acquire);
                let next = match phase {
                    0 => return,
                    1 => 0,
                    2 => 3,
                    3 => return,
                    _ => 0,
                };
                if self
                    .phase
                    .compare_exchange(phase, next, Ordering::AcqRel, Ordering::Acquire)
                    .is_ok()
                {
                    return;
                }
            }
        }
    }

