    unsafe fn cached_segregated_type_cache_entry_for_test(
        layout: Layout,
        metadata: AllocationMetadata,
        ptr: *mut u8,
    ) -> Option<*mut SegregatedTypeCacheEntry> {
        let cache_key = type_cache_identity_key(metadata);
        let identity = TypeCacheIdentity::from_metadata(metadata);
        let policy_key = segregated_type_cache_policy_key(metadata);
        let inline_cache_domain = segregated_type_cache_inline_domain(metadata);
        let mut inline_index = 0usize;
        while inline_index < inline_segregated_type_cache_capacity(inline_cache_domain) {
            let inline_entry =
                inline_segregated_type_cache_entry_at(inline_cache_domain, inline_index);
            if (*inline_entry).ptr == ptr
                && (*inline_entry).matches_cached_key(layout, identity, cache_key, policy_key)
            {
                return Some(inline_entry);
            }
            inline_index += 1;
        }

        let bucket = &mut SEGREGATED_TYPE_CACHE[segregated_type_cache_slot(metadata, layout)];
        let mut idx = 0usize;
        while idx < bucket.count {
            if bucket.entries[idx].ptr == ptr
                && bucket.entries[idx].matches_cached_key(layout, identity, cache_key, policy_key)
            {
                return Some(&mut bucket.entries[idx] as *mut SegregatedTypeCacheEntry);
            }
            idx += 1;
        }
        None
    }

    #[test]
    fn fast_auto_allocation_record_builder_keeps_unprotected_hot_path_unsigned() {
        let _guard = test_guard();
        let layout = Layout::from_size_align(64, align_of::<usize>()).unwrap();
        let ptr = 0x4000_1000usize as *mut u8;
        let metadata = AllocationMetadata::for_type(0xC003_0001)
            .with_module(0xC0DE)
            .with_callsite(0xA110_0001)
            .with_flags(FLAG_TYPE_ISOLATED);

        let record = fast_auto_allocation_record_for(ptr, layout, metadata);

        assert_eq!(record.ptr, ptr as usize);
        assert_eq!(record.size, layout.size());
        assert_eq!(record.align, layout.align());
        assert_eq!(record.metadata, metadata);
        assert_eq!(
            record.auth, 0,
            "same-thread compiler recovery records should not pay integrity hashing unless a protected metadata policy requests it"
        );
        assert!(fast_auto_allocation_record_auth_matches(
            ptr, layout, record
        ));
    }

    #[test]
    fn fast_auto_allocation_record_builder_preserves_protected_auth() {
        let _guard = test_guard();
        reset_metadata_auth_cookie_for_test();
        let layout = Layout::from_size_align(64, align_of::<usize>()).unwrap();
        let ptr = 0x4000_2000usize as *mut u8;
        let metadata = AllocationMetadata::for_type(0xC003_0002)
            .with_module(0xC0DE)
            .with_callsite(0xA110_0002)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_METADATA_PROTECTION);

        let record = fast_auto_allocation_record_for(ptr, layout, metadata);

        assert_ne!(
            record.auth, 0,
            "protected metadata must keep an authenticator even on the TLS fast record path"
        );
        assert_eq!(
            record.auth,
            derive_auto_allocation_record_auth(ptr, layout, metadata)
        );
        assert!(fast_auto_allocation_record_auth_matches(
            ptr, layout, record
        ));

        let tampered = AutoAllocationRecord {
            metadata: metadata.with_callsite(0xD0D0_0002),
            ..record
        };
        assert!(
            !fast_auto_allocation_record_auth_matches(ptr, layout, tampered),
            "metadata-protected recovery records must reject stale/tampered metadata"
        );
    }

    #[test]
    fn fast_auto_allocation_record_tls_cache_has_bounded_footprint() {
        let _guard = test_guard();
        let bytes = size_of::<[AutoAllocationRecord; FAST_AUTO_ALLOCATION_RECORD_SLOTS]>();
        let max_bytes = if cfg!(feature = "fixed_heap") {
            16 * 1024
        } else {
            8 * 1024
        };
        assert!(
            FAST_AUTO_ALLOCATION_RECORD_SLOTS.is_power_of_two(),
            "open-addressed TLS recovery cache requires a power-of-two slot count"
        );
        assert!(
            bytes <= max_bytes,
            "same-thread recovery cache should stay a small TLS hot cache, not a large per-thread side table"
        );
        assert!(
            FAST_AUTO_ALLOCATION_RECORD_SLOTS < AUTO_ALLOCATION_RECORD_SLOTS,
            "global sharded recovery table remains the spill path for many live records"
        );
    }

    #[test]
    fn metadata_segregated_bucket_table_has_bounded_tls_footprint() {
        let bytes = size_of::<[SegregatedTypeCacheBucket; TYPE_CACHE_SLOTS]>();
        let (max_depth, max_bytes) = if cfg!(feature = "fixed_heap") {
            (8, 48 * 1024)
        } else {
            (4, 24 * 1024)
        };
        assert!(SEGREGATED_TYPE_CACHE_DEPTH.is_power_of_two());
        assert!(
            SEGREGATED_TYPE_CACHE_DEPTH <= max_depth,
            "segregated cache depth must stay within the target-specific footprint budget"
        );
        assert!(
            bytes <= max_bytes,
            "metadata-segregated bucket table must stay within the target-specific footprint budget"
        );
    }

    #[test]
    fn fast_auto_allocation_record_tls_cache_spills_to_global_when_full() {
        let _guard = test_guard();
        clear_auto_allocation_records();
        let layout = Layout::from_size_align(64, align_of::<usize>()).unwrap();
        let metadata = AllocationMetadata::for_type(0xC003_5A11)
            .with_module(0xC0DE_5A11)
            .with_flags(FLAG_TYPE_ISOLATED);

        unsafe {
            // The inline slot plus the bounded TLS array should handle the
            // first small same-thread set without taking the global shard
            // locks.  Extra live records must still be accepted by spilling to
            // the existing process-visible sharded table rather than silently
            // dropping compiler metadata.
            let total = FAST_AUTO_ALLOCATION_RECORD_SLOTS + 17;
            let mut idx = 0usize;
            while idx < total {
                let ptr = (0x7200_0000usize + (idx + 1) * 0x1000) as *mut u8;
                assert!(record_recovery_auto_allocation_metadata_eligible(
                    ptr,
                    layout,
                    metadata.with_callsite(idx as u64)
                ));
                idx += 1;
            }
            assert!(
                FAST_AUTO_ALLOCATION_RECORD_COUNT <= FAST_AUTO_ALLOCATION_RECORD_SLOTS,
                "TLS recovery cache must remain bounded even when more records are accepted"
            );
            assert!(
                AUTO_ALLOCATION_RECORD_COUNT.load(Ordering::Relaxed) > 0,
                "records beyond the bounded TLS cache should spill to the global recovery table"
            );
            clear_auto_allocation_records();
        }
    }

    #[test]
    fn recovery_identity_matches_allocator_identity_but_not_callsite() {
        let recorded = AllocationMetadata::for_type(0xC003_1D01)
            .with_module(0xC0DE)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_METADATA_SEGREGATED)
            .with_lifetime_hint(7)
            .with_placement_hint(11)
            .with_callsite(0xA110_C001);
        let drop_site = recorded.with_callsite(0xD00D_C001);
        let wrong_module = drop_site.with_module(0xBAD0);
        let layout_derived = AllocationMetadata {
            placement_hint: LAYOUT_DERIVED_PLACEMENT_HINT,
            ..drop_site
        };

        assert!(allocation_metadata_recovery_identity_matches(
            drop_site, recorded
        ));
        assert!(
            !allocation_metadata_recovery_identity_matches(wrong_module, recorded),
            "module/context is an allocation identity boundary"
        );
        assert!(
            !allocation_metadata_recovery_identity_matches(layout_derived, recorded),
            "layout-derived metadata must not be promoted to exact compiler recovery identity"
        );
    }

    #[test]
    fn recovery_delegation_requires_exact_neutral_metadata() {
        let recorded = AllocationMetadata::for_type(0xC003_1D11)
            .with_module(0xC0DE_1D11)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_METADATA_SEGREGATED)
            .with_lifetime_hint(7)
            .with_placement_hint(11)
            .with_callsite(0xA110_1D11);
        let delegated = AllocationMetadata::unknown().with_callsite(0xD00D_1D11);

        assert!(is_recovery_delegated_metadata_request(delegated));
        assert_eq!(
            recovery_delegated_metadata_after_record(delegated, recorded),
            Some(recorded.with_callsite(delegated.callsite)),
            "delegation must retain recorded identity/policy/hints and only replace callsite"
        );
        assert!(
            !is_recovery_delegated_metadata_request(AllocationMetadata::unknown()),
            "ordinary all-zero unknown metadata is not a compiler delegation request"
        );

        for policy_bearing in [
            delegated.with_module(0xBAD0),
            delegated.with_flags(FLAG_FORCE_INITIALIZE),
            delegated.with_lifetime_hint(1),
            delegated.with_placement_hint(1),
        ] {
            assert!(!is_recovery_delegated_metadata_request(policy_bearing));
            assert_eq!(
                recovery_delegated_metadata_after_record(policy_bearing, recorded),
                None,
                "untyped but policy-bearing metadata must keep its original semantics"
            );
        }
        assert_eq!(
            recovery_delegated_metadata_after_record(delegated, AllocationMetadata::unknown()),
            None,
            "a neutral request cannot inherit a missing/unknown recorded type"
        );
    }

    #[test]
    fn recovery_delegated_layout_realloc_and_dealloc_preserve_recorded_identity() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();

        let old_layout = Layout::from_size_align(63, 64).unwrap();
        let new_layout = Layout::from_size_align(57, old_layout.align()).unwrap();
        assert_eq!(
            crate::size_class::get_size_class(old_layout.size()).index(),
            crate::size_class::get_size_class(new_layout.size()).index(),
            "regression requires an in-place-capable shrink"
        );
        let recorded = AllocationMetadata::for_type(0xC003_1D21)
            .with_module(0xC0DE_1D21)
            .with_flags(FLAG_TYPE_ISOLATED)
            .with_lifetime_hint(3)
            .with_placement_hint(5)
            .with_callsite(0xA110_1D21);
        let realloc_request = AllocationMetadata::unknown().with_callsite(0xA110_1D22);
        let dealloc_request = AllocationMetadata::unknown().with_callsite(0xD00D_1D23);
        let validation_before = semantic_metadata_validation_snapshot();

        let ptr = unsafe {
            __unialloc_alloc_layout_with_metadata_hints(
                old_layout,
                recorded.type_id,
                recorded.module_id,
                recorded.flags,
                recorded.lifetime_hint,
                recorded.placement_hint,
                recorded.callsite,
            )
        };
        assert!(!ptr.is_null());
        unsafe {
            ptr.write_volatile(0xC2);
        }
        assert_eq!(
            lookup_auto_allocation_metadata(ptr, old_layout),
            Some(recorded)
        );

        let shrunk = unsafe {
            __unialloc_realloc_layout_with_metadata_hints(
                ptr,
                old_layout,
                new_layout.size(),
                realloc_request.type_id,
                realloc_request.module_id,
                realloc_request.flags,
                realloc_request.lifetime_hint,
                realloc_request.placement_hint,
                realloc_request.callsite,
            )
        };
        assert_eq!(shrunk, ptr);
        assert_eq!((shrunk as usize) & (new_layout.align() - 1), 0);
        assert_eq!(unsafe { shrunk.read_volatile() }, 0xC2);
        assert_eq!(lookup_auto_allocation_metadata(ptr, old_layout), None);
        assert_eq!(
            lookup_auto_allocation_metadata(shrunk, new_layout),
            Some(recorded.with_callsite(realloc_request.callsite))
        );

        unsafe {
            __unialloc_dealloc_layout_with_metadata_hints(
                shrunk,
                new_layout,
                dealloc_request.type_id,
                dealloc_request.module_id,
                dealloc_request.flags,
                dealloc_request.lifetime_hint,
                dealloc_request.placement_hint,
                dealloc_request.callsite,
            );
        }
        assert_eq!(lookup_auto_allocation_metadata(shrunk, new_layout), None);
        let validation_after = semantic_metadata_validation_snapshot();
        assert_eq!(
            validation_after.recovery_identity_matches, validation_before.recovery_identity_matches,
            "recovery delegation is not an exact compiler identity match"
        );
        assert_eq!(
            validation_after.recovery_identity_mismatches,
            validation_before.recovery_identity_mismatches
        );

        let allocator = RustAllocator::new();
        let reused = unsafe { allocator.alloc_with_metadata(new_layout, recorded) };
        assert_eq!(
            reused, shrunk,
            "delegated dealloc must preserve typed cache routing"
        );
        unsafe {
            allocator.dealloc_raw(reused, new_layout);
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
    }

