    #[test]
    fn global_semantic_pointer_filter_refcounts_recovery_colliders() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();

        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let metadata = AllocationMetadata::for_type(0xC003_F117)
            .with_module(0xC0DE_F117)
            .with_callsite(0xA110_F117)
            .with_flags(FLAG_TYPE_ISOLATED)
            .with_placement_hint(PLACEMENT_HINT_CROSS_THREAD_RECOVERY);
        let first = 0x1000usize as *mut u8;
        let filter_idx = global_semantic_pointer_filter_index(first);
        let mut candidate = 0x1008usize;
        let second = loop {
            let ptr = candidate as *mut u8;
            if global_semantic_pointer_filter_index(ptr) == filter_idx {
                break ptr;
            }
            candidate = candidate.checked_add(8).unwrap();
        };

        assert!(!global_semantic_pointer_maybe_tracked(first));
        assert!(!global_semantic_pointer_maybe_tracked(second));
        assert!(unsafe { record_global_auto_allocation_metadata(first, layout, metadata) });
        assert!(global_semantic_pointer_maybe_tracked(first));
        assert!(global_semantic_pointer_maybe_tracked(second));
        assert!(unsafe { record_global_auto_allocation_metadata(second, layout, metadata) });

        assert_eq!(
            recover_global_auto_allocation_record_metadata(first, layout, true),
            Some(metadata)
        );
        assert!(
            global_semantic_pointer_maybe_tracked(second),
            "removing one colliding record must not create a filter false negative"
        );
        assert_eq!(
            recover_global_auto_allocation_record_metadata(second, layout, true),
            Some(metadata)
        );
        assert!(!global_semantic_pointer_maybe_tracked(first));
    }

    #[cfg(not(feature = "reclaim_checks"))]
    #[test]
    fn semantic_pointer_filter_second_acquire_observes_publication_after_first_zero() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
            clear_scoped_metadata_gate_for_test();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();
        let _retained_only = RetainedOnlyLifecycleOverride::active();

        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let metadata = AllocationMetadata::for_type(0xC003_F118)
            .with_module(0xC0DE_F118)
            .with_callsite(0xA110_F118)
            .with_flags(FLAG_TYPE_ISOLATED)
            .with_placement_hint(PLACEMENT_HINT_CROSS_THREAD_RECOVERY);
        let ptr = 0x2000usize as *mut u8;
        assert!(!global_semantic_pointer_maybe_tracked(ptr));

        let hook = PointerFilterFirstZeroHookGuard::arm(ptr);
        let ptr_addr = ptr as usize;
        let query = thread::spawn(move || unsafe {
            semantic_runtime_slow_path_enabled_for_pointer(ptr_addr as *mut u8)
        });
        hook.wait_for_first_zero();
        let recorded = unsafe { record_global_auto_allocation_metadata(ptr, layout, metadata) };
        hook.release_query();
        let selected_slow_path = query.join().expect("pointer-filter slow-path query");

        assert!(recorded, "concurrent recovery publication must succeed");
        assert!(
            selected_slow_path,
            "the second acquire must observe publication after the first zero"
        );
        assert_eq!(
            recover_global_auto_allocation_record_metadata(ptr, layout, true),
            Some(metadata)
        );
        assert!(!global_semantic_pointer_maybe_tracked(ptr));
    }

    #[test]
    fn global_semantic_pointer_filter_refcounts_mixed_authority_colliders() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();

        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let metadata = AllocationMetadata::for_type(0xC003_F119)
            .with_module(0xC0DE_F119)
            .with_callsite(0xA110_F119)
            .with_flags(FLAG_TYPE_ISOLATED)
            .with_placement_hint(PLACEMENT_HINT_CROSS_THREAD_RECOVERY);
        let recovery_ptr = 0x3000usize as *mut u8;
        let filter_idx = global_semantic_pointer_filter_index(recovery_ptr);
        let mut candidate = 0x3008usize;
        let retained_ptr = loop {
            let ptr = candidate as *mut u8;
            if global_semantic_pointer_filter_index(ptr) == filter_idx {
                break ptr;
            }
            candidate = candidate.checked_add(8).unwrap();
        };
        let combined_count = || GLOBAL_SEMANTIC_POINTER_FILTER[filter_idx].load(Ordering::Acquire);

        assert_eq!(combined_count(), 0);
        assert!(unsafe { record_global_auto_allocation_metadata(recovery_ptr, layout, metadata) });
        assert_eq!(combined_count(), 1);
        assert_eq!(
            register_global_type_cache_ownership(retained_ptr),
            GlobalTypeCacheOwnershipRegistration::Inserted
        );
        assert_eq!(combined_count(), 2);

        assert_eq!(
            recover_global_auto_allocation_record_metadata(recovery_ptr, layout, true),
            Some(metadata)
        );
        assert_eq!(combined_count(), 1);
        assert!(global_semantic_pointer_maybe_tracked(recovery_ptr));

        assert!(unsafe { record_global_auto_allocation_metadata(recovery_ptr, layout, metadata) });
        assert_eq!(combined_count(), 2);
        assert!(unregister_global_type_cache_ownership(retained_ptr));
        assert_eq!(combined_count(), 1);
        assert!(global_semantic_pointer_maybe_tracked(retained_ptr));

        assert_eq!(
            recover_global_auto_allocation_record_metadata(recovery_ptr, layout, true),
            Some(metadata)
        );
        assert_eq!(combined_count(), 0);
        assert!(!global_semantic_pointer_maybe_tracked(retained_ptr));

        assert!(unsafe { record_global_auto_allocation_metadata(recovery_ptr, layout, metadata) });
        assert_eq!(
            register_global_type_cache_ownership(retained_ptr),
            GlobalTypeCacheOwnershipRegistration::Inserted
        );
        assert_eq!(combined_count(), 2);
        clear_auto_allocation_records();
        assert_eq!(
            combined_count(),
            1,
            "resetting recovery fixtures must preserve retained contributions"
        );
        clear_global_type_cache_ownership_for_test();
        assert_eq!(combined_count(), 0);
    }

    #[test]
    fn global_semantic_pointer_filter_preserves_concurrent_cross_domain_swaps() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();

        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let metadata = AllocationMetadata::for_type(0xC003_F120)
            .with_module(0xC0DE_F120)
            .with_callsite(0xA110_F120)
            .with_flags(FLAG_TYPE_ISOLATED)
            .with_placement_hint(PLACEMENT_HINT_CROSS_THREAD_RECOVERY);
        let recovery_ptr = 0x4000usize as *mut u8;
        let filter_idx = global_semantic_pointer_filter_index(recovery_ptr);
        let mut candidate = 0x4008usize;
        let retained_ptr = loop {
            let ptr = candidate as *mut u8;
            if global_semantic_pointer_filter_index(ptr) == filter_idx {
                break ptr;
            }
            candidate = candidate.checked_add(8).unwrap();
        };
        let combined_count = || GLOBAL_SEMANTIC_POINTER_FILTER[filter_idx].load(Ordering::Acquire);

        assert_eq!(
            register_global_type_cache_ownership(retained_ptr),
            GlobalTypeCacheOwnershipRegistration::Inserted
        );
        assert_eq!(combined_count(), 1);

        let first_swap_barrier = Barrier::new(3);
        let (recovery_inserted, retained_removed) = thread::scope(|scope| {
            let recovery_barrier = &first_swap_barrier;
            let retained_barrier = &first_swap_barrier;
            let recovery_addr = recovery_ptr as usize;
            let retained_addr = retained_ptr as usize;
            let recovery = scope.spawn(move || {
                recovery_barrier.wait();
                let result = unsafe {
                    record_global_auto_allocation_metadata(
                        recovery_addr as *mut u8,
                        layout,
                        metadata,
                    )
                };
                recovery_barrier.wait();
                result
            });
            let retained = scope.spawn(move || {
                retained_barrier.wait();
                let result = unregister_global_type_cache_ownership(retained_addr as *mut u8);
                retained_barrier.wait();
                result
            });
            first_swap_barrier.wait();
            first_swap_barrier.wait();
            (
                recovery.join().expect("recovery publication worker"),
                retained.join().expect("retained retirement worker"),
            )
        });

        assert!(recovery_inserted);
        assert!(retained_removed);
        assert_eq!(combined_count(), 1);
        assert_eq!(
            recover_global_auto_allocation_record_metadata(recovery_ptr, layout, false),
            Some(metadata)
        );
        assert!(!global_type_cache_contains_ptr(retained_ptr));
        assert!(global_semantic_pointer_maybe_tracked(recovery_ptr));
        assert!(global_semantic_pointer_maybe_tracked(retained_ptr));

        let second_swap_barrier = Barrier::new(3);
        let (recovery_removed, retained_inserted) = thread::scope(|scope| {
            let recovery_barrier = &second_swap_barrier;
            let retained_barrier = &second_swap_barrier;
            let recovery_addr = recovery_ptr as usize;
            let retained_addr = retained_ptr as usize;
            let recovery = scope.spawn(move || {
                recovery_barrier.wait();
                let result = recover_global_auto_allocation_record_metadata(
                    recovery_addr as *mut u8,
                    layout,
                    true,
                );
                recovery_barrier.wait();
                result
            });
            let retained = scope.spawn(move || {
                retained_barrier.wait();
                let result = register_global_type_cache_ownership(retained_addr as *mut u8);
                retained_barrier.wait();
                result
            });
            second_swap_barrier.wait();
            second_swap_barrier.wait();
            (
                recovery.join().expect("recovery retirement worker"),
                retained.join().expect("retained publication worker"),
            )
        });

        assert_eq!(recovery_removed, Some(metadata));
        assert_eq!(
            retained_inserted,
            GlobalTypeCacheOwnershipRegistration::Inserted
        );
        assert_eq!(combined_count(), 1);
        assert_eq!(
            recover_global_auto_allocation_record_metadata(recovery_ptr, layout, false),
            None
        );
        assert!(global_type_cache_contains_ptr(retained_ptr));
        assert!(global_semantic_pointer_maybe_tracked(recovery_ptr));
        assert!(global_semantic_pointer_maybe_tracked(retained_ptr));

        assert!(unregister_global_type_cache_ownership(retained_ptr));
        assert_eq!(combined_count(), 0);
        assert!(!global_semantic_pointer_maybe_tracked(recovery_ptr));
        assert!(!global_semantic_pointer_maybe_tracked(retained_ptr));
    }

    #[test]
    fn global_semantic_pointer_filter_tracks_retained_ownership_until_release() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }

        let ptr = 0x2800usize as *mut u8;
        assert!(!global_semantic_pointer_maybe_tracked(ptr));
        assert_eq!(
            register_global_type_cache_ownership(ptr),
            GlobalTypeCacheOwnershipRegistration::Inserted
        );
        assert!(global_semantic_pointer_maybe_tracked(ptr));
        assert!(unregister_global_type_cache_ownership(ptr));
        assert!(!global_semantic_pointer_maybe_tracked(ptr));
    }

    #[cfg(all(not(feature = "reclaim_checks"), not(feature = "quarantine")))]
    #[test]
    fn retained_filter_publishes_before_type_owner_entry() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();
        let _retained_only = RetainedOnlyLifecycleOverride::active();

        let alloc = RustAllocator::new();
        let layout = Layout::from_size_align(3 * size_of::<usize>(), align_of::<usize>()).unwrap();
        let ptr = unsafe { GlobalAlloc::alloc(&alloc, layout) };
        assert!(!ptr.is_null());
        assert!(!global_semantic_pointer_maybe_tracked(ptr));

        TEST_RETAINED_FILTER_PUBLICATION_PHASE.store(1, Ordering::Release);
        let ptr_addr = ptr as usize;
        let owner =
            thread::spawn(move || register_global_type_cache_ownership(ptr_addr as *mut u8));
        while TEST_RETAINED_FILTER_PUBLICATION_PHASE.load(Ordering::Acquire) != 2 {
            core::hint::spin_loop();
        }
        assert!(
            global_semantic_pointer_maybe_tracked(ptr),
            "the negative filter must publish before the retained entry"
        );

        TEST_POINTER_FILTER_SLOW_PATH_PHASE.store(1, Ordering::Release);
        let ptr_addr = ptr as usize;
        let foreign = thread::spawn(move || {
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                GlobalAlloc::dealloc(&RustAllocator::new(), ptr_addr as *mut u8, layout);
            }))
        });
        while TEST_POINTER_FILTER_SLOW_PATH_PHASE.load(Ordering::Acquire) != 2 {
            core::hint::spin_loop();
        }

        TEST_RETAINED_FILTER_PUBLICATION_PHASE.store(3, Ordering::Release);
        assert_eq!(
            owner.join().expect("retained owner publication thread"),
            GlobalTypeCacheOwnershipRegistration::Inserted
        );
        TEST_POINTER_FILTER_SLOW_PATH_PHASE.store(3, Ordering::Release);
        assert!(
            foreign
                .join()
                .expect("foreign retained-filter reclaim thread")
                .is_err(),
            "a foreign raw free queued behind filter publication must fail-stop"
        );
        TEST_RETAINED_FILTER_PUBLICATION_PHASE.store(0, Ordering::Release);
        TEST_POINTER_FILTER_SLOW_PATH_PHASE.store(0, Ordering::Release);

        assert!(global_type_cache_contains_ptr(ptr));
        assert!(global_semantic_pointer_maybe_tracked(ptr));
        assert_eq!(GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire), 1);
        assert!(unregister_global_type_cache_ownership(ptr));
        assert!(!global_semantic_pointer_maybe_tracked(ptr));
        unsafe {
            GlobalAlloc::dealloc(&alloc, ptr, layout);
        }
    }

    #[cfg(all(not(feature = "reclaim_checks"), not(feature = "quarantine")))]
    #[test]
    fn retained_only_filter_skips_unrelated_raw_global_alloc_lifecycle_work() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();
        let _retained_only = RetainedOnlyLifecycleOverride::active();

        let alloc = RustAllocator::new();
        let typed_layout =
            Layout::from_size_align(3 * size_of::<usize>(), align_of::<usize>()).unwrap();
        let typed_metadata = AllocationMetadata::for_type(0xC003_F118)
            .with_module(0xC0DE_F118)
            .with_callsite(0xA110_F118)
            .with_flags(FLAG_TYPE_ISOLATED)
            .with_placement_hint(PLACEMENT_HINT_CROSS_THREAD_RECOVERY);
        let typed = unsafe { alloc.alloc_with_recovery_metadata(typed_layout, typed_metadata) };
        assert!(!typed.is_null());
        assert!(global_semantic_pointer_maybe_tracked(typed));

        let raw_layout = Layout::from_size_align(192, align_of::<usize>()).unwrap();
        let probes_before = TEST_GLOBAL_ADDRESS_LIFECYCLE_TABLE_PROBES.load(Ordering::Relaxed);
        let admissions_before = TEST_GLOBAL_RAW_RECLAIM_ADMISSION_ENTRIES.load(Ordering::Relaxed);
        let raw = unsafe { GlobalAlloc::alloc(&alloc, raw_layout) };
        assert!(!raw.is_null());
        assert_eq!(
            TEST_GLOBAL_ADDRESS_LIFECYCLE_TABLE_PROBES.load(Ordering::Relaxed),
            probes_before,
            "an unrelated raw allocation must bypass lifecycle publication"
        );
        assert!(
            !global_semantic_pointer_maybe_tracked(raw),
            "test raw pointer unexpectedly collided with the tracked semantic filter bucket"
        );
        unsafe {
            GlobalAlloc::dealloc(&alloc, raw, raw_layout);
        }
        assert_eq!(
            TEST_GLOBAL_ADDRESS_LIFECYCLE_TABLE_PROBES.load(Ordering::Relaxed),
            probes_before,
            "an unrelated raw pointer must bypass lifecycle lookup after semantic activation"
        );
        assert_eq!(
            TEST_GLOBAL_RAW_RECLAIM_ADMISSION_ENTRIES.load(Ordering::Relaxed),
            admissions_before,
            "an unrelated raw pointer must bypass retained-ownership admission"
        );

        unsafe {
            GlobalAlloc::dealloc(&alloc, typed, typed_layout);
        }
        assert!(
            TEST_GLOBAL_ADDRESS_LIFECYCLE_TABLE_PROBES.load(Ordering::Relaxed) > probes_before,
            "the matching recovery pointer must retain the semantic reclaim path"
        );
        assert!(global_semantic_pointer_maybe_tracked(typed));
        unsafe {
            clear_type_cache_for_test();
            clear_auto_allocation_records();
        }
    }

    #[test]
    fn auto_allocation_record_shard_live_count_keeps_active_until_last_remove() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();

        let layout = Layout::from_size_align(96, align_of::<usize>()).unwrap();
        let first_ptr = (0x3B10usize << 4) as *mut u8;
        let shard_idx = auto_allocation_record_shard(first_ptr);
        let second_ptr = (0x3B11usize..0x3C80usize)
            .map(|candidate| (candidate << 4) as *mut u8)
            .find(|candidate| {
                auto_allocation_record_shard(*candidate) == shard_idx
                    && auto_allocation_record_shard_and_slot(*candidate).1
                        != auto_allocation_record_shard_and_slot(first_ptr).1
            })
            .expect("test pointer from same recovery shard but another slot");
        let first_metadata = AllocationMetadata::for_type(0xC002_3B10)
            .with_module(0xC0DE)
            .with_callsite(0xA110_3B10)
            .with_flags(FLAG_TYPE_ISOLATED);
        let second_metadata = AllocationMetadata::for_type(0xC002_3B11)
            .with_module(0xC0DE)
            .with_callsite(0xA110_3B11)
            .with_flags(FLAG_TYPE_ISOLATED);

        unsafe {
            assert!(record_global_auto_allocation_metadata(
                first_ptr,
                layout,
                first_metadata
            ));
            assert!(record_global_auto_allocation_metadata(
                second_ptr,
                layout,
                second_metadata
            ));
        }
        {
            let table = AUTO_ALLOCATION_RECORDS[shard_idx].lock();
            assert_eq!(
                table.live_count, 2,
                "normal inserts should maintain O(1) shard live-count metadata"
            );
        }
        assert_eq!(
            take_auto_deallocation_metadata(first_ptr, layout),
            Some(first_metadata)
        );
        {
            let table = AUTO_ALLOCATION_RECORDS[shard_idx].lock();
            assert_eq!(
                table.live_count, 1,
                "non-final removal should update live_count without scanning the whole shard"
            );
            assert!(
                auto_allocation_record_shard_is_active(
                    auto_allocation_record_active_shards(),
                    shard_idx
                ),
                "active bit must remain set while one live record remains in the shard"
            );
        }
        assert_eq!(
            take_auto_deallocation_metadata(second_ptr, layout),
            Some(second_metadata)
        );
        {
            let table = AUTO_ALLOCATION_RECORDS[shard_idx].lock();
            assert_eq!(table.live_count, 0);
        }
        assert!(
            !auto_allocation_record_shard_is_active(
                auto_allocation_record_active_shards(),
                shard_idx
            ),
            "removing the last shard record should clear the active bit"
        );
    }

    fn exercise_concurrent_last_global_recovery_remove(seed_overflow: bool) {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
            clear_scoped_metadata_gate_for_test();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();

        let alloc = RustAllocator::new();
        let layout = Layout::from_size_align(96, align_of::<usize>()).unwrap();
        let old_metadata = AllocationMetadata::for_type(0xC003_A001)
            .with_module(0xC0DE_A001)
            .with_placement_hint(PLACEMENT_HINT_CROSS_THREAD_RECOVERY);
        let new_metadata = AllocationMetadata::for_type(0xC003_B001)
            .with_module(0xC0DE_B001)
            .with_placement_hint(PLACEMENT_HINT_CROSS_THREAD_RECOVERY);
        let old_ptr = unsafe { alloc.alloc_raw(layout) };
        let new_ptr = unsafe { alloc.alloc_raw(layout) };
        assert!(!old_ptr.is_null() && !new_ptr.is_null());

        let old_shard_idx = auto_allocation_record_shard(old_ptr);
        if seed_overflow {
            #[cfg(not(feature = "fixed_heap"))]
            unsafe {
                increment_global_recovery_pointer_filter(old_ptr);
                let overflow =
                    auto_allocation_record_overflow_for_test(&[auto_allocation_record_for(
                        old_ptr,
                        layout,
                        old_metadata,
                    )]);
                let mut table = AUTO_ALLOCATION_RECORDS[old_shard_idx].lock();
                table.overflow = overflow;
                table.live_count = 1;
                AUTO_ALLOCATION_RECORD_COUNT.store(1, Ordering::Relaxed);
                auto_allocation_record_mark_shard_active(old_shard_idx);
                semantic_slow_path_set(SLOW_PATH_ALLOCATION_RECORDS);
            }
            #[cfg(feature = "fixed_heap")]
            panic!("fixed_heap does not support global recovery overflow pages");
        } else {
            assert!(unsafe {
                record_global_auto_allocation_metadata_eligible(old_ptr, layout, old_metadata)
            });
        }
        assert_eq!(AUTO_ALLOCATION_RECORD_COUNT.load(Ordering::Relaxed), 1);

        let new_home_shard_idx = auto_allocation_record_shard(new_ptr);
        let new_record_shard_idx = (0..AUTO_ALLOCATION_RECORD_SHARD_COUNT)
            .find(|&shard_idx| shard_idx != old_shard_idx && shard_idx != new_home_shard_idx)
            .expect("at least one independent recovery shard");

        TEST_LAST_GLOBAL_RECOVERY_REMOVE_PHASE.store(1, Ordering::Release);
        let old_ptr_addr = old_ptr as usize;
        let remover = thread::spawn(move || {
            recover_global_auto_allocation_record_metadata(old_ptr_addr as *mut u8, layout, true)
        });

        struct ResumeLastGlobalRecoveryRemove;
        impl Drop for ResumeLastGlobalRecoveryRemove {
            fn drop(&mut self) {
                TEST_LAST_GLOBAL_RECOVERY_REMOVE_PHASE.store(3, Ordering::Release);
            }
        }
        let resume_remove = ResumeLastGlobalRecoveryRemove;
        let pause_deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while TEST_LAST_GLOBAL_RECOVERY_REMOVE_PHASE.load(Ordering::Acquire) != 2 {
            if std::time::Instant::now() >= pause_deadline {
                drop(resume_remove);
                let _ = remover.join();
                panic!("last global recovery removal did not reach the test pause");
            }
            thread::yield_now();
        }

        let inserted = {
            let mut table = AUTO_ALLOCATION_RECORDS[new_record_shard_idx].lock();
            install_global_auto_allocation_inline_record(
                new_record_shard_idx,
                &mut *table,
                0,
                new_ptr,
                layout,
                new_metadata,
            )
        };
        let count_while_paused = AUTO_ALLOCATION_RECORD_COUNT.load(Ordering::Relaxed);
        let mask_while_paused = auto_allocation_record_active_shards();
        drop(resume_remove);
        let removed_metadata = remover.join();

        let count_after_race = AUTO_ALLOCATION_RECORD_COUNT.load(Ordering::Relaxed);
        let mask_after_race = auto_allocation_record_active_shards();
        let gate_after_race = semantic_runtime_slow_path_enabled();
        unsafe {
            GlobalAlloc::dealloc(&alloc, new_ptr, layout);
        }
        let new_record_survived_dealloc =
            lookup_auto_allocation_metadata(new_ptr, layout) == Some(new_metadata);
        if new_record_survived_dealloc {
            let _ = recover_global_auto_allocation_record_metadata(new_ptr, layout, true);
        }
        unsafe {
            alloc.dealloc_raw(old_ptr, layout);
            clear_auto_allocation_records();
        }
        TEST_LAST_GLOBAL_RECOVERY_REMOVE_PHASE.store(0, Ordering::Release);

        assert!(
            inserted,
            "concurrent recovery-record insertion should succeed"
        );
        assert_eq!(count_while_paused, 1);
        assert!(auto_allocation_record_shard_is_active(
            mask_while_paused,
            new_record_shard_idx
        ));
        assert_eq!(removed_metadata.unwrap(), Some(old_metadata));
        assert_eq!(count_after_race, 1);
        assert_eq!(
            mask_after_race,
            auto_allocation_record_shard_bit(new_record_shard_idx),
            "last removal must clear only its own shard bit"
        );
        assert!(
            gate_after_race,
            "a live global recovery record must keep GlobalAlloc deallocation on the semantic path"
        );
        assert!(
            !new_record_survived_dealloc,
            "GlobalAlloc deallocation must consume metadata inserted during the last-remove window"
        );
    }

    #[test]
    fn concurrent_last_inline_global_recovery_remove_preserves_new_record() {
        exercise_concurrent_last_global_recovery_remove(false);
    }

    #[cfg(not(feature = "fixed_heap"))]
    #[test]
    fn concurrent_last_overflow_global_recovery_remove_preserves_new_record() {
        exercise_concurrent_last_global_recovery_remove(true);
    }

    #[test]
    fn auto_allocation_record_active_offsets_iterate_only_set_shards_from_home() {
        let active_mask = auto_allocation_record_shard_bit(6)
            | auto_allocation_record_shard_bit(0)
            | auto_allocation_record_shard_bit(3)
            | (1usize << (AUTO_ALLOCATION_RECORD_SHARD_COUNT + 3));
        let mut active_offsets = auto_allocation_record_active_offsets_from_home(active_mask, 6);

        assert_eq!(
            pop_next_auto_allocation_record_active_shard(6, &mut active_offsets),
            Some((6, 0)),
            "the home shard should be probed first when it is active"
        );
        assert_eq!(
            pop_next_auto_allocation_record_active_shard(6, &mut active_offsets),
            Some((0, 2)),
            "iteration should wrap through active shards without visiting inactive ones"
        );
        assert_eq!(
            pop_next_auto_allocation_record_active_shard(6, &mut active_offsets),
            Some((3, 5))
        );
        assert_eq!(
            pop_next_auto_allocation_record_active_shard(6, &mut active_offsets),
            None,
            "bits outside the shard mask must not create bogus shard visits"
        );
    }

    #[test]
    fn auto_allocation_record_recover_includes_home_when_active_mask_stale() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();

        let layout = Layout::from_size_align(96, align_of::<usize>()).unwrap();
        let ptr = (0x3C10usize << 4) as *mut u8;
        let home_shard_idx = auto_allocation_record_shard(ptr);
        let stale_active_shard_idx = next_auto_allocation_record_shard(home_shard_idx, 1);
        let metadata = AllocationMetadata::for_type(0xC002_3C10)
            .with_module(0xC0DE)
            .with_callsite(0xA110_3C10)
            .with_flags(FLAG_TYPE_ISOLATED);

        unsafe {
            assert!(record_global_auto_allocation_metadata(
                ptr, layout, metadata
            ));
        }
        assert!(
            auto_allocation_record_shard_is_active(
                auto_allocation_record_active_shards(),
                home_shard_idx
            ),
            "normal insert should publish the home shard bit"
        );

        let stale_mask = auto_allocation_record_shard_bit(stale_active_shard_idx);
        AUTO_ALLOCATION_RECORD_ACTIVE_SHARDS.store(stale_mask, Ordering::Release);
        assert!(
            !auto_allocation_record_shard_is_active(
                auto_allocation_record_active_shards(),
                home_shard_idx
            ),
            "test deliberately simulates a stale nonzero active mask that omits the home shard"
        );
        assert_eq!(
            lookup_auto_allocation_metadata(ptr, layout),
            Some(metadata),
            "lookup must include the pointer's home shard even when the active-shard hint is stale"
        );
        assert_eq!(
            take_auto_deallocation_metadata(ptr, layout),
            Some(metadata),
            "removal must use the same home-including probe policy as lookup"
        );
        assert_eq!(AUTO_ALLOCATION_RECORD_COUNT.load(Ordering::Relaxed), 0);
        let final_mask = auto_allocation_record_active_shards();
        assert!(
            !auto_allocation_record_shard_is_active(final_mask, home_shard_idx),
            "final removal should clear the removed record's home-shard bit"
        );
        assert_eq!(
            final_mask, stale_mask,
            "shard-local removal must not globally clear an unrelated hint that could belong to a concurrent insertion"
        );
        clear_auto_allocation_records();
    }

    #[test]
    fn auto_allocation_record_inactive_home_shard_is_reused_before_other_active_shards() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();

        let layout = Layout::from_size_align(96, align_of::<usize>()).unwrap();
        let target_ptr = (0x3A10usize << 4) as *mut u8;
        let (home_shard_idx, _) = auto_allocation_record_shard_and_slot(target_ptr);
        let active_ptr = (0x3A10usize..0x3B10usize)
            .map(|candidate| (candidate << 4) as *mut u8)
            .find(|candidate| auto_allocation_record_shard(*candidate) != home_shard_idx)
            .expect("test pointer from a different recovery shard");
        let active_shard_idx = auto_allocation_record_shard(active_ptr);
        let active_metadata = AllocationMetadata::for_type(0xC002_3A01)
            .with_module(0xC0DE)
            .with_callsite(0xA110_3A01)
            .with_flags(FLAG_TYPE_ISOLATED);
        let target_metadata = AllocationMetadata::for_type(0xC002_3A10)
            .with_module(0xC0DE)
            .with_callsite(0xA110_3A10)
            .with_flags(FLAG_TYPE_ISOLATED);

        unsafe {
            assert!(record_global_auto_allocation_metadata(
                active_ptr,
                layout,
                active_metadata
            ));
        }
        let active_mask = auto_allocation_record_active_shards();
        assert!(
            auto_allocation_record_shard_is_active(active_mask, active_shard_idx),
            "the seed record should make an unrelated shard active"
        );
        assert!(
            !auto_allocation_record_shard_is_active(active_mask, home_shard_idx),
            "the target home shard should still be inactive before insertion"
        );

        unsafe {
            assert!(
                record_global_auto_allocation_metadata(target_ptr, layout, target_metadata),
                "active-mask insertion should still probe an inactive home shard first"
            );
        }
        let (record_shard_idx, _record_idx) =
            global_auto_allocation_record_location_for_test(target_ptr)
                .expect("target recovery record");
        assert_eq!(
            record_shard_idx, home_shard_idx,
            "an empty/inactive home shard is the lowest-contention reusable target even when another shard is active"
        );
        assert_eq!(
            lookup_auto_allocation_metadata(target_ptr, layout),
            Some(target_metadata)
        );
        assert_eq!(
            take_auto_deallocation_metadata(active_ptr, layout),
            Some(active_metadata),
            "the unrelated active-shard record must remain recoverable"
        );
        assert_eq!(
            take_auto_deallocation_metadata(target_ptr, layout),
            Some(target_metadata),
            "the newly installed inactive-home record must be recoverable"
        );

        clear_auto_allocation_records();
    }

    #[test]
    fn auto_allocation_record_shard_overflow_preserves_inline_capacity() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();

        let layout = Layout::from_size_align(96, align_of::<usize>()).unwrap();
        let ptr = (0x3900usize << 4) as *mut u8;
        let (home_shard_idx, _) = auto_allocation_record_shard_and_slot(ptr);
        let metadata = AllocationMetadata::for_type(0xC002_3901)
            .with_module(0xC0DE)
            .with_callsite(0xA110_C390)
            .with_flags(FLAG_TYPE_ISOLATED);

        {
            let mut home = AUTO_ALLOCATION_RECORDS[home_shard_idx].lock();
            for idx in 0..AUTO_ALLOCATION_RECORD_SHARD_SLOTS {
                let dummy_ptr = ((0x3900_0000usize + idx) << 4) as *mut u8;
                let dummy_metadata = AllocationMetadata::for_type(0xC002_3900 + idx as u64)
                    .with_module(0xC0DE)
                    .with_callsite(0xA110_3900 + idx as u64)
                    .with_flags(FLAG_TYPE_ISOLATED);
                home.inline[idx] = AutoAllocationRecord {
                    ptr: dummy_ptr as usize,
                    size: layout.size(),
                    align: layout.align(),
                    auth: derive_auto_allocation_record_auth(dummy_ptr, layout, dummy_metadata),
                    metadata: dummy_metadata,
                };
            }
        }
        AUTO_ALLOCATION_RECORD_COUNT.store(AUTO_ALLOCATION_RECORD_SHARD_SLOTS, Ordering::Relaxed);
        semantic_slow_path_set(SLOW_PATH_ALLOCATION_RECORDS);

        unsafe {
            assert!(
                record_global_auto_allocation_metadata(ptr, layout, metadata),
                "a full home shard should spill into home overflow before dropping recovery metadata"
            );
        }
        assert_eq!(
            AUTO_ALLOCATION_RECORD_COUNT.load(Ordering::Relaxed),
            AUTO_ALLOCATION_RECORD_SHARD_SLOTS + 1
        );
        #[cfg(not(feature = "fixed_heap"))]
        {
            assert!(
                global_auto_allocation_record_location_for_test(ptr).is_none(),
                "hosted home overflow must not shadow the record in another inline shard"
            );
            let home = AUTO_ALLOCATION_RECORDS[home_shard_idx].lock();
            assert!(
                find_auto_allocation_record_in_overflow(&home.overflow, ptr as usize).is_some(),
                "the overflow record should remain in its pointer-derived home shard"
            );
        }
        #[cfg(feature = "fixed_heap")]
        {
            let next_shard_idx = next_auto_allocation_record_shard(home_shard_idx, 1);
            let (record_shard_idx, _) = global_auto_allocation_record_location_for_test(ptr)
                .expect("fixed-heap overflow record");
            assert_eq!(
                record_shard_idx, next_shard_idx,
                "fixed-heap mode must retain its complete cross-shard inline capacity"
            );
        }
        assert_eq!(lookup_auto_allocation_metadata(ptr, layout), Some(metadata));
        assert_eq!(
            take_auto_deallocation_metadata(ptr, layout),
            Some(metadata),
            "recovery lookup must scan shard-overflow records, not only the home shard"
        );
        assert_eq!(
            AUTO_ALLOCATION_RECORD_COUNT.load(Ordering::Relaxed),
            AUTO_ALLOCATION_RECORD_SHARD_SLOTS
        );

        clear_auto_allocation_records();
    }

