    #[test]
    fn rsh031_recovery_layout_mismatch_is_exact_bound_and_policy_independent() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();

        let allocation_layout = Layout::from_size_align(1009, 256).unwrap();
        let vulnerable_deallocation_layout = Layout::from_size_align(1009, 1).unwrap();

        for (flags, type_id) in [(0, 0xC002_3100), (FLAG_TYPE_ISOLATED, 0xC002_3101)] {
            semantic_stats_reset();
            let metadata = AllocationMetadata::for_type(type_id)
                .with_module(0xC0DE_0310)
                .with_callsite(0xA110_0310)
                .with_flags(flags);
            let ptr = unsafe {
                __unialloc_alloc_with_metadata(
                    allocation_layout.size(),
                    allocation_layout.align(),
                    metadata.type_id,
                    metadata.module_id,
                    metadata.flags,
                    metadata.callsite,
                )
            };
            assert!(!ptr.is_null());

            let accepted = unsafe {
                __unialloc_dealloc_with_metadata(
                    ptr,
                    vulnerable_deallocation_layout.size(),
                    vulnerable_deallocation_layout.align(),
                    metadata.type_id,
                    metadata.module_id,
                    metadata.flags,
                    0xD310_0310,
                )
            };
            let observed = semantic_allocation_layout_validation_snapshot();
            assert!(!accepted, "RSH-031 layout mismatch must fail closed");
            assert_eq!(observed.recovery_deallocation_layout_mismatches, 1);
            assert_eq!(observed.last_requested_size, 1009);
            assert_eq!(observed.last_requested_align, 1);
            assert_eq!(observed.last_recorded_size, 1009);
            assert_eq!(observed.last_recorded_align, 256);
            assert_eq!(observed.last_recorded_type_id, metadata.type_id);
            assert_eq!(observed.last_recorded_module_id, metadata.module_id);
            assert_eq!(observed.last_recorded_callsite, metadata.callsite);
            assert_eq!(
                lookup_auto_allocation_metadata(ptr, allocation_layout),
                Some(metadata),
                "the diagnostic must stay bound to the live allocation record"
            );

            assert!(unsafe {
                __unialloc_dealloc_with_metadata(
                    ptr,
                    allocation_layout.size(),
                    allocation_layout.align(),
                    metadata.type_id,
                    metadata.module_id,
                    metadata.flags,
                    0xD310_0311,
                )
            });
            assert_eq!(
                semantic_allocation_layout_validation_snapshot()
                    .recovery_deallocation_layout_mismatches,
                1,
                "the exact-layout patched control must stay signal-free"
            );
            unsafe {
                clear_type_cache_for_test();
            }
        }
        semantic_stats_recording_disable();
    }

    #[test]
    fn ffi_dealloc_rejects_valid_but_mismatched_recovery_layout() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();

        let allocation_layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let wrong_layout = Layout::from_size_align(
            MIN_TYPE_CACHE_OBJECT_SIZE + align_of::<usize>(),
            align_of::<usize>(),
        )
        .unwrap();
        let metadata = AllocationMetadata::for_type(0xC002_BAD1)
            .with_module(0xC0DE)
            .with_callsite(0xA110_BAD1)
            .with_flags(FLAG_TYPE_ISOLATED);

        let ptr = unsafe {
            __unialloc_alloc_with_metadata(
                allocation_layout.size(),
                allocation_layout.align(),
                metadata.type_id,
                metadata.module_id,
                metadata.flags,
                metadata.callsite,
            )
        };
        assert!(!ptr.is_null());
        assert_eq!(
            lookup_auto_allocation_metadata(ptr, allocation_layout),
            Some(metadata)
        );

        let accepted = unsafe {
            __unialloc_dealloc_with_metadata(
                ptr,
                wrong_layout.size(),
                wrong_layout.align(),
                metadata.type_id,
                metadata.module_id,
                metadata.flags,
                metadata.callsite,
            )
        };
        let exact_record_after_mismatch = lookup_auto_allocation_metadata(ptr, allocation_layout);
        let wrong_layout_cache_entry = unsafe { pop_semantic_type_cache(wrong_layout, metadata) };

        assert!(
            !accepted,
            "a valid but allocation-mismatched Layout must be rejected by the recovery-backed deallocation ABI: accepted={}, exact_record_after_mismatch={:?}, wrong_layout_cache_entry={:?}",
            accepted,
            exact_record_after_mismatch,
            wrong_layout_cache_entry,
        );
        assert_eq!(
            exact_record_after_mismatch,
            Some(metadata),
            "layout mismatch must preserve the exact allocation record for a correct retry"
        );
        assert_eq!(
            wrong_layout_cache_entry, None,
            "layout mismatch must not publish the allocation into a cache under the caller's wrong Layout"
        );
        assert!(unsafe {
            __unialloc_dealloc_with_metadata(
                ptr,
                allocation_layout.size(),
                allocation_layout.align(),
                metadata.type_id,
                metadata.module_id,
                metadata.flags,
                metadata.callsite,
            )
        });
        assert_eq!(
            lookup_auto_allocation_metadata(ptr, allocation_layout),
            None
        );
        assert_eq!(
            unsafe { pop_semantic_type_cache(allocation_layout, metadata) },
            Some(ptr),
            "a correct retry must consume the preserved record and publish under the exact layout"
        );
        unsafe {
            RustAllocator::new().dealloc_raw(ptr, allocation_layout);
            clear_type_cache_for_test();
        }

        let allocator = RustAllocator::new();
        let trait_ptr =
            unsafe { allocator.alloc_with_recovery_metadata(allocation_layout, metadata) };
        assert!(!trait_ptr.is_null());
        assert_eq!(
            lookup_auto_allocation_metadata(trait_ptr, allocation_layout),
            Some(metadata)
        );
        unsafe {
            allocator.dealloc_with_metadata(trait_ptr, wrong_layout, metadata);
        }
        assert_eq!(
            lookup_auto_allocation_metadata(trait_ptr, allocation_layout),
            Some(metadata),
            "SemanticAlloc deallocation must also preserve the exact record on layout mismatch"
        );
        assert_eq!(
            unsafe { pop_semantic_type_cache(wrong_layout, metadata) },
            None,
            "SemanticAlloc layout mismatch must fail before wrong-layout cache publication"
        );
        unsafe {
            allocator.dealloc_with_metadata(trait_ptr, allocation_layout, metadata);
        }
        assert_eq!(
            lookup_auto_allocation_metadata(trait_ptr, allocation_layout),
            None,
            "the exact SemanticAlloc retry must consume the preserved record"
        );
        assert_eq!(
            unsafe { pop_semantic_type_cache(allocation_layout, metadata) },
            Some(trait_ptr)
        );
        unsafe {
            allocator.dealloc_raw(trait_ptr, allocation_layout);
            clear_type_cache_for_test();
        }
    }

    #[cfg(feature = "stats")]
    #[test]
    fn global_dealloc_rejects_valid_but_mismatched_recovery_layout() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_reset();

        let allocation_size = (MIN_TYPE_CACHE_OBJECT_SIZE..crate::size_class::MAX_SIZE)
            .find(|size| {
                crate::size_class::get_size_class(*size).index()
                    == crate::size_class::get_size_class(*size + 1).index()
            })
            .expect("test needs a distinct layout in the same allocator size class");
        let allocation_layout =
            Layout::from_size_align(allocation_size, align_of::<usize>()).unwrap();
        let wrong_size = allocation_size + 1;
        let wrong_layout = Layout::from_size_align(wrong_size, allocation_layout.align()).unwrap();
        let metadata = AllocationMetadata::for_type(0xC002_BAD2)
            .with_module(0xC0DE)
            .with_callsite(0xA110_BAD2)
            .with_flags(FLAG_TYPE_ISOLATED);
        let allocator = RustAllocator::new();
        let ptr = unsafe { allocator.alloc_with_recovery_metadata(allocation_layout, metadata) };
        assert!(!ptr.is_null());
        assert_eq!(
            lookup_auto_allocation_metadata(ptr, allocation_layout),
            Some(metadata)
        );

        let fallback_before = semantic_fallback_attribution_snapshot();
        unsafe {
            GlobalAlloc::dealloc(&allocator, ptr, wrong_layout);
        }
        let fallback_after = semantic_fallback_attribution_snapshot();
        assert_eq!(
            fallback_after.raw_dealloc_no_metadata,
            fallback_before.raw_dealloc_no_metadata,
            "a live same-pointer recovery mismatch must fail closed instead of falling through to raw GlobalAlloc deallocation"
        );
        assert_eq!(
            lookup_auto_allocation_metadata(ptr, allocation_layout),
            Some(metadata),
            "a rejected GlobalAlloc layout mismatch must preserve the exact recovery record for a correct retry"
        );

        unsafe {
            GlobalAlloc::dealloc(&allocator, ptr, allocation_layout);
        }
        assert_eq!(
            lookup_auto_allocation_metadata(ptr, allocation_layout),
            None
        );
        assert_eq!(
            unsafe { pop_semantic_type_cache(allocation_layout, metadata) },
            Some(ptr),
            "the exact retry must consume the record and publish only under the allocation layout"
        );
        unsafe {
            allocator.dealloc_raw(ptr, allocation_layout);
            clear_type_cache_for_test();
        }
        semantic_stats_recording_disable();
    }

    #[test]
    fn ffi_realloc_rejects_valid_but_mismatched_recovery_layout() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();

        let allocation_layout = Layout::from_size_align(63, align_of::<usize>()).unwrap();
        let wrong_old_layout = Layout::from_size_align(57, align_of::<usize>()).unwrap();
        assert_eq!(
            crate::size_class::get_size_class(allocation_layout.size()).index(),
            crate::size_class::get_size_class(wrong_old_layout.size()).index(),
            "regression uses a same-class mismatch so fail-first execution cannot copy beyond or raw-free with a larger caller layout"
        );
        let metadata = AllocationMetadata::for_type(0xC002_BAD2)
            .with_module(0xC0DE)
            .with_callsite(0xA110_BAD2)
            .with_flags(FLAG_TYPE_ISOLATED);
        let new_metadata = AllocationMetadata::for_type(0xC002_BAD3)
            .with_module(metadata.module_id)
            .with_callsite(0xA110_BAD3)
            .with_flags(metadata.flags);

        let ptr = unsafe {
            __unialloc_alloc_with_metadata(
                allocation_layout.size(),
                allocation_layout.align(),
                metadata.type_id,
                metadata.module_id,
                metadata.flags,
                metadata.callsite,
            )
        };
        assert!(!ptr.is_null());
        unsafe {
            ptr.write_volatile(0xA5);
            ptr.add(allocation_layout.size() - 1).write_volatile(0x5A);
        }

        let single_result = unsafe {
            __unialloc_realloc_with_metadata(
                ptr,
                wrong_old_layout.size(),
                wrong_old_layout.align(),
                wrong_old_layout.size(),
                metadata.type_id,
                metadata.module_id,
                metadata.flags,
                metadata.callsite,
            )
        };
        assert!(
            single_result.is_null(),
            "single-metadata realloc must reject a valid layout that mismatches the live recovery record"
        );
        assert_eq!(
            lookup_auto_allocation_metadata(ptr, allocation_layout),
            Some(metadata)
        );

        let split_result = unsafe {
            __unialloc_realloc_with_split_metadata(
                ptr,
                wrong_old_layout.size(),
                wrong_old_layout.align(),
                wrong_old_layout.size(),
                metadata.type_id,
                metadata.module_id,
                metadata.flags,
                metadata.callsite,
                new_metadata.type_id,
                new_metadata.module_id,
                new_metadata.flags,
                new_metadata.callsite,
            )
        };
        assert!(
            split_result.is_null(),
            "split-metadata realloc must reject the same allocation-record layout mismatch"
        );
        assert_eq!(
            lookup_auto_allocation_metadata(ptr, allocation_layout),
            Some(metadata),
            "failed realloc attempts must preserve the exact allocation record"
        );
        assert_eq!(unsafe { ptr.read_volatile() }, 0xA5);
        assert_eq!(
            unsafe { ptr.add(allocation_layout.size() - 1).read_volatile() },
            0x5A,
            "failed realloc attempts must leave the original payload intact"
        );

        assert!(unsafe {
            __unialloc_dealloc_with_metadata(
                ptr,
                allocation_layout.size(),
                allocation_layout.align(),
                metadata.type_id,
                metadata.module_id,
                metadata.flags,
                metadata.callsite,
            )
        });
        assert_eq!(
            unsafe { pop_semantic_type_cache(allocation_layout, metadata) },
            Some(ptr)
        );
        unsafe {
            RustAllocator::new().dealloc_raw(ptr, allocation_layout);
            clear_type_cache_for_test();
        }
    }

    #[test]
    fn semantic_realloc_rejects_valid_but_mismatched_recovery_layout_before_zero_size() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();

        let allocation_size = (MIN_TYPE_CACHE_OBJECT_SIZE + 1..crate::size_class::MAX_SIZE - 1)
            .find(|size| {
                crate::size_class::get_size_class(*size).index()
                    == crate::size_class::get_size_class(*size - 1).index()
            })
            .expect("test needs a distinct smaller Layout in one allocator size class");
        let allocation_layout =
            Layout::from_size_align(allocation_size, align_of::<usize>()).unwrap();
        let wrong_old_layout =
            Layout::from_size_align(allocation_size - 1, allocation_layout.align()).unwrap();
        let metadata = AllocationMetadata::for_type(0xC002_BAD4)
            .with_module(0xC0DE_BAD4)
            .with_callsite(0xA110_BAD4)
            .with_flags(FLAG_TYPE_ISOLATED);
        let new_metadata = AllocationMetadata::for_type(0xC002_BAD5)
            .with_module(metadata.module_id)
            .with_callsite(0xA110_BAD5)
            .with_flags(metadata.flags);
        let allocator = RustAllocator::new();
        let ptr = unsafe { allocator.alloc_with_recovery_metadata(allocation_layout, metadata) };
        assert!(!ptr.is_null());
        unsafe {
            core::ptr::write_bytes(ptr, 0xA5, allocation_layout.size());
        }
        assert_eq!(
            lookup_auto_allocation_metadata(ptr, allocation_layout),
            Some(metadata)
        );

        let validation_before = semantic_metadata_validation_snapshot();
        let cache_before = type_isolation_side_cache_snapshot();
        let delayed_before = delayed_free_snapshot();
        let record_count_before = AUTO_ALLOCATION_RECORD_COUNT.load(Ordering::Relaxed);
        let result = unsafe {
            SemanticAlloc::realloc_with_split_metadata(
                &allocator,
                ptr,
                wrong_old_layout,
                0,
                metadata,
                new_metadata,
            )
        };
        let validation_after = semantic_metadata_validation_snapshot();
        let cache_after = type_isolation_side_cache_snapshot();
        let delayed_after = delayed_free_snapshot();
        let record_count_after = AUTO_ALLOCATION_RECORD_COUNT.load(Ordering::Relaxed);
        let exact_record_after = lookup_auto_allocation_metadata(ptr, allocation_layout);
        let wrong_record_after = lookup_auto_allocation_metadata(ptr, wrong_old_layout);
        let wrong_cache_after = unsafe { pop_semantic_type_cache(wrong_old_layout, metadata) };

        let payload_preserved = if result.is_null() {
            let preserved = (0..allocation_layout.size())
                .all(|offset| unsafe { ptr.add(offset).read_volatile() } == 0xA5);
            unsafe {
                allocator.dealloc_with_metadata(ptr, allocation_layout, metadata);
            }
            assert_eq!(
                unsafe { pop_semantic_type_cache(allocation_layout, metadata) },
                Some(ptr),
                "exact cleanup must consume the record and publish only under the allocation Layout"
            );
            unsafe {
                allocator.dealloc_raw(ptr, allocation_layout);
                clear_type_cache_for_test();
            }
            preserved
        } else {
            // A fail-first implementation returned a non-null zero-size
            // sentinel while the old allocation remained live. Remove only the
            // stale record before failing; do not assume it is safe to touch or
            // release the old address after an unexpected success.
            let _ = take_recorded_reallocation_old_metadata(ptr, allocation_layout);
            false
        };

        assert!(
            result.is_null(),
            "direct SemanticAlloc split realloc must reject a live same-address/different-Layout record instead of returning a zero-size success sentinel"
        );
        assert_eq!(validation_after, validation_before);
        assert_eq!(cache_after, cache_before);
        assert_eq!(delayed_after, delayed_before);
        assert_eq!(record_count_after, record_count_before);
        assert_eq!(exact_record_after, Some(metadata));
        assert_eq!(wrong_record_after, None);
        assert_eq!(wrong_cache_after, None);
        assert!(
            payload_preserved,
            "mismatched semantic realloc changed payload"
        );
    }

    #[test]
    fn plain_global_recovery_record_reuses_auth_word_for_publisher_and_stays_layout_exact() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();

        let layout = Layout::from_size_align(96, align_of::<usize>()).unwrap();
        let wrong_layout = Layout::from_size_align(128, align_of::<usize>()).unwrap();
        let ptr = (0x4480usize << 4) as *mut u8;
        let metadata = AllocationMetadata::for_type(0xC002_2480)
            .with_module(0xC0DE)
            .with_callsite(0xA110_C248)
            .with_flags(FLAG_TYPE_ISOLATED)
            .with_lifetime_hint(0x17)
            .with_placement_hint(PLACEMENT_HINT_CROSS_THREAD_RECOVERY);

        assert!(unsafe { record_global_auto_allocation_metadata(ptr, layout, metadata) });
        let (shard_idx, record_idx) = global_auto_allocation_record_location_for_test(ptr)
            .expect("plain global recovery record");
        {
            let table = AUTO_ALLOCATION_RECORDS[shard_idx].lock();
            assert_eq!(
                table.inline[record_idx].auth,
                current_auto_allocation_publisher_thread_token(),
                "plain cross-thread recovery must bind its publisher thread without integrity hashing"
            );
            assert_eq!(
                table.inline[record_idx].align & AUTO_ALLOCATION_RECORD_INTEGRITY_ALIGN_BIT,
                0
            );
            assert_eq!(table.inline[record_idx].recorded_align(), layout.align());
            assert!(table.inline[record_idx].matches_allocation(ptr, layout));
        }
        assert_eq!(lookup_auto_allocation_metadata(ptr, wrong_layout), None);
        assert_eq!(lookup_auto_allocation_metadata(ptr, layout), Some(metadata));
        assert_eq!(take_auto_deallocation_metadata(ptr, layout), Some(metadata));
        assert_eq!(take_auto_deallocation_metadata(ptr, layout), None);

        clear_auto_allocation_records();
    }

