    #[test]
    fn typed_duplicate_free_plain_conservative_does_not_publish_cache_aliases() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();

        let alloc = RustAllocator::new();
        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let metadata = AllocationMetadata::for_type(0xD0B1_EF01)
            .with_module(0xC0DE_D0B1)
            .with_callsite(0xA110_D0B1)
            .with_flags(FLAG_TYPE_ISOLATED);
        let ptr = unsafe { alloc.alloc_with_recovery_metadata(layout, metadata) };
        assert!(!ptr.is_null());

        unsafe {
            alloc.dealloc_with_metadata(ptr, layout, metadata);
        }
        let duplicate_rejected =
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                alloc.dealloc_with_metadata(ptr, layout, metadata);
            }))
            .is_err();

        // Pop through the no-recovery path so a duplicate recovery-record insert
        // cannot hide two cache entries that claim the same allocation address.
        let first = unsafe { alloc.alloc_with_no_recovery_metadata(layout, metadata) };
        let second = unsafe { alloc.alloc_with_no_recovery_metadata(layout, metadata) };
        let allocations_succeeded = !first.is_null() && !second.is_null();
        let aliases = first == second;
        unsafe {
            dealloc_unique_test_pair(&alloc, layout, first, second);
            clear_type_cache_for_test();
            clear_auto_allocation_records();
        }

        assert!(
            allocations_succeeded,
            "duplicate-free probe allocations failed"
        );
        assert!(
            !aliases,
            "a conservative typed duplicate free published the same address twice; duplicate_rejected={}",
            duplicate_rejected
        );
    }

    #[test]
    fn global_type_cache_ownership_reuses_tombstone_without_hiding_colliding_owner() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
        }

        // These synthetic aligned addresses are registry keys only; the test
        // never dereferences or releases them. Fill one complete bounded probe
        // window so the next key must fail closed under registry pressure.
        let target = global_type_cache_ownership_shard_and_slot(8usize as *mut u8);
        let mut colliders = Vec::with_capacity(GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT + 1);
        let mut address = 8usize;
        while colliders.len() <= GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT {
            let ptr = address as *mut u8;
            if global_type_cache_ownership_shard_and_slot(ptr) == target {
                colliders.push(ptr);
            }
            address = address.checked_add(8).unwrap();
        }

        for &ptr in &colliders[..GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT] {
            assert_eq!(
                register_global_type_cache_ownership(ptr),
                GlobalTypeCacheOwnershipRegistration::Inserted
            );
        }
        let replacement = colliders[GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT];
        assert_eq!(
            register_global_type_cache_ownership(replacement),
            GlobalTypeCacheOwnershipRegistration::Full
        );

        let removed = colliders[GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT / 2];
        let tail = colliders[GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT - 1];
        assert!(unregister_global_type_cache_ownership(removed));
        assert!(global_type_cache_contains_ptr(tail));
        assert_eq!(
            register_global_type_cache_ownership(tail),
            GlobalTypeCacheOwnershipRegistration::Duplicate
        );
        assert_eq!(
            register_global_type_cache_ownership(replacement),
            GlobalTypeCacheOwnershipRegistration::Inserted
        );
        assert!(global_type_cache_contains_ptr(replacement));

        for &ptr in &colliders[..GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT] {
            if ptr != removed {
                assert!(unregister_global_type_cache_ownership(ptr));
            }
        }
        assert!(unregister_global_type_cache_ownership(replacement));
        assert_eq!(GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire), 0);
    }

    #[test]
    fn global_type_cache_ownership_concurrent_duplicate_registration_has_single_owner() {
        const WORKERS: usize = 16;

        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
        }

        let baseline = GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire);
        let ptr_addr = 0x1000usize;
        let barrier = std::sync::Arc::new(std::sync::Barrier::new(WORKERS));
        let mut workers = Vec::with_capacity(WORKERS);
        for _ in 0..WORKERS {
            let barrier = barrier.clone();
            workers.push(thread::spawn(move || {
                barrier.wait();
                register_global_type_cache_ownership(ptr_addr as *mut u8)
            }));
        }

        let mut inserted = 0usize;
        let mut duplicate = 0usize;
        let mut full = 0usize;
        for worker in workers {
            match worker
                .join()
                .expect("ownership registration worker panicked")
            {
                GlobalTypeCacheOwnershipRegistration::Inserted => inserted += 1,
                GlobalTypeCacheOwnershipRegistration::Duplicate => duplicate += 1,
                GlobalTypeCacheOwnershipRegistration::Full => full += 1,
            }
        }

        assert_eq!(
            inserted, 1,
            "exactly one concurrent registrant owns the key"
        );
        assert_eq!(duplicate, WORKERS - 1);
        assert_eq!(full, 0);
        assert!(global_type_cache_contains_ptr(ptr_addr as *mut u8));
        assert_eq!(
            GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire),
            baseline + 1
        );

        assert!(unregister_global_type_cache_ownership(ptr_addr as *mut u8));
        assert!(!global_type_cache_contains_ptr(ptr_addr as *mut u8));
        assert_eq!(
            GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire),
            baseline
        );
    }

