    #[cfg(not(feature = "fixed_heap"))]
    #[test]
    fn queued_alignment_changing_grow_rejects_after_release_and_reuse() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
        }
        TEST_STALE_RECLAIM_PHASE.store(0, Ordering::Release);
        let alloc = RustAllocator::new();
        let old_layout = Layout::from_size_align(24, align_of::<usize>()).unwrap();
        let new_layout = Layout::from_size_align(48, align_of::<usize>() * 2).unwrap();
        let ptr = unsafe { alloc.alloc_raw(old_layout) };
        assert!(!ptr.is_null());
        let ptr_addr = ptr as usize;
        let waiter = thread::spawn(move || {
            let alloc = RustAllocator::new();
            unsafe {
                TEST_PAUSE_NEXT_RECLAIM_AFTER_SNAPSHOT = true;
            }
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                core::alloc::Allocator::grow(
                    &alloc,
                    NonNull::new_unchecked(ptr_addr as *mut u8),
                    old_layout,
                    new_layout,
                )
            }))
            .is_err()
        });
        while TEST_STALE_RECLAIM_PHASE.load(Ordering::Acquire) != 2 {
            thread::yield_now();
        }
        unsafe {
            alloc.dealloc_with_recovered_metadata(ptr, old_layout, AllocationMetadata::unknown());
        }
        let reused = unsafe { alloc.alloc_raw(old_layout) };
        assert_eq!(reused, ptr);
        TEST_STALE_RECLAIM_PHASE.store(3, Ordering::Release);
        assert!(waiter.join().expect("alignment-changing grow waiter"));
        unsafe {
            alloc.dealloc_raw(reused, old_layout);
        }
        TEST_STALE_RECLAIM_PHASE.store(0, Ordering::Release);
    }

    #[test]
    fn concurrent_delayed_and_type_cache_ownership_never_publish_same_pointer() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
        }

        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();

        let alloc = RustAllocator::new();
        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let delayed_metadata = AllocationMetadata::for_type(0xD17A_D0C3)
            .with_module(0xC0DE_D0C3)
            .with_callsite(0xA110_D0C3)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_DELAYED_FREE);
        let type_cache_metadata = delayed_metadata
            .with_callsite(0xA110_D0C4)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_FORCE_INITIALIZE);
        assert!(type_cache_eligible(layout, type_cache_metadata));

        let ptr = unsafe { alloc.alloc_raw(layout) };
        assert!(!ptr.is_null());
        unsafe {
            ptr.write_bytes(0xA7, layout.size());
        }
        let ptr_addr = ptr as usize;
        let missing_delayed_source = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _ = begin_global_type_cache_ownership_for_delayed_handoff(ptr_addr as *mut u8);
        }));
        assert!(
            missing_delayed_source.is_err(),
            "the handoff-only helper must reject a pointer without delayed ownership"
        );
        assert!(!global_type_cache_contains_ptr(ptr_addr as *mut u8));

        TEST_CROSS_DOMAIN_DEALLOC_WAITERS.store(0, Ordering::Release);
        assert_eq!(
            TEST_CROSS_DOMAIN_DEALLOC_PHASE.compare_exchange(
                0,
                1,
                Ordering::AcqRel,
                Ordering::Acquire,
            ),
            Ok(0),
            "cross-domain deallocation phase must start idle"
        );
        let start = std::sync::Arc::new(std::sync::Barrier::new(3));
        let (outcome_tx, outcome_rx) = std::sync::mpsc::channel();
        let (delayed_release_tx, delayed_release_rx) = std::sync::mpsc::channel();
        let (type_release_tx, type_release_rx) = std::sync::mpsc::channel();

        let delayed_start = start.clone();
        let delayed_tx = outcome_tx.clone();
        let delayed = thread::spawn(move || {
            delayed_start.wait();
            let returned = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                RustAllocator::new().dealloc_with_recovered_metadata(
                    ptr_addr as *mut u8,
                    layout,
                    delayed_metadata,
                );
            }))
            .is_ok();
            let _ = delayed_tx.send(("delayed", returned));
            let _ = delayed_release_rx.recv_timeout(std::time::Duration::from_secs(30));
            unsafe {
                // Detach the winning TLS record without releasing the shared
                // allocation; the parent performs exactly one raw free after
                // both workers have terminated, even on a regression where
                // both domains were incorrectly published.
                clear_delayed_free_for_test();
            }
        });

        let type_start = start.clone();
        let type_tx = outcome_tx.clone();
        let type_cache = thread::spawn(move || {
            type_start.wait();
            let returned = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                RustAllocator::new().dealloc_with_recovered_metadata(
                    ptr_addr as *mut u8,
                    layout,
                    type_cache_metadata,
                );
            }))
            .is_ok();
            let _ = type_tx.send(("type-cache", returned));
            let _ = type_release_rx.recv_timeout(std::time::Duration::from_secs(30));
            unsafe {
                clear_type_cache_for_test();
            }
        });
        drop(outcome_tx);

        start.wait();
        let phase_deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while TEST_CROSS_DOMAIN_DEALLOC_WAITERS.load(Ordering::Acquire) != 2
            && std::time::Instant::now() < phase_deadline
        {
            thread::yield_now();
        }
        let phase_synchronized = TEST_CROSS_DOMAIN_DEALLOC_WAITERS.load(Ordering::Acquire) == 2;
        TEST_CROSS_DOMAIN_DEALLOC_PHASE.store(2, Ordering::Release);

        let first = outcome_rx.recv_timeout(std::time::Duration::from_secs(10));
        let second = outcome_rx.recv_timeout(std::time::Duration::from_secs(10));
        let outcomes = [first.ok(), second.ok()];
        let delayed_returned = outcomes
            .iter()
            .flatten()
            .find_map(|(domain, returned)| (*domain == "delayed").then_some(*returned));
        let type_cache_returned = outcomes
            .iter()
            .flatten()
            .find_map(|(domain, returned)| (*domain == "type-cache").then_some(*returned));
        let delayed_published = global_delayed_free_contains_ptr(ptr);
        let type_cache_published = global_type_cache_contains_ptr(ptr);

        // Always unblock and join both workers before making assertions. Each
        // worker also has a bounded receive as a last-resort cleanup guarantee.
        let _ = delayed_release_tx.send(());
        let _ = type_release_tx.send(());
        let delayed_joined = delayed.join();
        let type_cache_joined = type_cache.join();
        TEST_CROSS_DOMAIN_DEALLOC_PHASE.store(0, Ordering::Release);
        TEST_CROSS_DOMAIN_DEALLOC_WAITERS.store(0, Ordering::Release);

        // A regression may have published both domains. Retire any surviving
        // test records, then free the real allocation exactly once.
        let _ = unregister_global_delayed_free_ownership(ptr);
        let _ = unregister_global_type_cache_ownership(ptr);
        unsafe {
            alloc.dealloc_raw(ptr, layout);
        }

        assert!(
            phase_synchronized,
            "both real deallocations must reach the deterministic race phase"
        );
        assert!(
            delayed_joined.is_ok(),
            "delayed deallocation worker panicked outside its catch boundary"
        );
        assert!(
            type_cache_joined.is_ok(),
            "type-cache deallocation worker panicked outside its catch boundary"
        );
        let delayed_returned = delayed_returned.expect("delayed deallocation outcome");
        let type_cache_returned = type_cache_returned.expect("type-cache deallocation outcome");
        assert!(
            delayed_returned ^ type_cache_returned,
            "exactly one concurrent real deallocation may complete ownership publication"
        );
        assert!(
            delayed_published ^ type_cache_published,
            "the same real allocation must be visible in exactly one retained ownership registry"
        );
        assert_eq!(delayed_returned, delayed_published);
        assert_eq!(type_cache_returned, type_cache_published);
        assert!(!global_delayed_free_contains_ptr(ptr));
        assert!(!global_type_cache_contains_ptr(ptr));
    }

    #[test]
    fn type_cache_owned_pointer_rejects_raw_reclaim_without_mutation() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
        }

        let alloc = RustAllocator::new();
        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        for (action, sentinel) in [("dealloc", 0xA5), ("realloc", 0x5A)] {
            let ptr = unsafe { alloc.alloc_raw(layout) };
            assert!(!ptr.is_null());
            unsafe {
                ptr.write_bytes(sentinel, layout.size());
            }
            assert_eq!(
                register_global_type_cache_ownership(ptr),
                GlobalTypeCacheOwnershipRegistration::Inserted
            );
            let registered = GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire);

            let rejection = match action {
                "dealloc" => std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                    alloc.dealloc_raw(ptr, layout);
                })),
                "realloc" => std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                    let _ = alloc.realloc_raw(ptr, layout, layout.size() * 2);
                })),
                _ => unreachable!(),
            };
            match rejection {
                Ok(()) => panic!(
                    "raw {} returned after reclaiming its independently owned test pointer",
                    action
                ),
                Err(payload) => {
                    let expected =
                        payload.downcast_ref::<&str>().is_some_and(|message| {
                            *message == "type-cache pointer already retained"
                        }) || payload.downcast_ref::<std::string::String>().is_some_and(
                            |message| message == "type-cache pointer already retained",
                        );
                    assert!(
                        expected,
                        "raw {} panicked for an unexpected reason before storage verification",
                        action
                    );
                }
            }

            assert!(global_type_cache_contains_ptr(ptr));

            assert_eq!(
                GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire),
                registered,
                "rejected raw entry point must not mutate ownership"
            );
            for offset in 0..layout.size() {
                assert_eq!(unsafe { ptr.add(offset).read() }, sentinel);
            }

            assert!(unregister_global_type_cache_ownership(ptr));
            assert_eq!(GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire), 0);
            unsafe {
                alloc.dealloc_raw(ptr, layout);
            }
        }
    }

    #[test]
    fn type_cache_owned_pointer_globalalloc_entrypoints_fail_stop() {
        const CHILD_ENV: &str = "UNIALLOC_TYPE_CACHE_GLOBALALLOC_DEATH";
        const TEST_NAME: &str = concat!(
            "alloc_api::type_isolation::tests::",
            "type_cache_owned_pointer_globalalloc_entrypoints_fail_stop"
        );

        if let Some(action) = std::env::var_os(CHILD_ENV) {
            const EXPECTED_ABORT_MARKER: &[u8] =
                b"UNIALLOC_TYPE_CACHE_GUARD_ABORT:type-cache pointer already retained\n";
            const UNEXPECTED_ABORT_MARKER: &[u8] = b"UNIALLOC_UNEXPECTED_GLOBALALLOC_PANIC\n";
            std::panic::set_hook(Box::new(|info| {
                let expected = info
                    .payload()
                    .downcast_ref::<&str>()
                    .is_some_and(|message| *message == "type-cache pointer already retained")
                    || info
                        .payload()
                        .downcast_ref::<std::string::String>()
                        .is_some_and(|message| message == "type-cache pointer already retained");
                let marker = if expected {
                    EXPECTED_ABORT_MARKER
                } else {
                    UNEXPECTED_ABORT_MARKER
                };
                let _ = std::io::Write::write_all(&mut std::io::stderr(), marker);
                std::process::abort();
            }));
            let _guard = test_guard();
            unsafe {
                clear_type_cache_for_test();
                clear_delayed_free_for_test();
            }
            let alloc = RustAllocator::new();
            let layout =
                Layout::from_size_align(3 * size_of::<usize>(), align_of::<usize>()).unwrap();
            let ptr = unsafe { alloc.alloc_raw(layout) };
            assert!(!ptr.is_null());
            unsafe {
                ptr.write_bytes(0x5A, layout.size());
            }
            assert_eq!(
                register_global_type_cache_ownership(ptr),
                GlobalTypeCacheOwnershipRegistration::Inserted
            );

            match action.to_str().expect("ASCII child action") {
                "dealloc" => unsafe {
                    <RustAllocator as GlobalAlloc>::dealloc(&alloc, ptr, layout)
                },
                "realloc" => unsafe {
                    let _ = <RustAllocator as GlobalAlloc>::realloc(
                        &alloc,
                        ptr,
                        layout,
                        layout.size() * 2,
                    );
                },
                other => panic!("unknown GlobalAlloc death-test action: {}", other),
            }
            let _ = std::io::Write::write_all(
                &mut std::io::stderr(),
                b"UNIALLOC_GLOBALALLOC_GUARD_RETURNED\n",
            );
            std::process::abort();
        }

        for action in ["dealloc", "realloc"] {
            let output = std::process::Command::new(
                std::env::current_exe().expect("current type-isolation test executable"),
            )
            .args(["--exact", TEST_NAME, "--nocapture"])
            .env(CHILD_ENV, action)
            .env("RUST_BACKTRACE", "0")
            .output()
            .expect("spawn isolated GlobalAlloc cache-ownership death test");
            assert!(
                !output.status.success(),
                "GlobalAlloc {} child unexpectedly succeeded",
                action
            );
            let stderr = std::string::String::from_utf8_lossy(&output.stderr);
            assert!(
                stderr.contains(
                    "UNIALLOC_TYPE_CACHE_GUARD_ABORT:type-cache pointer already retained"
                ),
                "GlobalAlloc {} child failed for the wrong reason: {}",
                action,
                stderr
            );
            assert!(
                !stderr.contains("UNIALLOC_GLOBALALLOC_GUARD_RETURNED")
                    && !stderr.contains("UNIALLOC_UNEXPECTED_GLOBALALLOC_PANIC"),
                "GlobalAlloc {} bypassed the ownership guard: {}",
                action,
                stderr
            );
        }
    }

    #[test]
    fn retained_type_cache_ownership_rejects_raw_reclaim_and_preserves_exact_reuse() {
        const CHILD_ENV: &str = "UNIALLOC_RETAINED_TYPE_CACHE_RAW_GUARD";
        const TEST_NAME: &str = concat!(
            "alloc_api::type_isolation::tests::",
            "retained_type_cache_ownership_rejects_raw_reclaim_and_preserves_exact_reuse"
        );

        if let Some(action) = std::env::var_os(CHILD_ENV) {
            let action = action.to_str().expect("ASCII child action");
            let _guard = test_guard();
            let _cleanup = SemanticStateCleanup;
            unsafe {
                clear_type_cache_for_test();
                clear_delayed_free_for_test();
                clear_auto_allocation_records();
            }
            semantic_auto_metadata_disable();
            semantic_stats_recording_disable();
            semantic_type_stats_recording_disable();

            let alloc = RustAllocator::new();
            let layout =
                Layout::from_size_align(3 * size_of::<usize>(), align_of::<usize>()).unwrap();
            let metadata = AllocationMetadata::for_type(0xD0B1_EF05)
                .with_module(0xC0DE_D0B5)
                .with_callsite(0xA110_D0B5)
                .with_flags(FLAG_TYPE_ISOLATED);
            let sentinel = match action {
                "dealloc" => 0xA5,
                "realloc" => 0x5A,
                other => panic!("unknown raw reclaim action: {}", other),
            };

            let ptr = unsafe { alloc.alloc_with_metadata(layout, metadata) };
            assert!(!ptr.is_null());
            unsafe {
                ptr.write_bytes(sentinel, layout.size());
                alloc.dealloc_with_metadata(ptr, layout, metadata);
            }

            let retained = unsafe { inline_type_cache_entry_snapshot_for_test() };
            assert_eq!(retained.ptr, ptr);
            assert_eq!(
                retained.identity,
                TypeCacheIdentity::from_metadata(metadata)
            );
            assert!(global_type_cache_contains_ptr(ptr));
            assert_eq!(GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire), 1);

            // Each action runs in its own process. If a missing guard reclaims
            // the retained pointer, fail without touching that pointer again;
            // process exit contains the leaked/stale test-only cache state.
            let rejection = match action {
                "dealloc" => std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                    alloc.dealloc_raw(ptr, layout);
                })),
                "realloc" => std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                    let _ = alloc.realloc_raw(ptr, layout, layout.size() * 4);
                })),
                _ => unreachable!(),
            };
            let payload = match rejection {
                Err(payload) => payload,
                Ok(()) => {
                    let marker: &[u8] = match action {
                        "dealloc" => b"UNIALLOC_RETAINED_CACHE_RAW_DEALLOC_RETURNED\n",
                        "realloc" => b"UNIALLOC_RETAINED_CACHE_RAW_REALLOC_RETURNED\n",
                        _ => unreachable!(),
                    };
                    let _ = std::io::Write::write_all(&mut std::io::stderr(), marker);
                    std::process::abort();
                }
            };
            let expected = payload
                .downcast_ref::<&str>()
                .is_some_and(|message| *message == "type-cache pointer already retained")
                || payload
                    .downcast_ref::<std::string::String>()
                    .is_some_and(|message| message == "type-cache pointer already retained");
            if !expected {
                let _ = std::io::Write::write_all(
                    &mut std::io::stderr(),
                    b"UNIALLOC_RETAINED_CACHE_RAW_UNEXPECTED_PANIC\n",
                );
                std::process::abort();
            }

            // The exact ownership guard fires before registry, cache-entry, or
            // payload mutation. An exact typed pop must then retire ownership
            // and return the original allocation for one terminal raw release.
            let retained_after_rejection = unsafe { inline_type_cache_entry_snapshot_for_test() };
            assert_eq!(retained_after_rejection.ptr, ptr);
            assert_eq!(
                retained_after_rejection.identity,
                TypeCacheIdentity::from_metadata(metadata)
            );
            assert!(global_type_cache_contains_ptr(ptr));
            assert_eq!(GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire), 1);
            for offset in 0..layout.size() {
                assert_eq!(unsafe { ptr.add(offset).read() }, sentinel);
            }

            let reused = unsafe { alloc.alloc_with_metadata(layout, metadata) };
            assert_eq!(reused, ptr);
            assert!(!global_type_cache_contains_ptr(reused));
            assert_eq!(
                global_address_lifecycle_snapshot(reused),
                GlobalAddressLifecycleSnapshot::Absent
            );
            assert_eq!(GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire), 0);
            assert!(unsafe { inline_type_cache_entry_snapshot_for_test() }.is_empty());
            for offset in 0..layout.size() {
                assert_eq!(unsafe { reused.add(offset).read() }, sentinel);
            }
            unsafe {
                alloc.dealloc_raw(reused, layout);
            }
            std::eprintln!("UNIALLOC_RETAINED_TYPE_CACHE_RAW_GUARD_OK:{}", action);
            return;
        }

        for action in ["dealloc", "realloc"] {
            let output = std::process::Command::new(
                std::env::current_exe().expect("current type-isolation test executable"),
            )
            .args(["--exact", TEST_NAME, "--nocapture", "--test-threads=1"])
            .env(CHILD_ENV, action)
            .env("RUST_BACKTRACE", "0")
            .output()
            .expect("spawn isolated retained-cache raw-reclaim regression");
            let stderr = std::string::String::from_utf8_lossy(&output.stderr);
            assert!(
                output.status.success(),
                "retained-cache raw {} child failed: {}",
                action,
                stderr
            );
            assert!(
                stderr.contains(&std::format!(
                    "UNIALLOC_RETAINED_TYPE_CACHE_RAW_GUARD_OK:{}",
                    action
                )),
                "retained-cache raw {} child omitted its completion marker: {}",
                action,
                stderr
            );
        }
    }

    #[test]
    fn foreign_thread_raw_reclaim_of_real_retained_entry_fails_stop() {
        const CHILD_ENV: &str = "UNIALLOC_FOREIGN_RETAINED_TYPE_CACHE_RAW_GUARD";
        const TEST_NAME: &str = concat!(
            "alloc_api::type_isolation::tests::",
            "foreign_thread_raw_reclaim_of_real_retained_entry_fails_stop"
        );

        if let Some(action) = std::env::var_os(CHILD_ENV) {
            let action = std::string::String::from(action.to_str().expect("ASCII child action"));
            let _guard = test_guard();
            let _cleanup = SemanticStateCleanup;
            unsafe {
                clear_type_cache_for_test();
                clear_delayed_free_for_test();
                clear_auto_allocation_records();
            }
            semantic_auto_metadata_disable();
            semantic_stats_recording_disable();
            semantic_type_stats_recording_disable();

            let alloc = RustAllocator::new();
            // Keep this regression on the original general inline tier; the
            // dedicated sub-24-byte tier has its own ownership tests.
            let layout =
                Layout::from_size_align(3 * size_of::<usize>(), align_of::<usize>()).unwrap();
            let metadata = AllocationMetadata::for_type(0xD0B1_EF06)
                .with_module(0xC0DE_D0B6)
                .with_callsite(0xA110_D0B6)
                .with_flags(FLAG_TYPE_ISOLATED);
            let sentinel = match action.as_str() {
                "dealloc" => 0xA6,
                "realloc" => 0x5B,
                other => panic!("unknown foreign raw reclaim action: {}", other),
            };

            let ptr = unsafe { alloc.alloc_with_metadata(layout, metadata) };
            assert!(!ptr.is_null());
            unsafe {
                ptr.write_bytes(sentinel, layout.size());
                alloc.dealloc_with_metadata(ptr, layout, metadata);
            }

            let retained = unsafe { inline_type_cache_entry_snapshot_for_test() };
            assert_eq!(retained.ptr, ptr);
            assert_eq!(
                retained.identity,
                TypeCacheIdentity::from_metadata(metadata)
            );
            assert!(global_type_cache_contains_ptr(ptr));
            assert_eq!(GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire), 1);

            let foreign_action = action.clone();
            let ptr_addr = ptr as usize;
            let foreign = thread::spawn(move || {
                let foreign_alloc = RustAllocator::new();
                let foreign_ptr = ptr_addr as *mut u8;
                let rejection = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                    match foreign_action.as_str() {
                        "dealloc" => foreign_alloc.dealloc_raw(foreign_ptr, layout),
                        "realloc" => {
                            let _ =
                                foreign_alloc.realloc_raw(foreign_ptr, layout, layout.size() * 4);
                        }
                        _ => unreachable!(),
                    }
                }));
                let payload = match rejection {
                    Err(payload) => payload,
                    Ok(()) => {
                        let _ = std::io::Write::write_all(
                            &mut std::io::stderr(),
                            b"UNIALLOC_FOREIGN_RETAINED_CACHE_RAW_RETURNED\n",
                        );
                        // A missing guard may already have reclaimed or moved
                        // the allocation. Abort the isolated child before the
                        // owner can inspect, pop, or release the stale entry.
                        std::process::abort();
                    }
                };
                let expected = payload
                    .downcast_ref::<&str>()
                    .is_some_and(|message| *message == "type-cache pointer already retained")
                    || payload
                        .downcast_ref::<std::string::String>()
                        .is_some_and(|message| message == "type-cache pointer already retained");
                if !expected {
                    let _ = std::io::Write::write_all(
                        &mut std::io::stderr(),
                        b"UNIALLOC_FOREIGN_RETAINED_CACHE_RAW_UNEXPECTED_PANIC\n",
                    );
                    std::process::abort();
                }
                if !global_type_cache_contains_ptr(foreign_ptr)
                    || GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire) != 1
                {
                    let _ = std::io::Write::write_all(
                        &mut std::io::stderr(),
                        b"UNIALLOC_FOREIGN_RETAINED_CACHE_OWNERSHIP_MUTATED\n",
                    );
                    std::process::abort();
                }
            });
            if foreign.join().is_err() {
                let _ = std::io::Write::write_all(
                    &mut std::io::stderr(),
                    b"UNIALLOC_FOREIGN_RETAINED_CACHE_THREAD_PANICKED\n",
                );
                std::process::abort();
            }

            // Only the owner thread can see and pop its thread-local retained
            // entry. Exact typed reuse must retire global ownership before the
            // allocation receives its single terminal raw release.
            let retained_after_rejection = unsafe { inline_type_cache_entry_snapshot_for_test() };
            assert_eq!(retained_after_rejection.ptr, ptr);
            assert_eq!(
                retained_after_rejection.identity,
                TypeCacheIdentity::from_metadata(metadata)
            );
            assert!(global_type_cache_contains_ptr(ptr));
            assert_eq!(GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire), 1);
            for offset in 0..layout.size() {
                assert_eq!(unsafe { ptr.add(offset).read() }, sentinel);
            }

            let reused = unsafe { alloc.alloc_with_metadata(layout, metadata) };
            assert_eq!(reused, ptr);
            assert!(!global_type_cache_contains_ptr(reused));
            assert_eq!(GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire), 0);
            assert!(unsafe { inline_type_cache_entry_snapshot_for_test() }.is_empty());
            for offset in 0..layout.size() {
                assert_eq!(unsafe { reused.add(offset).read() }, sentinel);
            }
            unsafe {
                alloc.dealloc_raw(reused, layout);
            }
            std::eprintln!(
                "UNIALLOC_FOREIGN_RETAINED_TYPE_CACHE_RAW_GUARD_OK:{}",
                action
            );
            return;
        }

        for action in ["dealloc", "realloc"] {
            let output = std::process::Command::new(
                std::env::current_exe().expect("current type-isolation test executable"),
            )
            .args(["--exact", TEST_NAME, "--nocapture", "--test-threads=1"])
            .env(CHILD_ENV, action)
            .env("RUST_BACKTRACE", "0")
            .output()
            .expect("spawn isolated foreign-thread raw-reclaim regression");
            let stderr = std::string::String::from_utf8_lossy(&output.stderr);
            assert!(
                output.status.success(),
                "foreign-thread raw {} child failed: {}",
                action,
                stderr
            );
            assert!(
                stderr.contains(&std::format!(
                    "UNIALLOC_FOREIGN_RETAINED_TYPE_CACHE_RAW_GUARD_OK:{}",
                    action
                )),
                "foreign-thread raw {} child omitted its completion marker: {}",
                action,
                stderr
            );
            assert!(
                !stderr.contains("UNIALLOC_FOREIGN_RETAINED_CACHE_RAW_RETURNED")
                    && !stderr.contains("UNIALLOC_FOREIGN_RETAINED_CACHE_RAW_UNEXPECTED_PANIC")
                    && !stderr.contains("UNIALLOC_FOREIGN_RETAINED_CACHE_OWNERSHIP_MUTATED")
                    && !stderr.contains("UNIALLOC_FOREIGN_RETAINED_CACHE_THREAD_PANICKED"),
                "foreign-thread raw {} bypassed the ownership guard: {}",
                action,
                stderr
            );
        }
    }

    #[cfg(feature = "stats")]
    #[test]
    fn type_cache_registry_pressure_bypasses_real_semantic_free() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();

        let alloc = RustAllocator::new();
        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let metadata = AllocationMetadata::for_type(0xD0B1_EF04)
            .with_module(0xC0DE_D0B4)
            .with_callsite(0xA110_D0B4)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_FORCE_INITIALIZE);
        assert!(type_cache_eligible(layout, metadata));
        assert!(!compiler_type_isolated_recovery_fast_path(metadata));
        let ptr = unsafe { alloc.alloc_with_metadata(layout, metadata) };
        assert!(!ptr.is_null());
        unsafe {
            ptr.write_bytes(0xA5, layout.size());
        }

        let target = global_type_cache_ownership_shard_and_slot(ptr);
        let mut colliders = Vec::with_capacity(GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT);
        let mut address = 8usize;
        while colliders.len() < GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT {
            let candidate = address as *mut u8;
            address = address.checked_add(8).unwrap();
            if candidate != ptr && global_type_cache_ownership_shard_and_slot(candidate) == target {
                colliders.push(candidate);
            }
        }
        for &candidate in &colliders {
            assert_eq!(
                register_global_type_cache_ownership(candidate),
                GlobalTypeCacheOwnershipRegistration::Inserted
            );
        }
        let saturated_count = GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire);
        assert_eq!(saturated_count, GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT);
        assert_eq!(
            register_global_type_cache_ownership(ptr),
            GlobalTypeCacheOwnershipRegistration::Full
        );
        assert_eq!(
            GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire),
            saturated_count
        );

        semantic_stats_reset();
        let rejected = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
            alloc.dealloc_with_metadata(ptr, layout, metadata);
        }));
        assert!(
            rejected.is_err(),
            "T-registry saturation must fail-stop before backend release"
        );
        let stats = semantic_stats_snapshot();
        assert_eq!(stats.typed_deallocations, 0);
        assert_eq!(stats.typed_cache_inserts, 0);
        assert_eq!(stats.typed_cache_hits, 0);
        assert_eq!(stats.typed_cache_bypasses, 1);
        let admission = type_cache_admission_stats_snapshot();
        assert_eq!(admission.ownership_registry_full_failstop.events, 1);
        assert_eq!(
            admission.ownership_registry_full_failstop.rounded_bytes,
            type_cache_retained_bytes_for_layout(layout)
        );
        assert_eq!(admission.terminal_events(), 0);
        assert!(!global_type_cache_contains_ptr(ptr));
        assert_eq!(
            GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire),
            saturated_count,
            "real semantic-free bypass must not disturb synthetic owners"
        );
        for &candidate in &colliders {
            assert!(global_type_cache_contains_ptr(candidate));
        }
        for offset in 0..layout.size() {
            assert_eq!(unsafe { ptr.add(offset).read() }, 0xA5);
        }

        for candidate in colliders {
            assert!(unregister_global_type_cache_ownership(candidate));
        }
        assert_eq!(GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire), 0);
        unsafe {
            alloc.dealloc_raw(ptr, layout);
        }
        semantic_stats_recording_disable();
    }

    #[test]
    fn typed_duplicate_free_metadata_segregated_local_does_not_publish_cache_aliases() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();

        let alloc = RustAllocator::new();
        let layout = Layout::from_size_align(4 * size_of::<usize>(), align_of::<usize>()).unwrap();
        let metadata = AllocationMetadata::for_type(0xD0B1_EF02)
            .with_module(0xC0DE_D0B2)
            .with_callsite(0xA110_D0B2)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_METADATA_SEGREGATED);
        let ptr = unsafe { alloc.alloc_with_no_recovery_metadata(layout, metadata) };
        assert!(!ptr.is_null());

        unsafe {
            alloc.dealloc_with_recovered_metadata(ptr, layout, metadata);
        }
        let duplicate_rejected =
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                alloc.dealloc_with_recovered_metadata(ptr, layout, metadata);
            }))
            .is_err();

        let first = unsafe { alloc.alloc_with_no_recovery_metadata(layout, metadata) };
        let second = unsafe { alloc.alloc_with_no_recovery_metadata(layout, metadata) };
        let allocations_succeeded = !first.is_null() && !second.is_null();
        let aliases = first == second;
        unsafe {
            dealloc_unique_test_pair(&alloc, layout, first, second);
            clear_type_cache_for_test();
            clear_auto_allocation_records();
        }

        assert!(
            allocations_succeeded,
            "duplicate-free probe allocations failed"
        );
        assert!(
            !aliases,
            "a local metadata-segregated duplicate free published the same address twice; duplicate_rejected={}",
            duplicate_rejected
        );
    }

    #[test]
    fn typed_duplicate_free_cross_thread_hinted_does_not_publish_tls_aliases() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();

        let alloc = RustAllocator::new();
        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let metadata = AllocationMetadata::for_type(0xD0B1_EF03)
            .with_module(0xC0DE_D0B3)
            .with_callsite(0xA110_D0B3)
            .with_flags(FLAG_TYPE_ISOLATED)
            .with_placement_hint(PLACEMENT_HINT_CROSS_THREAD_RECOVERY | 0x73);
        let ptr = unsafe { alloc.alloc_with_recovery_metadata(layout, metadata) };
        assert!(!ptr.is_null());
        let ptr_addr = ptr as usize;

        let (first_freed_tx, first_freed_rx) = std::sync::mpsc::channel();
        let (first_alloc_tx, first_alloc_rx) = std::sync::mpsc::channel();
        let first_worker = thread::spawn(move || {
            let alloc = RustAllocator::new();
            let ptr = ptr_addr as *mut u8;
            let dealloc_rejected =
                std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                    alloc.dealloc_with_metadata(ptr, layout, metadata);
                }))
                .is_err();
            first_freed_tx.send(()).unwrap();
            first_alloc_rx.recv().unwrap();
            let reused = unsafe { alloc.alloc_with_no_recovery_metadata(layout, metadata) };
            (dealloc_rejected, reused as usize)
        });
        first_freed_rx.recv().unwrap();

        let (second_freed_tx, second_freed_rx) = std::sync::mpsc::channel();
        let (second_alloc_tx, second_alloc_rx) = std::sync::mpsc::channel();
        let second_worker = thread::spawn(move || {
            let alloc = RustAllocator::new();
            let ptr = ptr_addr as *mut u8;
            let dealloc_rejected =
                std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                    alloc.dealloc_with_metadata(ptr, layout, metadata);
                }))
                .is_err();
            second_freed_tx.send(()).unwrap();
            second_alloc_rx.recv().unwrap();
            let reused = unsafe { alloc.alloc_with_no_recovery_metadata(layout, metadata) };
            (dealloc_rejected, reused as usize)
        });
        second_freed_rx.recv().unwrap();

        first_alloc_tx.send(()).unwrap();
        second_alloc_tx.send(()).unwrap();
        let (first_dealloc_rejected, first_addr) = first_worker.join().unwrap();
        let (second_dealloc_rejected, second_addr) = second_worker.join().unwrap();
        let first = first_addr as *mut u8;
        let second = second_addr as *mut u8;
        let allocations_succeeded = !first.is_null() && !second.is_null();
        let aliases = first == second;
        unsafe {
            dealloc_unique_test_pair(&alloc, layout, first, second);
            clear_type_cache_for_test();
            clear_auto_allocation_records();
        }

        assert!(
            !first_dealloc_rejected,
            "the first cross-thread owner release must remain valid"
        );
        assert!(
            allocations_succeeded,
            "cross-thread probe allocations failed"
        );
        assert!(
            !aliases,
            "two TLS caches published the same typed address; second_dealloc_rejected={}",
            second_dealloc_rejected
        );
    }

