    #[test]
    fn delayed_flush_segregated_cache_rejection_preserves_delayed_owner() {
        struct SegregatedRejectionFixtureGuard;

        impl SegregatedRejectionFixtureGuard {
            fn clear(&mut self) {
                unsafe {
                    INLINE_SEGREGATED_TYPE_CACHE_ENTRY = SegregatedTypeCacheEntry::empty();
                    INLINE_SEGREGATED_TYPE_CACHE_ENTRY_SECOND = SegregatedTypeCacheEntry::empty();
                    set_segregated_type_cache_bucket_retained_bytes(
                        SEGREGATED_TYPE_CACHE_DOMAIN_ORDINARY,
                        0,
                        false,
                    );
                }
            }
        }

        impl Drop for SegregatedRejectionFixtureGuard {
            fn drop(&mut self) {
                self.clear();
            }
        }

        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        let _depot_reject = TypeCacheDepotForceRejectGuard::new();
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();

        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let metadata = AllocationMetadata::for_type(0xD17A_5E61)
            .with_module(0xC0DE_5E61)
            .with_callsite(0xA110_5E61)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_METADATA_SEGREGATED | FLAG_DELAYED_FREE);
        let (retained_tx, retained_rx) = std::sync::mpsc::channel();
        let (release_tx, release_rx) = std::sync::mpsc::channel();
        let (released_tx, released_rx) = std::sync::mpsc::channel();
        let owner = thread::spawn(move || {
            let alloc = RustAllocator::new();
            let ptr = unsafe { alloc.alloc_with_metadata(layout, metadata) };
            assert!(!ptr.is_null());
            unsafe {
                ptr.write_bytes(0xA9, layout.size());
                alloc.dealloc_with_metadata(ptr, layout, metadata);
            }
            assert!(global_delayed_free_contains_ptr(ptr));
            assert!(!global_type_cache_contains_ptr(ptr));

            let mut fixture_guard = SegregatedRejectionFixtureGuard;
            unsafe {
                // Fill the two inline positions with structurally valid,
                // distinct synthetic fixture keys, then make the bucket
                // aggregate budget reject growth.  The fixture pointers are
                // registry-free keys only: they are never dereferenced or
                // released and are removed before the post-release snapshot.
                let first_fixture_metadata = AllocationMetadata::for_type(0xF17E_5E61)
                    .with_flags(FLAG_TYPE_ISOLATED | FLAG_METADATA_SEGREGATED);
                let second_fixture_metadata = AllocationMetadata::for_type(0xF17E_5E62)
                    .with_flags(FLAG_TYPE_ISOLATED | FLAG_METADATA_SEGREGATED);
                INLINE_SEGREGATED_TYPE_CACHE_ENTRY = SegregatedTypeCacheEntry::new(
                    type_cache_identity_key(first_fixture_metadata),
                    segregated_type_cache_policy_key(first_fixture_metadata),
                    0x5100_0000usize as *mut u8,
                    layout,
                    first_fixture_metadata,
                );
                INLINE_SEGREGATED_TYPE_CACHE_ENTRY_SECOND = SegregatedTypeCacheEntry::new(
                    type_cache_identity_key(second_fixture_metadata),
                    segregated_type_cache_policy_key(second_fixture_metadata),
                    0x5200_0000usize as *mut u8,
                    layout,
                    second_fixture_metadata,
                );
                set_segregated_type_cache_bucket_retained_bytes(
                    SEGREGATED_TYPE_CACHE_DOMAIN_ORDINARY,
                    MAX_SEGREGATED_TYPE_CACHE_RETAINED_BYTES,
                    true,
                );
            }
            retained_tx.send(ptr as usize).unwrap();
            release_rx.recv().unwrap();

            unsafe {
                release_delayed_free_for_test(&alloc);
            }
            fixture_guard.clear();
            let side_cache = metadata_segregation_side_cache_snapshot();
            assert_eq!(side_cache.occupied_entries, 0);
            assert_eq!(side_cache.corrupt_buckets, 0);
            assert!(!global_delayed_free_contains_ptr(ptr));
            assert!(!global_type_cache_contains_ptr(ptr));

            // A duplicate backend release can publish the same free-list node
            // twice.  Two immediate raw allocations on the releasing thread
            // must therefore remain distinct and independently writable.
            let first = unsafe { alloc.alloc_raw(layout) };
            let second = unsafe { alloc.alloc_raw(layout) };
            assert!(!first.is_null() && !second.is_null());
            assert_ne!(
                first, second,
                "terminal raw release published a duplicate free-list node"
            );
            unsafe {
                first.write_bytes(0x51, layout.size());
                second.write_bytes(0xA2, layout.size());
                for offset in 0..layout.size() {
                    assert_eq!(first.add(offset).read(), 0x51);
                    assert_eq!(second.add(offset).read(), 0xA2);
                }
                dealloc_unique_test_pair(&alloc, layout, first, second);
            }
            released_tx.send(()).unwrap();
        });

        let ptr = retained_rx
            .recv_timeout(std::time::Duration::from_secs(10))
            .expect("owner should publish delayed metadata-segregated pointer")
            as *mut u8;
        assert!(global_delayed_free_contains_ptr(ptr));
        assert!(!global_type_cache_contains_ptr(ptr));
        let phase = &TEST_DELAYED_TERMINAL_RELEASE_PHASE;
        let phase_guard = TerminalReleasePhaseGuard::arm(phase);
        release_tx.send(()).unwrap();

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while phase.load(Ordering::Acquire) != 2 {
            if std::time::Instant::now() >= deadline {
                phase_guard.release_owner();
                let _ = released_rx
                    .recv_timeout(std::time::Duration::from_secs(10))
                    .unwrap_or_else(|_| std::process::abort());
                owner
                    .join()
                    .expect("timed-out delayed segregated-rejection owner");
                phase_guard.reset();
                panic!("delayed segregated rejection did not reach the raw-release boundary");
            }
            thread::yield_now();
        }

        assert!(
            global_delayed_free_contains_ptr(ptr),
            "delayed ownership must remain published across the sole backend release"
        );
        assert!(
            !global_type_cache_contains_ptr(ptr),
            "rejected segregated insertion must roll back temporary type-cache ownership"
        );
        assert_eq!(
            GLOBAL_DELAYED_FREE_OWNERSHIP_COUNT.load(Ordering::Acquire),
            1
        );
        assert_eq!(GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire), 0);
        for offset in 0..layout.size() {
            assert_eq!(unsafe { ptr.add(offset).read() }, 0xA9);
        }
        let duplicate_rejected = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            reject_known_retained_or_released_pointer(ptr);
        }))
        .is_err();
        assert!(
            duplicate_rejected,
            "a foreign reclaimer must not race the delayed owner's backend release"
        );

        phase_guard.release_owner();
        released_rx
            .recv_timeout(std::time::Duration::from_secs(10))
            .expect("owner should complete delayed segregated-rejection release");
        owner.join().expect("delayed segregated-rejection owner");
        phase_guard.reset();

        assert!(!global_delayed_free_contains_ptr(ptr));
        assert!(!global_type_cache_contains_ptr(ptr));
        assert_eq!(
            GLOBAL_DELAYED_FREE_OWNERSHIP_COUNT.load(Ordering::Acquire),
            0
        );
        assert_eq!(GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire), 0);
    }

    #[test]
    fn delayed_to_type_handoff_rejects_forced_reclaim_entrypoint_race() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();

        let alloc = RustAllocator::new();
        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let delayed_metadata = AllocationMetadata::for_type(0xD17A_D0B7)
            .with_module(0xC0DE_D0B7)
            .with_callsite(0xA110_D0B7)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_DELAYED_FREE);
        let immediate_metadata = delayed_metadata.with_flags(FLAG_TYPE_ISOLATED);
        let mutating_bypass_metadata = delayed_metadata.with_flags(FLAG_FORCE_INITIALIZE);

        for (action, sentinel) in [
            ("raw", 0xA7),
            ("trait", 0x5C),
            ("semantic", 0xE4),
            ("resolved", 0xD3),
        ] {
            let ptr = unsafe { alloc.alloc_with_metadata(layout, delayed_metadata) };
            assert!(!ptr.is_null());
            unsafe {
                ptr.write_bytes(sentinel, layout.size());
                alloc.dealloc_with_metadata(ptr, layout, delayed_metadata);
            }
            assert!(global_delayed_free_contains_ptr(ptr));
            assert!(!global_type_cache_contains_ptr(ptr));

            let phase_guard = DelayedToTypeReclaimPhaseGuard::arm();
            let ptr_addr = ptr as usize;
            let (outcome_tx, outcome_rx) = std::sync::mpsc::channel();
            let worker = thread::spawn(move || {
                let foreign_alloc = RustAllocator::new();
                let foreign_ptr = ptr_addr as *mut u8;
                let rejection = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                    match action {
                        "raw" => foreign_alloc.dealloc_raw(foreign_ptr, layout),
                        "trait" => <RustAllocator as GlobalAlloc>::dealloc(
                            &foreign_alloc,
                            foreign_ptr,
                            layout,
                        ),
                        "resolved" => foreign_alloc.dealloc_with_resolved_metadata(
                            foreign_ptr,
                            layout,
                            mutating_bypass_metadata,
                            false,
                        ),
                        "semantic" => <RustAllocator as SemanticAlloc>::dealloc_with_metadata(
                            &foreign_alloc,
                            foreign_ptr,
                            layout,
                            immediate_metadata,
                        ),
                        _ => unreachable!(),
                    }
                }));
                let outcome = match rejection {
                    Ok(()) => 0,
                    Err(payload) => {
                        let message = payload
                            .downcast_ref::<&str>()
                            .copied()
                            .or_else(|| {
                                payload
                                    .downcast_ref::<std::string::String>()
                                    .map(|message| message.as_str())
                            })
                            .unwrap_or("unexpected non-string panic");
                        match message {
                            "delayed-free pointer already quarantined" => 1,
                            "type-cache pointer already retained" => 2,
                            "test ownership guard missed delayed-to-type handoff" => 3,
                            _ => 4,
                        }
                    }
                };
                outcome_tx.send(outcome).unwrap();
            });

            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
            let mut forced_handoff = false;
            let mut early_outcome = None;
            loop {
                if TEST_DELAYED_TO_TYPE_RECLAIM_PHASE.load(Ordering::Acquire) == 2 {
                    unsafe {
                        release_delayed_free_for_test(&alloc);
                    }
                    phase_guard.release_worker();
                    forced_handoff = true;
                    break;
                }
                match outcome_rx.try_recv() {
                    Ok(outcome) => {
                        early_outcome = Some(outcome);
                        break;
                    }
                    Err(std::sync::mpsc::TryRecvError::Empty) => {}
                    Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                        // A disconnected sender means the worker has already
                        // terminated and cannot consume a synthetic resume.
                        phase_guard.reset();
                        unsafe {
                            clear_delayed_free_for_test();
                            clear_type_cache_for_test();
                        }
                        panic!("foreign reclaim worker disconnected")
                    }
                }
                if std::time::Instant::now() >= deadline {
                    phase_guard.release_worker();
                    let _ = outcome_rx
                        .recv_timeout(std::time::Duration::from_secs(10))
                        .unwrap_or_else(|_| std::process::abort());
                    worker.join().expect("timed-out foreign reclaim worker");
                    phase_guard.reset();
                    unsafe {
                        clear_delayed_free_for_test();
                        clear_type_cache_for_test();
                    }
                    panic!("foreign reclaim did not reach an ownership decision");
                }
                thread::yield_now();
            }

            let outcome = match early_outcome {
                Some(outcome) => outcome,
                None => match outcome_rx.recv_timeout(std::time::Duration::from_secs(10)) {
                    Ok(outcome) => outcome,
                    Err(_) => {
                        phase_guard.release_worker();
                        let _ = outcome_rx
                            .recv_timeout(std::time::Duration::from_secs(10))
                            .unwrap_or_else(|_| std::process::abort());
                        worker.join().expect("released foreign reclaim worker");
                        phase_guard.reset();
                        unsafe {
                            clear_delayed_free_for_test();
                            clear_type_cache_for_test();
                        }
                        panic!("foreign reclaim did not finish after ownership handoff");
                    }
                },
            };
            worker.join().expect("foreign reclaim worker");
            phase_guard.reset();

            if outcome != 1 {
                // A returned or unexpectedly panicking reclaim may already
                // have released or moved the allocation. Retire only the
                // test registries/TLS slots and deliberately leak the backing
                // storage on this failing path; never inspect or free a
                // potentially stale pointer.
                unsafe {
                    clear_delayed_free_for_test();
                    clear_type_cache_for_test();
                }
                panic!(
                    "{} reclaim produced ownership outcome {}; expected delayed-free fail-stop",
                    action, outcome
                );
            }

            if !forced_handoff {
                unsafe {
                    release_delayed_free_for_test(&alloc);
                }
            }
            assert!(!global_delayed_free_contains_ptr(ptr));
            assert!(global_type_cache_contains_ptr(ptr));
            let released = unsafe {
                pop_semantic_type_cache(layout, immediate_metadata)
                    .expect("owner must retain the handed-off quarantine entry")
            };
            assert_eq!(released, ptr);
            assert!(!global_type_cache_contains_ptr(ptr));
            for offset in 0..layout.size() {
                assert_eq!(unsafe { released.add(offset).read() }, sentinel);
            }
            unsafe {
                alloc.dealloc_raw(released, layout);
            }
        }
    }

    #[test]
    fn cross_thread_delayed_free_rejects_raw_and_semantic_reallocation_entry_points() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();

        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let metadata = [
            AllocationMetadata::for_type(0xD17A_D0C0)
                .with_module(0xC0DE_D0C0)
                .with_callsite(0xA110_D0C0)
                .with_flags(FLAG_TYPE_ISOLATED | FLAG_DELAYED_FREE),
            AllocationMetadata::for_type(0xD17A_D0C1)
                .with_module(0xC0DE_D0C1)
                .with_callsite(0xA110_D0C1)
                .with_flags(FLAG_TYPE_ISOLATED | FLAG_DELAYED_FREE),
            AllocationMetadata::for_type(0xD17A_D0C2)
                .with_module(0xC0DE_D0C2)
                .with_callsite(0xA110_D0C2)
                .with_flags(FLAG_TYPE_ISOLATED | FLAG_DELAYED_FREE),
        ];
        let alloc = RustAllocator::new();
        let ptrs = metadata.map(|entry| unsafe {
            let ptr = alloc.alloc_with_recovery_metadata(layout, entry);
            assert!(!ptr.is_null());
            ptr
        });
        let ptr_addrs = ptrs.map(|ptr| ptr as usize);

        let (quarantined_tx, quarantined_rx) = std::sync::mpsc::channel();
        let (cleanup_tx, cleanup_rx) = std::sync::mpsc::channel();
        let owner = thread::spawn(move || {
            let alloc = RustAllocator::new();
            for idx in 0..ptr_addrs.len() {
                unsafe {
                    alloc.dealloc_with_metadata(ptr_addrs[idx] as *mut u8, layout, metadata[idx]);
                }
            }
            assert_eq!(delayed_free_snapshot().occupied_slots, ptr_addrs.len());
            quarantined_tx.send(()).unwrap();
            cleanup_rx.recv().unwrap();

            unsafe {
                release_delayed_free_for_test(&alloc);
                for idx in 0..ptr_addrs.len() {
                    let immediate_metadata = metadata[idx].with_flags(FLAG_TYPE_ISOLATED);
                    let released = pop_semantic_type_cache(layout, immediate_metadata)
                        .expect("owner cleanup should recover each released quarantine entry");
                    assert_eq!(released, ptr_addrs[idx] as *mut u8);
                    alloc.dealloc_raw(released, layout);
                }
            }
        });
        quarantined_rx.recv().unwrap();

        let global_dealloc_rejected =
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                <RustAllocator as GlobalAlloc>::dealloc(&alloc, ptrs[0], layout);
            }))
            .is_err();
        let global_realloc_rejected =
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                <RustAllocator as GlobalAlloc>::realloc(&alloc, ptrs[1], layout, layout.size());
            }))
            .is_err();
        let semantic_realloc_rejected =
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
                <RustAllocator as SemanticAlloc>::realloc_with_split_metadata(
                    &alloc,
                    ptrs[2],
                    layout,
                    layout.size(),
                    metadata[2].with_flags(FLAG_TYPE_ISOLATED),
                    metadata[2].with_flags(FLAG_TYPE_ISOLATED),
                );
            }))
            .is_err();

        assert!(
            global_dealloc_rejected,
            "GlobalAlloc::dealloc must fail-stop"
        );
        assert!(
            global_realloc_rejected,
            "GlobalAlloc::realloc must fail-stop"
        );
        assert!(
            semantic_realloc_rejected,
            "SemanticAlloc::realloc_with_split_metadata must fail-stop before in-place reuse"
        );
        for ptr in ptrs {
            assert!(global_delayed_free_contains_ptr(ptr));
        }

        cleanup_tx.send(()).unwrap();
        owner.join().expect("quarantine owner cleanup");
    }

    #[test]
    fn pending_cross_thread_quarantine_ownership_blocks_foreign_dealloc_before_tls_publish() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();

        let alloc = RustAllocator::new();
        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let delayed_metadata = AllocationMetadata::for_type(0xD17A_D0B4)
            .with_module(0xC0DE_D0B4)
            .with_callsite(0xA110_D0B4)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_DELAYED_FREE);
        let immediate_metadata = delayed_metadata.with_flags(FLAG_TYPE_ISOLATED);
        let ptr = unsafe { alloc.alloc_raw(layout) };
        assert!(!ptr.is_null());

        let ptr_addr = ptr as usize;
        let (registered_tx, registered_rx) = std::sync::mpsc::channel();
        let (release_tx, release_rx) = std::sync::mpsc::channel();
        let pending_owner = thread::spawn(move || {
            let ptr = ptr_addr as *mut u8;
            let pending = begin_global_delayed_free_ownership(ptr, layout, delayed_metadata)
                .expect("test pointer should acquire bounded quarantine ownership");
            registered_tx.send(()).unwrap();
            release_rx.recv().unwrap();
            drop(pending);
        });
        registered_rx.recv().unwrap();

        let rejected = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
            alloc.dealloc_with_resolved_metadata(ptr, layout, immediate_metadata, false);
        }));
        assert!(
            rejected.is_err(),
            "foreign deallocation must observe pending ownership before TLS publication"
        );
        assert!(global_delayed_free_contains_ptr(ptr));

        release_tx.send(()).unwrap();
        pending_owner.join().expect("pending quarantine owner");
        assert!(
            !global_delayed_free_contains_ptr(ptr),
            "uncommitted pending ownership must unregister on guard drop"
        );
        unsafe {
            alloc.dealloc_raw(ptr, layout);
        }
    }

    #[test]
    fn delayed_free_registry_pressure_falls_back_to_immediate_release() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();

        let alloc = RustAllocator::new();
        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let delayed_metadata = AllocationMetadata::for_type(0xD17A_D0B5)
            .with_module(0xC0DE_D0B5)
            .with_callsite(0xA110_D0B5)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_DELAYED_FREE);
        let immediate_metadata = delayed_metadata.with_flags(FLAG_TYPE_ISOLATED);
        let ptr = unsafe { alloc.alloc_with_metadata(layout, delayed_metadata) };
        assert!(!ptr.is_null());

        let baseline_registrations = GLOBAL_DELAYED_FREE_OWNERSHIP_COUNT.load(Ordering::Acquire);
        let target_shard = global_delayed_free_ownership_shard(ptr);
        let mut owners: [Option<PendingGlobalDelayedFreeOwnership>;
            GLOBAL_DELAYED_FREE_OWNERSHIP_SHARD_SLOTS] = core::array::from_fn(|_| None);
        let mut candidate = 8usize;
        let mut inserted = 0usize;
        let mut observed_full = false;
        while inserted < owners.len() && !observed_full {
            let fake_ptr = candidate as *mut u8;
            candidate = candidate.wrapping_add(8);
            if fake_ptr == ptr
                || global_delayed_free_ownership_shard(fake_ptr) != target_shard
                || global_delayed_free_contains_ptr(fake_ptr)
            {
                continue;
            }
            match register_global_delayed_free_ownership(fake_ptr) {
                GlobalDelayedFreeRegistration::Inserted => {
                    owners[inserted] = Some(PendingGlobalDelayedFreeOwnership::new(fake_ptr));
                    inserted += 1;
                }
                GlobalDelayedFreeRegistration::Duplicate => {}
                GlobalDelayedFreeRegistration::Full => observed_full = true,
            }
        }
        assert!(
            observed_full || inserted == owners.len(),
            "the test must saturate the target ownership shard before deallocation"
        );

        unsafe {
            alloc.dealloc_with_metadata(ptr, layout, delayed_metadata);
        }
        assert_eq!(
            delayed_free_snapshot().occupied_slots,
            0,
            "registry pressure must not create quarantine ownership invisible to other threads"
        );
        let reused = unsafe { alloc.alloc_with_metadata(layout, immediate_metadata) };
        assert_eq!(
            reused, ptr,
            "bounded-registry fallback should release through the ordinary type cache"
        );
        unsafe {
            alloc.dealloc_raw(reused, layout);
        }

        drop(owners);
        assert_eq!(
            GLOBAL_DELAYED_FREE_OWNERSHIP_COUNT.load(Ordering::Acquire),
            baseline_registrations,
            "dropping pending ownership guards must restore the pre-test registry count"
        );
    }

    #[test]
    fn delayed_and_type_cache_registry_pressure_fails_stop_without_release() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();

        let alloc = RustAllocator::new();
        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let metadata = AllocationMetadata::for_type(0xD17A_D0C5)
            .with_module(0xC0DE_D0C5)
            .with_callsite(0xA110_D0C5)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_DELAYED_FREE);
        let ptr = unsafe { alloc.alloc_raw(layout) };
        assert!(!ptr.is_null());
        unsafe {
            ptr.write_bytes(0xC5, layout.size());
        }

        let delayed_target = global_delayed_free_ownership_shard(ptr);
        let mut delayed_owners: [Option<PendingGlobalDelayedFreeOwnership>;
            GLOBAL_DELAYED_FREE_OWNERSHIP_SHARD_SLOTS] = core::array::from_fn(|_| None);
        let mut address = 8usize;
        let mut delayed_inserted = 0usize;
        while delayed_inserted < delayed_owners.len() {
            let candidate = address as *mut u8;
            address = address.wrapping_add(8);
            if candidate == ptr || global_delayed_free_ownership_shard(candidate) != delayed_target
            {
                continue;
            }
            if register_global_delayed_free_ownership(candidate)
                == GlobalDelayedFreeRegistration::Inserted
            {
                delayed_owners[delayed_inserted] =
                    Some(PendingGlobalDelayedFreeOwnership::new(candidate));
                delayed_inserted += 1;
            }
        }

        let type_target = global_type_cache_ownership_shard_and_slot(ptr);
        let mut type_owners = Vec::with_capacity(GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT);
        let mut type_full = false;
        address = 8;
        while type_owners.len() < GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT && !type_full {
            let candidate = address as *mut u8;
            address = address.wrapping_add(8);
            if candidate != ptr
                && global_type_cache_ownership_shard_and_slot(candidate) == type_target
            {
                match register_global_type_cache_ownership(candidate) {
                    GlobalTypeCacheOwnershipRegistration::Inserted => type_owners.push(candidate),
                    GlobalTypeCacheOwnershipRegistration::Full => type_full = true,
                    GlobalTypeCacheOwnershipRegistration::Duplicate => {}
                }
            }
        }
        assert!(
            type_full || type_owners.len() == GLOBAL_TYPE_CACHE_OWNERSHIP_PROBE_LIMIT,
            "the unified lifecycle probe window must be saturated"
        );

        let rejected = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| unsafe {
            alloc.dealloc_with_recovered_metadata(ptr, layout, metadata);
        }));
        assert!(
            rejected.is_err(),
            "simultaneous D/T registry saturation must fail-stop"
        );
        assert!(!global_delayed_free_contains_ptr(ptr));
        assert!(!global_type_cache_contains_ptr(ptr));
        for offset in 0..layout.size() {
            assert_eq!(unsafe { ptr.add(offset).read() }, 0xC5);
        }

        for candidate in type_owners {
            assert!(unregister_global_type_cache_ownership(candidate));
        }
        drop(delayed_owners);
        unsafe {
            alloc.dealloc_raw(ptr, layout);
        }
    }

    #[test]
    fn pending_delayed_free_ownership_remains_published_during_unwind() {
        let _guard = test_guard();
        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let metadata = AllocationMetadata::for_type(0xD17A_D0B6)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_DELAYED_FREE);
        let baseline_registrations = GLOBAL_DELAYED_FREE_OWNERSHIP_COUNT.load(Ordering::Acquire);
        let mut fake_addr = 0xD0B6_0008usize;
        while global_delayed_free_contains_ptr(fake_addr as *mut u8) {
            fake_addr = fake_addr.wrapping_add(8);
        }
        let fake_ptr = fake_addr as *mut u8;

        let unwound = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _pending = begin_global_delayed_free_ownership(fake_ptr, layout, metadata)
                .expect("test pointer should acquire pending ownership");
            assert!(global_delayed_free_contains_ptr(fake_ptr));
            panic!("exercise pending ownership unwind");
        }));
        assert!(unwound.is_err());
        assert!(
            global_delayed_free_contains_ptr(fake_ptr),
            "unknown unwind must conservatively retain pending ownership"
        );
        assert!(unregister_global_delayed_free_ownership(fake_ptr));
        assert_eq!(
            GLOBAL_DELAYED_FREE_OWNERSHIP_COUNT.load(Ordering::Acquire),
            baseline_registrations
        );
    }

