    #[test]
    fn semantic_type_cache_inline_rejects_forced_identity_key_collision() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            let mut storage = [0usize; TYPE_CACHE_NODE_WORDS];
            let layout =
                Layout::from_size_align(size_of_val(&storage), align_of::<usize>()).unwrap();
            let module_a = AllocationMetadata::for_type(0xC003_004A)
                .with_module(0xC0DE_A)
                .with_flags(FLAG_TYPE_ISOLATED);
            let module_b = AllocationMetadata::for_type(module_a.type_id)
                .with_module(0xC0DE_B)
                .with_flags(module_a.flags);
            let ptr = storage.as_mut_ptr() as *mut u8;
            let forced_collision_key = 0xC011_1510_C011_1510;

            assert!(push_inline_type_cache_eligible_with_key(
                ptr,
                layout,
                module_a,
                forced_collision_key,
            ));
            assert_eq!(
                pop_inline_type_cache_eligible_with_key(layout, module_b, forced_collision_key,),
                None,
                "a cache-key collision must not bypass the exact module/context boundary",
            );
            assert_eq!(
                pop_inline_type_cache_eligible_with_key(layout, module_a, forced_collision_key,),
                Some(ptr),
                "rejecting the colliding identity must preserve the entry for its exact owner",
            );
        }
    }

    #[test]
    fn type_cache_linked_rejects_forced_identity_key_collision() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            let mut storage_a = [0usize; TYPE_CACHE_NODE_WORDS];
            let mut storage_b = [0usize; TYPE_CACHE_NODE_WORDS];
            let layout =
                Layout::from_size_align(size_of_val(&storage_a), align_of::<usize>()).unwrap();
            let module_a = AllocationMetadata::for_type(0xC003_004B)
                .with_module(0xC0DE_A)
                .with_flags(FLAG_TYPE_ISOLATED)
                .with_lifetime_hint(0x11)
                .with_placement_hint(0x21);
            let module_b = AllocationMetadata::for_type(module_a.type_id)
                .with_module(0xC0DE_B)
                .with_flags(module_a.flags)
                .with_lifetime_hint(0x12)
                .with_placement_hint(0x22);
            let ptr_a = storage_a.as_mut_ptr() as *mut u8;
            let ptr_b = storage_b.as_mut_ptr() as *mut u8;
            let forced_collision_key = 0xC011_1510_C011_1511;

            assert!(push_type_cache_with_key(
                ptr_a,
                layout,
                module_a,
                forced_collision_key,
            ));
            assert_eq!(
                pop_type_cache_with_key(layout, module_b, forced_collision_key),
                None,
                "a linked-cache key collision must not bypass exact module/hint boundaries",
            );
            assert!(push_type_cache_with_key(
                ptr_b,
                layout,
                module_b,
                forced_collision_key,
            ));
            assert_eq!(
                pop_type_cache_with_key(layout, module_b, forced_collision_key),
                Some(ptr_b),
                "colliding identities must occupy separate bounded-probe slots",
            );
            assert_eq!(
                pop_type_cache_with_key(layout, module_a, forced_collision_key),
                Some(ptr_a),
                "rejecting the colliding identity must preserve the linked entry for its exact owner",
            );
        }
    }

    #[test]
    fn type_cache_linked_probe_exhaustion_preserves_exact_owners_and_accounting() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            const REJECTED_COLLISIONS: usize = 8;
            const COLLISION_COUNT: usize = TYPE_CACHE_PROBE_LIMIT + REJECTED_COLLISIONS;

            let mut storage = [[0usize; TYPE_CACHE_NODE_WORDS]; COLLISION_COUNT];
            let layout =
                Layout::from_size_align(size_of_val(&storage[0]), align_of::<usize>()).unwrap();
            let forced_collision_key = 0xC011_1510_C011_1512;
            let mut metadata = [AllocationMetadata::unknown(); COLLISION_COUNT];
            let mut idx = 0usize;
            while idx < COLLISION_COUNT {
                metadata[idx] = AllocationMetadata::for_type(0xC003_004C)
                    .with_module(0xC0DE_1000 + idx as u64)
                    .with_flags(FLAG_TYPE_ISOLATED)
                    .with_lifetime_hint(0x30 + idx as u16)
                    .with_placement_hint(0x40 + idx as u16);
                idx += 1;
            }

            idx = 0;
            while idx < TYPE_CACHE_PROBE_LIMIT {
                assert!(
                    push_type_cache_with_key(
                        storage[idx].as_mut_ptr() as *mut u8,
                        layout,
                        metadata[idx],
                        forced_collision_key,
                    ),
                    "each exact identity should occupy one slot in the bounded collision window",
                );
                idx += 1;
            }

            let retained_per_entry = type_cache_retained_bytes_for_layout(layout);
            let before_storm = type_cache_snapshot_for_test();
            let before_snapshot = type_isolation_side_cache_snapshot();
            assert!(!before_snapshot.inline_occupied);
            assert_eq!(before_snapshot.occupied_slots, TYPE_CACHE_PROBE_LIMIT);
            assert_eq!(before_snapshot.occupied_entries, TYPE_CACHE_PROBE_LIMIT);
            assert_eq!(
                before_snapshot.retained_bytes,
                retained_per_entry * TYPE_CACHE_PROBE_LIMIT,
            );
            assert_eq!(
                plain_type_cache_retained_bytes_snapshot_for_test(),
                before_snapshot.retained_bytes,
            );
            assert!(plain_type_cache_retained_bytes_trusted_for_test());

            while idx < COLLISION_COUNT {
                assert!(
                    !push_type_cache_with_key(
                        storage[idx].as_mut_ptr() as *mut u8,
                        layout,
                        metadata[idx],
                        forced_collision_key,
                    ),
                    "a full bounded probe window must fail closed instead of replacing another identity",
                );
                assert_eq!(
                    pop_type_cache_with_key(layout, metadata[idx], forced_collision_key),
                    None,
                    "a rejected colliding identity must not consume a retained foreign pointer",
                );
                assert!(
                    storage[idx].iter().all(|word| *word == 0),
                    "a failed cache insertion must not write an in-object list header",
                );
                idx += 1;
            }

            let after_storm = type_cache_snapshot_for_test();
            idx = 0;
            while idx < TYPE_CACHE_SLOTS {
                assert_eq!(after_storm[idx].cache_key, before_storm[idx].cache_key);
                assert_eq!(after_storm[idx].identity, before_storm[idx].identity);
                assert_eq!(after_storm[idx].head, before_storm[idx].head);
                assert_eq!(after_storm[idx].count, before_storm[idx].count);
                assert_eq!(
                    after_storm[idx].retained_bytes,
                    before_storm[idx].retained_bytes,
                );
                idx += 1;
            }
            let after_storm_snapshot = type_isolation_side_cache_snapshot();
            assert_eq!(
                after_storm_snapshot.inline_occupied,
                before_snapshot.inline_occupied,
            );
            assert_eq!(
                after_storm_snapshot.occupied_slots,
                before_snapshot.occupied_slots,
            );
            assert_eq!(
                after_storm_snapshot.occupied_entries,
                before_snapshot.occupied_entries,
            );
            assert_eq!(
                after_storm_snapshot.retained_bytes,
                before_snapshot.retained_bytes,
            );
            assert_eq!(
                after_storm_snapshot.corrupt_slots,
                before_snapshot.corrupt_slots,
            );
            assert!(
                !after_storm_snapshot.hot_slot_active,
                "a colliding identity miss should invalidate the non-authoritative hot hint",
            );
            assert_eq!(
                plain_type_cache_retained_bytes_snapshot_for_test(),
                before_snapshot.retained_bytes,
            );
            assert!(plain_type_cache_retained_bytes_trusted_for_test());

            idx = 0;
            while idx < TYPE_CACHE_PROBE_LIMIT {
                let expected = storage[idx].as_mut_ptr() as *mut u8;
                assert_eq!(
                    pop_type_cache_with_key(layout, metadata[idx], forced_collision_key),
                    Some(expected),
                    "each retained pointer must remain recoverable only by its exact identity",
                );
                let remaining = TYPE_CACHE_PROBE_LIMIT - idx - 1;
                let snapshot = type_isolation_side_cache_snapshot();
                assert_eq!(snapshot.occupied_slots, remaining);
                assert_eq!(snapshot.occupied_entries, remaining);
                assert_eq!(snapshot.retained_bytes, retained_per_entry * remaining);
                assert_eq!(
                    plain_type_cache_retained_bytes_snapshot_for_test(),
                    snapshot.retained_bytes,
                );
                assert!(plain_type_cache_retained_bytes_trusted_for_test());
                idx += 1;
            }
        }
    }

    #[test]
    fn semantic_allocator_does_not_reuse_cached_object_across_type_ids() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();

        let alloc = RustAllocator::new();
        let layout =
            Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
        let metadata_a = AllocationMetadata::for_type(0xC003_A11C)
            .with_module(0xC0DE)
            .with_flags(FLAG_TYPE_ISOLATED);
        let metadata_b = AllocationMetadata::for_type(0xC003_B11C)
            .with_module(metadata_a.module_id)
            .with_flags(metadata_a.flags);

        let ptr_a = unsafe { alloc.alloc_with_metadata(layout, metadata_a) };
        assert!(!ptr_a.is_null());
        unsafe {
            alloc.dealloc_with_metadata(ptr_a, layout, metadata_a);
        }

        let ptr_b = unsafe { alloc.alloc_with_metadata(layout, metadata_b) };
        assert!(!ptr_b.is_null());
        assert_ne!(
            ptr_b, ptr_a,
            "a different compiler object type must not consume a cached object from type A"
        );

        let ptr_a_reused = unsafe { alloc.alloc_with_metadata(layout, metadata_a) };
        assert_eq!(
            ptr_a_reused, ptr_a,
            "the cached object should remain available to the original compiler object type"
        );

        unsafe {
            alloc.dealloc_raw(ptr_b, layout);
            alloc.dealloc_raw(ptr_a_reused, layout);
            clear_type_cache_for_test();
            clear_auto_allocation_records();
        }
    }

