    #[cfg(not(feature = "quarantine"))]
    #[test]
    fn global_allocator_inactive_lifecycle_fast_paths_preserve_realloc_contract() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();
        let _tracking = LifecycleTrackingOverride::inactive();

        let alloc = RustAllocator::new();
        let layout = Layout::from_size_align(64, align_of::<usize>()).unwrap();
        let probes_before = TEST_GLOBAL_ADDRESS_LIFECYCLE_TABLE_PROBES.load(Ordering::Relaxed);
        let admissions_before = TEST_GLOBAL_RAW_RECLAIM_ADMISSION_ENTRIES.load(Ordering::Relaxed);

        let released = unsafe { GlobalAlloc::alloc(&alloc, layout) };
        assert!(!released.is_null());
        unsafe {
            GlobalAlloc::dealloc(&alloc, released, layout);
        }

        let ptr = unsafe { GlobalAlloc::alloc(&alloc, layout) };
        assert!(!ptr.is_null());
        unsafe {
            for offset in 0..layout.size() {
                ptr.add(offset).write((offset as u8).wrapping_mul(17));
            }
        }

        let same_class_size = 63;
        let same_class = unsafe { GlobalAlloc::realloc(&alloc, ptr, layout, same_class_size) };
        assert_eq!(same_class, ptr);
        unsafe {
            for offset in 0..same_class_size {
                assert_eq!(
                    same_class.add(offset).read(),
                    (offset as u8).wrapping_mul(17)
                );
            }
        }

        let same_class_layout = Layout::from_size_align(same_class_size, layout.align()).unwrap();
        let moved_size = 192;
        let moved =
            unsafe { GlobalAlloc::realloc(&alloc, same_class, same_class_layout, moved_size) };
        assert!(!moved.is_null());
        unsafe {
            for offset in 0..same_class_size {
                assert_eq!(moved.add(offset).read(), (offset as u8).wrapping_mul(17));
            }
        }
        let moved_layout = Layout::from_size_align(moved_size, layout.align()).unwrap();
        unsafe {
            GlobalAlloc::dealloc(&alloc, moved, moved_layout);
        }

        let zeroed = unsafe { GlobalAlloc::alloc(&alloc, layout) };
        assert!(!zeroed.is_null());
        let zero = unsafe { GlobalAlloc::realloc(&alloc, zeroed, layout, 0) };
        assert!(!zero.is_null());
        assert_eq!(zero as usize, layout.align());

        assert_eq!(
            TEST_GLOBAL_ADDRESS_LIFECYCLE_TABLE_PROBES.load(Ordering::Relaxed),
            probes_before,
            "inactive GlobalAlloc operations should not probe lifecycle tables"
        );
        assert_eq!(
            TEST_GLOBAL_RAW_RECLAIM_ADMISSION_ENTRIES.load(Ordering::Relaxed),
            admissions_before,
            "inactive GlobalAlloc operations should not enter lifecycle admission"
        );
    }

    #[cfg(all(feature = "stats", not(feature = "quarantine")))]
    #[test]
    fn stats_only_global_realloc_keeps_inactive_lifecycle_untracked() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_reset();
        let _tracking = LifecycleTrackingOverride::inactive();

        let alloc = RustAllocator::new();
        let layout = Layout::from_size_align(64, align_of::<usize>()).unwrap();
        let ptr = unsafe { GlobalAlloc::alloc(&alloc, layout) };
        assert!(!ptr.is_null());
        unsafe {
            for offset in 0..layout.size() {
                ptr.add(offset).write((offset as u8).wrapping_mul(19));
            }
        }

        let moved_size = 192;
        let moved = unsafe { GlobalAlloc::realloc(&alloc, ptr, layout, moved_size) };
        assert!(!moved.is_null());
        unsafe {
            for offset in 0..layout.size() {
                assert_eq!(moved.add(offset).read(), (offset as u8).wrapping_mul(19));
            }
        }
        assert!(semantic_stats_recording_enabled());
        assert!(semantic_stats_snapshot().total_allocations >= 2);
        assert!(
            !global_address_lifecycle_tracking_active(),
            "stats-only raw realloc must not activate semantic lifecycle ownership"
        );

        let moved_layout = Layout::from_size_align(moved_size, layout.align()).unwrap();
        unsafe {
            GlobalAlloc::dealloc(&alloc, moved, moved_layout);
        }

        let aligned_layout = Layout::from_size_align(80, align_of::<usize>()).unwrap();
        let aligned_ptr = unsafe { GlobalAlloc::alloc(&alloc, aligned_layout) };
        assert!(!aligned_ptr.is_null());
        unsafe {
            for offset in 0..aligned_layout.size() {
                aligned_ptr
                    .add(offset)
                    .write((offset as u8).wrapping_mul(23));
            }
        }
        let grown_layout = Layout::from_size_align(320, 64).unwrap();
        let grown = unsafe {
            core::alloc::Allocator::grow(
                &alloc,
                core::ptr::NonNull::new(aligned_ptr).unwrap(),
                aligned_layout,
                grown_layout,
            )
        }
        .expect("stats-only alignment-changing grow");
        let grown_ptr = grown.as_ptr() as *mut u8;
        assert_eq!(grown_ptr as usize % grown_layout.align(), 0);
        unsafe {
            for offset in 0..aligned_layout.size() {
                assert_eq!(
                    grown_ptr.add(offset).read(),
                    (offset as u8).wrapping_mul(23)
                );
            }
            core::alloc::Allocator::deallocate(
                &alloc,
                core::ptr::NonNull::new(grown_ptr).unwrap(),
                grown_layout,
            );
        }
        assert!(
            !global_address_lifecycle_tracking_active(),
            "stats-only alignment-changing grow must keep semantic lifecycle inactive"
        );
    }

    #[test]
    fn compiler_cache_hit_fuses_ownership_consume_with_lifecycle_publication() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            clear_auto_allocation_records();
        }
        semantic_auto_metadata_disable();
        semantic_stats_recording_disable();
        semantic_type_stats_recording_disable();

        let alloc = RustAllocator::new();
        let layout = Layout::from_size_align(3 * size_of::<usize>(), align_of::<usize>()).unwrap();
        let metadata = AllocationMetadata::for_type(0xC003_004F)
            .with_module(0xC0DE)
            .with_callsite(0xA110_C34F)
            .with_flags(FLAG_TYPE_ISOLATED);

        let ptr = unsafe { alloc.alloc_with_recovery_metadata(layout, metadata) };
        assert!(!ptr.is_null());
        assert_eq!(take_auto_deallocation_metadata(ptr, layout), Some(metadata));
        unsafe {
            alloc.dealloc_with_recovered_metadata(ptr, layout, metadata);
        }
        assert_eq!(unsafe { INLINE_TYPE_CACHE_ENTRY.ptr }, ptr);

        let before_strict = TEST_STRICT_ALLOCATION_PUBLICATIONS.load(Ordering::Relaxed);
        let before_semantic = TEST_SEMANTIC_ALLOCATION_PUBLICATIONS.load(Ordering::Relaxed);
        let before_probes = TEST_GLOBAL_ADDRESS_LIFECYCLE_TABLE_PROBES.load(Ordering::Relaxed);
        let reused = unsafe { alloc.alloc_with_recovery_metadata(layout, metadata) };
        let after_strict = TEST_STRICT_ALLOCATION_PUBLICATIONS.load(Ordering::Relaxed);
        let after_semantic = TEST_SEMANTIC_ALLOCATION_PUBLICATIONS.load(Ordering::Relaxed);
        let after_probes = TEST_GLOBAL_ADDRESS_LIFECYCLE_TABLE_PROBES.load(Ordering::Relaxed);
        assert_eq!(reused, ptr);
        assert_eq!(after_strict - before_strict, 0);
        assert_eq!(
            after_semantic - before_semantic,
            1,
            "a cache hit must retain its source-specific semantic lifecycle publication"
        );
        assert_eq!(
            after_probes - before_probes,
            0,
            "a cache hit must consume retained ownership and publish reuse in one table pass"
        );
        assert_eq!(
            take_auto_deallocation_metadata(reused, layout),
            Some(metadata)
        );
        unsafe {
            alloc.dealloc_raw(reused, layout);
            clear_type_cache_for_test();
            clear_auto_allocation_records();
        }
    }

