    #[cfg(not(feature = "fixed_heap"))]
    #[test]
    fn hosted_type_cache_aggregate_entry_budget_tracks_real_linked_owners() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            let layout =
                Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, align_of::<usize>()).unwrap();
            let retained = type_cache_retained_bytes_for_layout(layout);
            assert!(retained * MAX_TYPE_CACHE_DEPTH <= MAX_TYPE_CACHE_SLOT_BYTES);
            assert!(
                retained * MAX_PLAIN_TYPE_CACHE_RETAINED_ENTRIES
                    <= MAX_PLAIN_TYPE_CACHE_RETAINED_BYTES
            );
            let identities = [
                AllocationMetadata::for_type(0xC003_52F0).with_flags(FLAG_TYPE_ISOLATED),
                AllocationMetadata::for_type(0xC003_52F1).with_flags(FLAG_TYPE_ISOLATED),
                AllocationMetadata::for_type(0xC003_52F2).with_flags(FLAG_TYPE_ISOLATED),
                AllocationMetadata::for_type(0xC003_52F3).with_flags(FLAG_TYPE_ISOLATED),
            ];
            let mut storage: Vec<[usize; TYPE_CACHE_NODE_WORDS]> = (0
                ..=MAX_PLAIN_TYPE_CACHE_RETAINED_ENTRIES)
                .map(|_| [0usize; TYPE_CACHE_NODE_WORDS])
                .collect();
            let mut next = 0usize;

            for metadata in identities {
                for _ in 0..MAX_TYPE_CACHE_DEPTH {
                    assert!(push_type_cache(
                        storage[next].as_mut_ptr() as *mut u8,
                        layout,
                        metadata,
                    ));
                    next += 1;
                }
            }
            assert_eq!(next, MAX_PLAIN_TYPE_CACHE_RETAINED_ENTRIES);
            assert_eq!(
                plain_type_cache_retained_entries_snapshot_for_test(),
                MAX_PLAIN_TYPE_CACHE_RETAINED_ENTRIES
            );
            assert_eq!(
                plain_type_cache_retained_bytes_snapshot_for_test(),
                retained * MAX_PLAIN_TYPE_CACHE_RETAINED_ENTRIES
            );
            assert!(plain_type_cache_retained_bytes_trusted_for_test());

            let overflow_metadata = (0xC003_5300u64..)
                .map(|type_id| AllocationMetadata::for_type(type_id).with_flags(FLAG_TYPE_ISOLATED))
                .find(|metadata| {
                    let cache_key = type_cache_identity_key(*metadata);
                    let slot_key = plain_type_cache_slot_key(cache_key, layout);
                    type_cache_find_slot_for_key(slot_key, layout, *metadata, true)
                        .map(|slot| (*slot).count == 0)
                        .unwrap_or(false)
                })
                .expect("the 64-slot table must have an empty slot outside four hot identities");
            let overflow_ptr = storage[next].as_mut_ptr() as *mut u8;
            assert_eq!(
                try_push_type_cache_eligible_with_key(
                    overflow_ptr,
                    layout,
                    overflow_metadata,
                    type_cache_identity_key(overflow_metadata),
                ),
                Err(TypeCacheAdmissionRejection::AggregateEntryBudget)
            );

            let released = pop_type_cache(layout, identities[0]).expect("full hot slot must pop");
            assert_eq!(
                plain_type_cache_retained_entries_snapshot_for_test(),
                MAX_PLAIN_TYPE_CACHE_RETAINED_ENTRIES - 1
            );
            assert!(push_type_cache(overflow_ptr, layout, overflow_metadata));
            assert_eq!(
                plain_type_cache_retained_entries_snapshot_for_test(),
                MAX_PLAIN_TYPE_CACHE_RETAINED_ENTRIES
            );
            assert_eq!(
                pop_type_cache(layout, overflow_metadata),
                Some(overflow_ptr)
            );

            let released_index = storage
                .iter()
                .position(|node| node.as_ptr() as *mut u8 == released)
                .expect("popped node belongs to stable test storage");
            assert!(released_index < MAX_PLAIN_TYPE_CACHE_RETAINED_ENTRIES);
            for (identity_index, metadata) in identities.iter().copied().enumerate() {
                let expected = if identity_index == 0 {
                    MAX_TYPE_CACHE_DEPTH - 1
                } else {
                    MAX_TYPE_CACHE_DEPTH
                };
                for _ in 0..expected {
                    assert!(pop_type_cache(layout, metadata).is_some());
                }
                assert!(pop_type_cache(layout, metadata).is_none());
            }
            assert_eq!(plain_type_cache_retained_entries_snapshot_for_test(), 0);
            assert_eq!(plain_type_cache_retained_bytes_snapshot_for_test(), 0);
        }
    }

    #[cfg(all(feature = "stats", not(feature = "fixed_heap")))]
    #[test]
    fn hosted_registry_retention_cap_preempts_plain_aggregate_overflow() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
        }
        semantic_auto_metadata_disable();
        semantic_stats_reset();

        let alloc = RustAllocator::new();
        // Keep the aggregate linked-entry regression independent from the
        // bounded direct tier, whose eight owners have separate cap coverage.
        let layout = Layout::from_size_align(3 * size_of::<usize>(), align_of::<usize>()).unwrap();
        let mut identities = Vec::with_capacity(4);
        let mut next_type = 0xC003_5340u64;

        for identity_index in 0..4 {
            let metadata = loop {
                let candidate =
                    AllocationMetadata::for_type(next_type).with_flags(FLAG_TYPE_ISOLATED);
                next_type = next_type.wrapping_add(1);
                let cache_key = type_cache_identity_key(candidate);
                let slot_key = plain_type_cache_slot_key(cache_key, layout);
                if unsafe {
                    type_cache_find_slot_for_key(slot_key, layout, candidate, true)
                        .map(|slot| (*slot).count == 0)
                        .unwrap_or(false)
                } {
                    break candidate;
                }
            };
            let object_count = MAX_TYPE_CACHE_DEPTH + usize::from(identity_index == 0);
            let mut ptrs = Vec::with_capacity(object_count);
            for _ in 0..object_count {
                let ptr = unsafe { alloc.alloc_with_no_recovery_metadata(layout, metadata) };
                assert!(!ptr.is_null());
                ptrs.push(ptr);
            }
            for ptr in ptrs {
                unsafe {
                    alloc.dealloc_with_metadata(ptr, layout, metadata);
                }
            }
            identities.push((metadata, object_count));
        }

        let initial_offers = identities
            .iter()
            .map(|(_, object_count)| *object_count)
            .sum::<usize>();
        assert_eq!(
            unsafe { plain_type_cache_retained_entries_snapshot_for_test() },
            GLOBAL_TYPE_CACHE_OWNERSHIP_RETENTION_LIMIT - 1,
            "one retained owner uses the separate inline plain-cache entry"
        );
        assert!(unsafe { !INLINE_TYPE_CACHE_ENTRY.is_empty() });
        assert_eq!(
            GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire),
            GLOBAL_TYPE_CACHE_OWNERSHIP_RETENTION_LIMIT
        );
        let initial_admission = type_cache_admission_stats_snapshot();
        assert_eq!(
            initial_admission.admitted.events,
            GLOBAL_TYPE_CACHE_OWNERSHIP_RETENTION_LIMIT
        );
        assert_eq!(
            initial_admission.rejected_registry_pressure.events,
            initial_offers - GLOBAL_TYPE_CACHE_OWNERSHIP_RETENTION_LIMIT
        );
        assert_eq!(initial_admission.depot_attempts.events, 0);
        assert_eq!(initial_admission.depot_current_entries, 0);

        let overflow_metadata = loop {
            let candidate = AllocationMetadata::for_type(next_type).with_flags(FLAG_TYPE_ISOLATED);
            next_type = next_type.wrapping_add(1);
            let cache_key = type_cache_identity_key(candidate);
            let slot_key = plain_type_cache_slot_key(cache_key, layout);
            if unsafe {
                type_cache_find_slot_for_key(slot_key, layout, candidate, true)
                    .map(|slot| (*slot).count == 0)
                    .unwrap_or(false)
            } {
                break candidate;
            }
        };
        let overflow_ptr =
            unsafe { alloc.alloc_with_no_recovery_metadata(layout, overflow_metadata) };
        assert!(!overflow_ptr.is_null());
        unsafe {
            alloc.dealloc_with_metadata(overflow_ptr, layout, overflow_metadata);
        }

        let admission = type_cache_admission_stats_snapshot();
        assert_eq!(admission.rejected_aggregate_entry_budget.events, 0);
        assert_eq!(
            admission.rejected_registry_pressure.events,
            initial_offers + 1 - GLOBAL_TYPE_CACHE_OWNERSHIP_RETENTION_LIMIT
        );
        assert_eq!(admission.ownership_registry_full_failstop.events, 0);
        assert_eq!(admission.depot_from_aggregate_entry_budget.events, 0);
        assert_eq!(admission.depot_attempts.events, 0);
        assert_eq!(admission.depot_inserts.events, 0);
        assert_eq!(admission.depot_rescued_overflow.events, 0);
        assert_eq!(admission.depot_rejected_registry_headroom.events, 0);
        assert_eq!(admission.depot_current_entries, 0);
        assert_eq!(admission.depot_hits.events, 0);
        assert_eq!(
            GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire),
            GLOBAL_TYPE_CACHE_OWNERSHIP_RETENTION_LIMIT
        );
        assert_eq!(
            unsafe { pop_semantic_type_cache(layout, overflow_metadata) },
            None
        );

        let mut recovered = 0usize;
        for (metadata, _) in identities {
            while let Some(ptr) = unsafe { pop_semantic_type_cache(layout, metadata) } {
                recovered += 1;
                unsafe {
                    alloc.dealloc_raw(ptr, layout);
                }
            }
        }
        assert_eq!(recovered, GLOBAL_TYPE_CACHE_OWNERSHIP_RETENTION_LIMIT);
        assert_eq!(
            unsafe { plain_type_cache_retained_entries_snapshot_for_test() },
            0
        );
        assert_eq!(GLOBAL_TYPE_CACHE_OWNERSHIP_COUNT.load(Ordering::Acquire), 0);
        semantic_stats_recording_disable();
    }

    #[test]
    fn type_cache_aggregate_byte_budget_rejects_cross_slot_overflow() {
        const QUARTER_SLOT_WORDS: usize =
            (MAX_TYPE_CACHE_SLOT_BYTES / 4) / core::mem::size_of::<usize>();

        let _guard = test_guard();
        let mut storage: Vec<Box<[usize; QUARTER_SLOT_WORDS]>> = Vec::new();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();

            let layout = Layout::from_size_align(
                QUARTER_SLOT_WORDS * core::mem::size_of::<usize>(),
                align_of::<usize>(),
            )
            .unwrap();
            let retained = type_cache_retained_bytes_for_layout(layout);
            assert!(retained > 0);
            assert!(retained <= MAX_TYPE_CACHE_SLOT_BYTES);
            assert_eq!(MAX_PLAIN_TYPE_CACHE_RETAINED_BYTES % retained, 0);
            let fit_entries = MAX_PLAIN_TYPE_CACHE_RETAINED_BYTES / retained;
            assert!(
                fit_entries > 1 && fit_entries < MAX_PLAIN_TYPE_CACHE_RETAINED_ENTRIES,
                "test must fill the aggregate byte budget before the ownership-entry cap"
            );

            let mut accepted = 0usize;
            let mut next_type = 0xC003_5300u64;
            let mut attempts = 0usize;
            while accepted < fit_entries {
                assert!(
                    attempts < 16_384,
                    "test should find enough insertable cache keys"
                );
                storage.push(Box::new([0usize; QUARTER_SLOT_WORDS]));
                let ptr = storage.last_mut().unwrap().as_mut_ptr() as *mut u8;
                let metadata =
                    AllocationMetadata::for_type(next_type).with_flags(FLAG_TYPE_ISOLATED);
                next_type = next_type.wrapping_add(1);
                attempts += 1;
                if push_type_cache(ptr, layout, metadata) {
                    accepted += 1;
                } else {
                    storage.pop();
                }
            }

            let before_overflow = type_isolation_side_cache_snapshot();
            assert!(
                before_overflow.retained_bytes <= MAX_PLAIN_TYPE_CACHE_RETAINED_BYTES,
                "accepted entries must stay within the aggregate budget"
            );
            assert_eq!(
                before_overflow.retained_bytes, MAX_PLAIN_TYPE_CACHE_RETAINED_BYTES,
                "the aggregate counter must admit exactly the 512 KiB cap"
            );
            assert_eq!(
                plain_type_cache_retained_bytes_snapshot_for_test(),
                MAX_PLAIN_TYPE_CACHE_RETAINED_BYTES
            );
            assert!(plain_type_cache_retained_bytes_trusted_for_test());
            assert_eq!(PLAIN_TYPE_CACHE_AGGREGATE_SCANS.load(Ordering::Relaxed), 1);
            assert!(
                before_overflow.retained_bytes.saturating_add(retained)
                    > MAX_PLAIN_TYPE_CACHE_RETAINED_BYTES,
                "one more object must overflow the aggregate budget"
            );

            let mut overflow_accepted = false;
            let mut overflow_attempts = 0usize;
            while overflow_attempts < 16_384 {
                storage.push(Box::new([0usize; QUARTER_SLOT_WORDS]));
                let ptr = storage.last_mut().unwrap().as_mut_ptr() as *mut u8;
                let metadata =
                    AllocationMetadata::for_type(next_type).with_flags(FLAG_TYPE_ISOLATED);
                next_type = next_type.wrapping_add(1);
                overflow_attempts += 1;
                let before = type_isolation_side_cache_snapshot().retained_bytes;
                if push_type_cache(ptr, layout, metadata) {
                    overflow_accepted = true;
                    break;
                }
                storage.pop();
                assert_eq!(
                    type_isolation_side_cache_snapshot().retained_bytes,
                    before,
                    "a rejected aggregate-budget push must not mutate retained bytes"
                );
            }

            assert!(
                !overflow_accepted,
                "plain semantic type-cache retention must be capped across distinct slots"
            );
            assert!(
                type_isolation_side_cache_snapshot().retained_bytes
                    <= MAX_PLAIN_TYPE_CACHE_RETAINED_BYTES
            );
            assert_eq!(PLAIN_TYPE_CACHE_AGGREGATE_SCANS.load(Ordering::Relaxed), 1);
        }
    }

    #[test]
    fn plain_type_cache_inline_replacement_respects_aggregate_byte_cap() {
        const QUARTER_SLOT_WORDS: usize =
            (MAX_TYPE_CACHE_SLOT_BYTES / 4) / core::mem::size_of::<usize>();
        const MAX_OBJECT_WORDS: usize = MAX_TYPE_CACHE_OBJECT_SIZE / core::mem::size_of::<usize>();

        let _guard = test_guard();
        let mut cold_storage: Vec<Box<[usize; QUARTER_SLOT_WORDS]>> = Vec::new();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();

            let mut small_inline_storage = [0usize; TYPE_CACHE_NODE_WORDS];
            let small_layout =
                Layout::from_size_align(size_of_val(&small_inline_storage), align_of::<usize>())
                    .unwrap();
            let small_metadata =
                AllocationMetadata::for_type(0xC003_5311).with_flags(FLAG_TYPE_ISOLATED);
            let small_cache_key = type_cache_identity_key(small_metadata);
            let small_ptr = small_inline_storage.as_mut_ptr() as *mut u8;
            assert!(push_inline_type_cache_eligible_with_key(
                small_ptr,
                small_layout,
                small_metadata,
                small_cache_key,
            ));

            let cold_layout = Layout::from_size_align(
                QUARTER_SLOT_WORDS * core::mem::size_of::<usize>(),
                align_of::<usize>(),
            )
            .unwrap();
            let cold_retained = type_cache_retained_bytes_for_layout(cold_layout);
            let mut next_type = 0xC003_5312u64;
            let mut attempts = 0usize;
            while type_isolation_side_cache_snapshot()
                .retained_bytes
                .saturating_add(cold_retained)
                <= MAX_PLAIN_TYPE_CACHE_RETAINED_BYTES
            {
                assert!(attempts < 16_384, "test should find enough cold cache keys");
                cold_storage.push(Box::new([0usize; QUARTER_SLOT_WORDS]));
                let ptr = cold_storage.last_mut().unwrap().as_mut_ptr() as *mut u8;
                let metadata =
                    AllocationMetadata::for_type(next_type).with_flags(FLAG_TYPE_ISOLATED);
                next_type = next_type.wrapping_add(1);
                attempts += 1;
                if !push_type_cache(ptr, cold_layout, metadata) {
                    cold_storage.pop();
                }
            }

            let with_small_inline = type_isolation_side_cache_snapshot();
            assert!(with_small_inline.inline_occupied);
            assert!(with_small_inline.retained_bytes <= MAX_PLAIN_TYPE_CACHE_RETAINED_BYTES);
            assert!(
                with_small_inline
                    .retained_bytes
                    .saturating_add(cold_retained)
                    > MAX_PLAIN_TYPE_CACHE_RETAINED_BYTES,
                "cold slots should be filled to the last aggregate-sized step"
            );
            assert_eq!(
                pop_inline_type_cache_eligible_with_key(
                    small_layout,
                    small_metadata,
                    small_cache_key,
                ),
                Some(small_ptr)
            );

            let cold_only = type_isolation_side_cache_snapshot();
            assert!(!cold_only.inline_occupied);
            assert_eq!(
                cold_only.retained_bytes,
                plain_type_cache_retained_bytes_snapshot_for_test()
            );

            let mut larger_inline_storage = Box::new([0usize; MAX_OBJECT_WORDS]);
            let larger_layout =
                Layout::from_size_align(size_of_val(&*larger_inline_storage), align_of::<usize>())
                    .unwrap();
            let larger_retained = type_cache_retained_bytes_for_layout(larger_layout);
            assert!(
                cold_only.retained_bytes.saturating_add(larger_retained)
                    > MAX_PLAIN_TYPE_CACHE_RETAINED_BYTES,
                "the replacement inline candidate must exceed the remaining aggregate headroom"
            );
            let larger_metadata =
                AllocationMetadata::for_type(next_type).with_flags(FLAG_TYPE_ISOLATED);
            assert!(
                !push_plain_semantic_type_cache_eligible(
                    larger_inline_storage.as_mut_ptr() as *mut u8,
                    larger_layout,
                    larger_metadata,
                ),
                "an empty inline slot must not bypass the aggregate byte cap"
            );

            let after_rejection = type_isolation_side_cache_snapshot();
            assert!(!after_rejection.inline_occupied);
            assert_eq!(after_rejection.retained_bytes, cold_only.retained_bytes);
            assert!(after_rejection.retained_bytes <= MAX_PLAIN_TYPE_CACHE_RETAINED_BYTES);
            assert_eq!(
                plain_type_cache_retained_bytes_snapshot_for_test(),
                cold_only.retained_bytes
            );
            assert!(plain_type_cache_retained_bytes_trusted_for_test());
            assert_eq!(PLAIN_TYPE_CACHE_AGGREGATE_SCANS.load(Ordering::Relaxed), 1);
        }
    }

    #[test]
    fn segregated_type_cache_retained_bytes_counter_tracks_push_and_pop() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            let metadata = AllocationMetadata::for_type(0xC003_520A)
                .with_flags(FLAG_TYPE_ISOLATED | FLAG_METADATA_SEGREGATED);
            let cache_key = type_cache_identity_key(metadata);
            let identity = TypeCacheIdentity::from_metadata(metadata);
            let policy_key = segregated_type_cache_policy_key(metadata);
            let mut small_storage = [0usize; TYPE_CACHE_NODE_WORDS];
            let mut large_storage = [0usize; TYPE_CACHE_NODE_WORDS * 2];
            let small =
                Layout::from_size_align(size_of_val(&small_storage), align_of::<usize>()).unwrap();
            let large =
                Layout::from_size_align(size_of_val(&large_storage), align_of::<usize>()).unwrap();
            let small_retained = type_cache_retained_bytes_for_layout(small);
            let large_retained = type_cache_retained_bytes_for_layout(large);
            let small_ptr = small_storage.as_mut_ptr() as *mut u8;
            let large_ptr = large_storage.as_mut_ptr() as *mut u8;
            let mut bucket = SegregatedTypeCacheBucket::empty();

            assert!(bucket
                .push(SegregatedTypeCacheEntry::new(
                    cache_key, policy_key, small_ptr, small, metadata,
                ))
                .is_none());
            assert_eq!(bucket.count, 1);
            assert_eq!(bucket.retained_bytes, small_retained);
            assert_eq!(bucket.retained_bytes(), Some(small_retained));

            assert!(bucket
                .push(SegregatedTypeCacheEntry::new(
                    cache_key, policy_key, large_ptr, large, metadata,
                ))
                .is_none());
            assert_eq!(bucket.count, 2);
            assert_eq!(bucket.retained_bytes, small_retained + large_retained);
            assert_eq!(
                bucket.retained_bytes(),
                Some(small_retained + large_retained)
            );

            let popped_large = bucket
                .pop(large, identity, cache_key, policy_key)
                .expect("large entry should be reusable");
            assert_eq!(popped_large.ptr, large_ptr);
            assert_eq!(bucket.count, 1);
            assert_eq!(bucket.retained_bytes, small_retained);
            assert_eq!(bucket.retained_bytes(), Some(small_retained));

            let popped_small = bucket
                .pop(small, identity, cache_key, policy_key)
                .expect("small entry should be reusable");
            assert_eq!(popped_small.ptr, small_ptr);
            assert_eq!(bucket.count, 0);
            assert_eq!(bucket.retained_bytes, 0);
            assert_eq!(bucket.retained_bytes(), Some(0));
        }
    }

    #[test]
    fn segregated_type_cache_retained_bytes_use_allocator_rounded_size() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            let metadata = AllocationMetadata::for_type(0xC003_5212)
                .with_flags(FLAG_TYPE_ISOLATED | FLAG_METADATA_SEGREGATED);
            let cache_key = type_cache_identity_key(metadata);
            let identity = TypeCacheIdentity::from_metadata(metadata);
            let policy_key = segregated_type_cache_policy_key(metadata);
            let mut storage = [0usize; TYPE_CACHE_NODE_WORDS + 4];
            let layout = first_unrounded_type_cache_layout_for_test();
            assert!(
                layout.size() <= size_of_val(&storage),
                "test storage must cover the requested unrounded layout"
            );
            let retained = type_cache_retained_bytes_for_layout(layout);
            assert!(
                retained > layout.size(),
                "test layout must exercise internal-fragmentation accounting"
            );
            let ptr = storage.as_mut_ptr() as *mut u8;
            let mut bucket = SegregatedTypeCacheBucket::empty();

            assert!(bucket
                .push(SegregatedTypeCacheEntry::new(
                    cache_key, policy_key, ptr, layout, metadata,
                ))
                .is_none());
            assert_eq!(bucket.count, 1);
            assert_eq!(bucket.retained_bytes, retained);
            assert_eq!(bucket.retained_bytes(), Some(retained));
            assert!(bucket.can_accept_object_size(layout.size()));

            let popped = bucket
                .pop(layout, identity, cache_key, policy_key)
                .expect("rounded-accounted entry should still match by exact layout");
            assert_eq!(popped.ptr, ptr);
            assert_eq!(bucket.count, 0);
            assert_eq!(bucket.retained_bytes, 0);
            assert_eq!(bucket.retained_bytes(), Some(0));
        }
    }

    #[test]
    fn segregated_type_cache_bucket_byte_budget_allows_replacement_but_rejects_growth() {
        const ENTRY_WORDS: usize = (MAX_SEGREGATED_TYPE_CACHE_BUCKET_BYTES
            / SEGREGATED_TYPE_CACHE_DEPTH)
            / core::mem::size_of::<usize>();
        const LARGER_ENTRY_WORDS: usize =
            (MAX_SEGREGATED_TYPE_CACHE_BUCKET_BYTES / 2) / core::mem::size_of::<usize>();

        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            let metadata = AllocationMetadata::for_type(0xC003_5209)
                .with_flags(FLAG_TYPE_ISOLATED | FLAG_METADATA_SEGREGATED);
            let small_layout =
                Layout::from_size_align(ENTRY_WORDS * size_of::<usize>(), align_of::<usize>())
                    .unwrap();
            let large_layout = Layout::from_size_align(
                LARGER_ENTRY_WORDS * size_of::<usize>(),
                align_of::<usize>(),
            )
            .unwrap();
            let mut storage = [[0usize; ENTRY_WORDS]; SEGREGATED_TYPE_CACHE_DEPTH];
            let mut replacement = [0usize; ENTRY_WORDS];
            let mut bucket = SegregatedTypeCacheBucket::empty();

            for item in storage.iter_mut() {
                let ptr = item.as_mut_ptr() as *mut u8;
                assert!(bucket
                    .push(SegregatedTypeCacheEntry::new(
                        type_cache_identity_key(metadata),
                        segregated_type_cache_policy_key(metadata),
                        ptr,
                        small_layout,
                        metadata,
                    ))
                    .is_none());
            }

            assert_eq!(
                bucket.retained_bytes(),
                Some(MAX_SEGREGATED_TYPE_CACHE_BUCKET_BYTES)
            );
            assert_eq!(
                bucket.retained_bytes,
                MAX_SEGREGATED_TYPE_CACHE_BUCKET_BYTES
            );
            assert!(
                bucket.can_accept_object_size(small_layout.size()),
                "a same-size push can evict one full bucket entry without growing retained bytes"
            );
            let replacement_ptr = replacement.as_mut_ptr() as *mut u8;
            let evicted = bucket
                .push(SegregatedTypeCacheEntry::new(
                    type_cache_identity_key(metadata),
                    segregated_type_cache_policy_key(metadata),
                    replacement_ptr,
                    small_layout,
                    metadata,
                ))
                .expect("same-size replacement should evict one entry from the full bucket");
            assert!(!evicted.ptr.is_null());
            assert_eq!(
                bucket.retained_bytes,
                MAX_SEGREGATED_TYPE_CACHE_BUCKET_BYTES
            );
            assert_eq!(
                bucket.retained_bytes(),
                Some(MAX_SEGREGATED_TYPE_CACHE_BUCKET_BYTES)
            );
            assert!(
                !bucket.can_accept_object_size(large_layout.size()),
                "a larger replacement would exceed the bucket byte budget"
            );
        }
    }

    #[test]
    fn metadata_segregated_full_bucket_projection_authenticates_eviction_candidate() {
        const ENTRY_WORDS: usize = (MAX_SEGREGATED_TYPE_CACHE_BUCKET_BYTES
            / SEGREGATED_TYPE_CACHE_DEPTH)
            / core::mem::size_of::<usize>();

        #[derive(Clone, Copy, Debug)]
        enum Tamper {
            SizeBeforeReplacement,
            StructuralAuthBeforeRejection,
        }

        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
        }

        for tamper in [
            Tamper::SizeBeforeReplacement,
            Tamper::StructuralAuthBeforeRejection,
        ] {
            let metadata = AllocationMetadata::for_type(0xC003_5213)
                .with_flags(FLAG_TYPE_ISOLATED | FLAG_METADATA_SEGREGATED);
            let cache_key = type_cache_identity_key(metadata);
            let policy_key = segregated_type_cache_policy_key(metadata);
            let layout =
                Layout::from_size_align(ENTRY_WORDS * size_of::<usize>(), align_of::<usize>())
                    .unwrap();
            let mut storage = [[0usize; ENTRY_WORDS]; SEGREGATED_TYPE_CACHE_DEPTH];
            let mut bucket = SegregatedTypeCacheBucket::empty();

            for item in storage.iter_mut() {
                assert!(bucket
                    .push(SegregatedTypeCacheEntry::new(
                        cache_key,
                        policy_key,
                        item.as_mut_ptr() as *mut u8,
                        layout,
                        metadata,
                    ))
                    .is_none());
            }
            assert_eq!(bucket.count, SEGREGATED_TYPE_CACHE_DEPTH);

            let incoming_size = match tamper {
                Tamper::SizeBeforeReplacement => {
                    bucket.entries[bucket.evict_cursor].size += size_of::<usize>();
                    layout.size()
                }
                Tamper::StructuralAuthBeforeRejection => {
                    bucket.entries[bucket.evict_cursor].structural_auth ^= 1;
                    MAX_SEGREGATED_TYPE_CACHE_BUCKET_BYTES
                }
            };

            let rejected = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let _ = segregated_type_cache_projected_aggregate_retained_bytes(
                    bucket.retained_bytes,
                    bucket,
                    incoming_size,
                );
            }));
            assert!(
                rejected.is_err(),
                "full-bucket {:?} must authenticate before capacity projection",
                tamper,
            );
        }
    }

    #[test]
    fn segregated_type_cache_aggregate_byte_budget_rejects_cross_bucket_overflow() {
        const QUARTER_BUCKET_WORDS: usize =
            (MAX_SEGREGATED_TYPE_CACHE_BUCKET_BYTES / 4) / core::mem::size_of::<usize>();

        let _guard = test_guard();
        let mut storage: Vec<Box<[usize; QUARTER_BUCKET_WORDS]>> = Vec::new();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();

            let layout = Layout::from_size_align(
                QUARTER_BUCKET_WORDS * core::mem::size_of::<usize>(),
                align_of::<usize>(),
            )
            .unwrap();
            let retained = type_cache_retained_bytes_for_layout(layout);
            assert!(retained > 0);
            assert!(retained <= MAX_SEGREGATED_TYPE_CACHE_BUCKET_BYTES);

            let mut next_type = 0xC003_5400u64;
            let mut attempts = 0usize;
            while metadata_segregation_side_cache_snapshot()
                .retained_bytes
                .saturating_add(retained)
                <= MAX_SEGREGATED_TYPE_CACHE_RETAINED_BYTES
            {
                assert!(
                    attempts < 16_384,
                    "test should find enough insertable segregated cache keys"
                );
                let metadata = AllocationMetadata::for_type(next_type)
                    .with_flags(FLAG_TYPE_ISOLATED | FLAG_METADATA_SEGREGATED);
                next_type = next_type.wrapping_add(1);
                attempts += 1;
                if !INLINE_SEGREGATED_TYPE_CACHE_ENTRY.is_empty()
                    && !metadata_segregated_growth_bucket_available_for_test(layout, metadata)
                {
                    continue;
                }

                storage.push(Box::new([0usize; QUARTER_BUCKET_WORDS]));
                let ptr = storage.last_mut().unwrap().as_mut_ptr() as *mut u8;
                match push_segregated_type_cache(ptr, layout, metadata) {
                    Ok(evicted) => {
                        assert!(
                            evicted.is_none(),
                            "budget-fill phase should grow into empty buckets, not replace"
                        );
                    }
                    Err(()) => {
                        storage.pop();
                    }
                }
            }

            let before_overflow = metadata_segregation_side_cache_snapshot();
            assert!(
                before_overflow.retained_bytes <= MAX_SEGREGATED_TYPE_CACHE_RETAINED_BYTES,
                "accepted entries must stay within the aggregate budget"
            );
            assert!(
                before_overflow.retained_bytes.saturating_add(retained)
                    > MAX_SEGREGATED_TYPE_CACHE_RETAINED_BYTES,
                "one more side-cache object must overflow the aggregate budget"
            );

            let mut overflow_accepted = false;
            let mut overflow_attempts = 0usize;
            while overflow_attempts < 16_384 {
                let metadata = AllocationMetadata::for_type(next_type)
                    .with_flags(FLAG_TYPE_ISOLATED | FLAG_METADATA_SEGREGATED);
                next_type = next_type.wrapping_add(1);
                overflow_attempts += 1;
                if !metadata_segregated_growth_bucket_available_for_test(layout, metadata) {
                    continue;
                }

                storage.push(Box::new([0usize; QUARTER_BUCKET_WORDS]));
                let ptr = storage.last_mut().unwrap().as_mut_ptr() as *mut u8;
                let before = metadata_segregation_side_cache_snapshot().retained_bytes;
                match push_segregated_type_cache(ptr, layout, metadata) {
                    Ok(evicted) => {
                        assert!(
                            evicted.is_none(),
                            "overflow candidate should have had an empty growth bucket"
                        );
                        overflow_accepted = true;
                        break;
                    }
                    Err(()) => {
                        storage.pop();
                        assert_eq!(
                            metadata_segregation_side_cache_snapshot().retained_bytes,
                            before,
                            "a rejected aggregate-budget push must not mutate retained bytes"
                        );
                    }
                }
            }

            assert!(
                !overflow_accepted,
                "metadata-segregated cache retention must be capped across distinct buckets"
            );
            assert!(
                metadata_segregation_side_cache_snapshot().retained_bytes
                    <= MAX_SEGREGATED_TYPE_CACHE_RETAINED_BYTES
            );
        }
    }

    #[test]
    fn type_cache_rejects_pointer_without_usize_node_alignment() {
        let _guard = test_guard();
        unsafe {
            if TYPE_CACHE_NODE_ALIGN <= 4 {
                return;
            }
            clear_type_cache_for_test();
            let mut storage = [0u8; MIN_TYPE_CACHE_OBJECT_SIZE + 2 * TYPE_CACHE_NODE_ALIGN];
            let base = storage.as_mut_ptr() as usize;
            let aligned = (base + TYPE_CACHE_NODE_ALIGN - 1) & !(TYPE_CACHE_NODE_ALIGN - 1);
            let ptr = (aligned + TYPE_CACHE_NODE_ALIGN / 2) as *mut u8;
            let layout = Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, 4).unwrap();
            let metadata = AllocationMetadata::for_type(90);

            assert_eq!((ptr as usize) & (layout.align() - 1), 0);
            assert_ne!((ptr as usize) & (TYPE_CACHE_NODE_ALIGN - 1), 0);
            assert!(!push_type_cache(ptr, layout, metadata));
            assert_eq!(pop_type_cache(layout, metadata), None);
        }
    }

    #[test]
    fn type_cache_rejects_word_aligned_pointer_below_requested_layout_alignment() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            let requested_align = TYPE_CACHE_NODE_ALIGN * 2;
            let mut storage = [0xA5u8; MIN_TYPE_CACHE_OBJECT_SIZE + 4 * TYPE_CACHE_NODE_ALIGN];
            let before = storage;
            let base = storage.as_mut_ptr() as usize;
            let requested_aligned = (base + requested_align - 1) & !(requested_align - 1);
            let ptr = (requested_aligned + TYPE_CACHE_NODE_ALIGN) as *mut u8;
            let layout =
                Layout::from_size_align(MIN_TYPE_CACHE_OBJECT_SIZE, requested_align).unwrap();
            let metadata = AllocationMetadata::for_type(0xC003_A110);

            assert_eq!((ptr as usize) & (TYPE_CACHE_NODE_ALIGN - 1), 0);
            assert_ne!((ptr as usize) & (layout.align() - 1), 0);
            assert!(!push_type_cache(ptr, layout, metadata));
            assert_eq!(
                storage, before,
                "rejected admission must not write a link word"
            );
            assert_eq!(pop_type_cache(layout, metadata), None);
        }
    }

    #[test]
    fn delayed_free_defers_type_cache_reuse_until_eviction() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
            let mut backing = [[0usize; TYPE_CACHE_NODE_WORDS]; DELAYED_FREE_SLOTS + 1];
            let layout =
                Layout::from_size_align(size_of_val(&backing[0]), align_of::<usize>()).unwrap();
            let metadata =
                AllocationMetadata::for_type(99).with_flags(FLAG_TYPE_ISOLATED | FLAG_DELAYED_FREE);

            for slot in backing.iter_mut().take(DELAYED_FREE_SLOTS) {
                assert!(enqueue_delayed_free(
                    &RustAllocator::new(),
                    slot.as_mut_ptr() as *mut u8,
                    layout,
                    metadata
                )
                .is_none());
            }
            assert_eq!(
                pop_semantic_type_cache(layout, metadata.with_flags(FLAG_TYPE_ISOLATED)),
                None
            );

            let evicted = enqueue_delayed_free(
                &RustAllocator::new(),
                backing[DELAYED_FREE_SLOTS].as_mut_ptr() as *mut u8,
                layout,
                metadata,
            )
            .expect("ring should evict the oldest delayed free");
            assert_eq!(evicted.ptr, backing[0].as_mut_ptr() as *mut u8);
            release_delayed_slot(&RustAllocator::new(), evicted);
            assert_eq!(
                pop_semantic_type_cache(layout, metadata.with_flags(FLAG_TYPE_ISOLATED)),
                Some(backing[0].as_mut_ptr() as *mut u8)
            );
        }
    }

    #[test]
    fn delayed_free_occupied_mask_tracks_slots_and_repairs_missing_bits() {
        let _guard = test_guard();
        let _cleanup = SemanticStateCleanup;
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();

            let mut first = [0usize; TYPE_CACHE_NODE_WORDS];
            let mut second = [0usize; TYPE_CACHE_NODE_WORDS];
            let mut larger = [0usize; TYPE_CACHE_NODE_WORDS + 1];
            let small_layout =
                Layout::from_size_align(size_of_val(&first), align_of::<usize>()).unwrap();
            let larger_layout =
                Layout::from_size_align(size_of_val(&larger), align_of::<usize>()).unwrap();
            let metadata = AllocationMetadata::for_type(0xD17A_0CC1)
                .with_flags(FLAG_TYPE_ISOLATED | FLAG_DELAYED_FREE);

            assert!(enqueue_delayed_free(
                &RustAllocator::new(),
                first.as_mut_ptr() as *mut u8,
                small_layout,
                metadata,
            )
            .is_none());
            assert!(enqueue_delayed_free(
                &RustAllocator::new(),
                second.as_mut_ptr() as *mut u8,
                small_layout,
                metadata,
            )
            .is_none());
            assert_eq!(
                DELAYED_FREE_OCCUPIED_MASK & 0b11,
                0b11,
                "the occupied mask should track normal enqueue slots"
            );

            let taken = delayed_free_take_slot(0);
            let taken_ownership_cleanup = PendingGlobalDelayedFreeOwnership::new(taken.ptr);
            assert_eq!(taken.ptr, first.as_mut_ptr() as *mut u8);
            assert!(
                global_delayed_free_contains_ptr(taken.ptr),
                "taking a delayed-free slot must retain process-visible ownership until the caller completes release"
            );
            assert_eq!(
                DELAYED_FREE_OCCUPIED_MASK & 0b11,
                0b10,
                "taking a delayed-free slot must clear only that slot bit"
            );

            assert!(enqueue_delayed_free(
                &RustAllocator::new(),
                larger.as_mut_ptr() as *mut u8,
                larger_layout,
                metadata,
            )
            .is_none());
            assert_eq!(
                DELAYED_FREE_OCCUPIED_MASK & 0b110,
                0b110,
                "the next cursor slot should be marked occupied"
            );

            DELAYED_FREE_OCCUPIED_MASK = 0b10;
            assert_eq!(
                delayed_free_largest_occupied_index(),
                Some(2),
                "a partially missing occupied-mask bit should trigger a slow repair scan and still find the largest retained slot"
            );
            assert_eq!(
                DELAYED_FREE_OCCUPIED_MASK & 0b110,
                0b110,
                "slow repair should rebuild the occupied mask from real slots"
            );

            drop(taken_ownership_cleanup);
            assert!(!global_delayed_free_contains_ptr(taken.ptr));
            clear_delayed_free_for_test();
            clear_type_cache_for_test();
        }
    }

    #[cfg(all(feature = "stats", not(feature = "fixed_heap")))]
    #[test]
    fn delayed_free_retained_byte_budget_evicts_old_large_real_objects() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
        }
        semantic_auto_metadata_disable();
        semantic_stats_reset();

        const OBJECTS: usize = 4;
        let alloc = RustAllocator::new();
        let layout =
            Layout::from_size_align(MAX_DELAYED_FREE_RETAINED_BYTES / 2, align_of::<usize>())
                .unwrap();
        let metadata = AllocationMetadata::for_type(0xD17A_0001)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_DELAYED_FREE);
        let mut ptrs = [core::ptr::null_mut(); OBJECTS];

        for ptr in ptrs.iter_mut() {
            *ptr = unsafe { alloc.alloc_with_metadata(layout, metadata) };
            assert!(!ptr.is_null());
        }
        for &ptr in ptrs.iter() {
            unsafe {
                alloc.dealloc_with_metadata(ptr, layout, metadata);
            }
            let snap = delayed_free_snapshot();
            assert_delayed_free_snapshot_accounting(snap);
            assert!(
                snap.retained_bytes <= MAX_DELAYED_FREE_RETAINED_BYTES,
                "delayed-free retained bytes must stay within the quarantine budget"
            );
        }

        let snap = delayed_free_snapshot();
        assert_delayed_free_snapshot_accounting(snap);
        assert_eq!(snap.occupied_slots, 2);
        assert_eq!(snap.retained_bytes, MAX_DELAYED_FREE_RETAINED_BYTES);

        let stats = semantic_stats_snapshot();
        assert_eq!(stats.delayed_free_enqueues, OBJECTS);
        assert_eq!(
            stats.delayed_free_flushes,
            OBJECTS - 2,
            "the third and fourth frees should evict older large delayed-free slots"
        );

        semantic_stats_recording_disable();
        unsafe {
            release_delayed_free_for_test(&alloc);
            clear_type_cache_for_test();
        }
    }

    #[cfg(all(feature = "stats", not(feature = "fixed_heap")))]
    #[test]
    fn delayed_free_multi_evicts_old_slots_to_retain_larger_real_object() {
        let _guard = test_guard();
        unsafe {
            clear_type_cache_for_test();
            clear_delayed_free_for_test();
        }
        semantic_auto_metadata_disable();
        semantic_stats_reset();

        const OLD_OBJECTS: usize = 3;
        let alloc = RustAllocator::new();
        let old_layout = Layout::from_size_align(
            MAX_TYPE_CACHE_OBJECT_SIZE + core::mem::size_of::<usize>(),
            align_of::<usize>(),
        )
        .unwrap();
        let incoming_layout =
            Layout::from_size_align(MAX_DELAYED_FREE_RETAINED_BYTES / 2, align_of::<usize>())
                .unwrap();
        let metadata = AllocationMetadata::for_type(0xD17A_0003)
            .with_flags(FLAG_TYPE_ISOLATED | FLAG_DELAYED_FREE);
        let mut old_ptrs = [core::ptr::null_mut(); OLD_OBJECTS];

        for ptr in old_ptrs.iter_mut() {
            *ptr = unsafe { alloc.alloc_with_metadata(old_layout, metadata) };
            assert!(!ptr.is_null());
        }
        let incoming = unsafe { alloc.alloc_with_metadata(incoming_layout, metadata) };
        assert!(!incoming.is_null());

        for &ptr in old_ptrs.iter() {
            unsafe {
                alloc.dealloc_with_metadata(ptr, old_layout, metadata);
            }
        }
        let before = delayed_free_snapshot();
        assert_delayed_free_snapshot_accounting(before);
        assert_eq!(before.occupied_slots, OLD_OBJECTS);
        assert_eq!(
            before.retained_bytes,
            OLD_OBJECTS * delayed_free_retained_bytes_for_layout(old_layout)
        );

        unsafe {
            alloc.dealloc_with_metadata(incoming, incoming_layout, metadata);
        }

        let after = delayed_free_snapshot();
        assert_delayed_free_snapshot_accounting(after);
        assert_eq!(
            after.occupied_slots, 2,
            "two old delayed slots must be evicted so the larger incoming object can be retained"
        );
        assert_eq!(
            after.retained_bytes,
            delayed_free_retained_bytes_for_layout(old_layout)
                + delayed_free_retained_bytes_for_layout(incoming_layout)
        );
        assert!(
            after.retained_bytes <= MAX_DELAYED_FREE_RETAINED_BYTES,
            "multi-eviction must preserve the delayed-free retained-byte cap"
        );

        let mut retained_old = 0usize;
        let mut retained_incoming = false;
        unsafe {
            for slot in delayed_free_slots_snapshot_for_test().iter() {
                if old_ptrs.iter().any(|&ptr| ptr == slot.ptr) {
                    retained_old += 1;
                }
                if slot.ptr == incoming {
                    retained_incoming = true;
                }
            }
        }
        assert_eq!(
            retained_old, 1,
            "largest-first multi-eviction should release two old oversized objects"
        );
        assert!(
            retained_incoming,
            "the incoming object should be quarantined instead of bypassing after multi-eviction"
        );

        let stats = semantic_stats_snapshot();
        assert_eq!(stats.delayed_free_enqueues, OLD_OBJECTS + 1);
        assert_eq!(stats.delayed_free_flushes, 2);

        semantic_stats_recording_disable();
        unsafe {
            release_delayed_free_for_test(&alloc);
            clear_type_cache_for_test();
        }
    }

